import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Акафіст Пресвятій Богородиці перед іконою «Феодорівська»","e":"Akathist to the Theotokos before her icon “Feodorovskaya”","secs":[{"h":"Кондак 1","ps":["Взбра́нней Воєво́ді, Пренепоро́чній Ді́ві Богоро́диці, Засту́пниці на́шей і Предста́тельству христия́н непости́дному, явле́нієм чу́дния іко́ни Своєя́ ра́дованіє пода́вшей земле́ Росси́йстій і вся ві́рная ча́да Це́ркве просвети́вшей, благодаре́ніє усе́рдно прино́сим Ті, Богоро́дице, і припа́дающе пречу́дному о́бразу Твоєму́, уми́льно глаго́лем: спаси́, Госпоже́, і поми́луй раби́ Твоя́, зову́щия:","Ра́дуйся, Ма́тер Бо́жия, Предста́тельнице і Засту́пнице на́ша усе́рдная."]},{"h":"Ікос 1","ps":["Арха́нгел Гавриї́л от Бо́га по́слан бисть во град Назаре́т ко Пречи́стій Ді́ві Марі́ї, і вшед к Ней рече́: Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю, благослове́нна Ти в жена́х. Арха́нгельському гла́су подража́юще, і ми, грі́шнії, ра́дости і благодаре́нія в се́рдці своє́м іспо́лнені, пред явле́нним о́бразом Твої́м благохвале́нія на́ша возноси́ти к Тебі́ дерза́єм, Пресвята́я Богоро́дице:","Ра́дуйся, о́трасле от ко́рене Дави́дова благослове́нная;","ра́дуйся, обі́том роди́телей в же́ртву Бо́гу принесе́нная.","Ра́дуйся, святи́х пра́ведних Іоаки́ма і А́нни Дщи Богода́нная;","ра́дуйся, тріє́х літ во храм Бо́жий введе́нная і та́мо воспита́нная.","Ра́дуйся, та́мо смире́нієм і чистото́ю всіх удиви́вшая;","ра́дуйся, та́мо арха́нгельськия бесі́ди сподо́бльшаяся.","Ра́дуйся, Ді́во, о зача́тії Бо́га Сло́ва благові́стіє во смире́нії приі́мшая;","ра́дуйся, ізбра́нная Отрокови́це, к зача́тію Бо́га Сло́ва си́лою сви́ше осіне́нная.","Ра́дуйся, та́йну воплоще́нія Си́на Бо́жия, от віко́во в Бо́зі сокрове́нную, откри́вшая;","ра́дуйся, А́гнице, ро́ждшая А́гнця Христа́, взе́мшаго гріхи́ ми́ра.","Ра́дуйся, Тобо́ю бо ізбавля́ємся мук а́дових;","ра́дуйся, Тобо́ю бо сподобля́ємся ві́чния жи́зні.","Ра́дуйся, Ма́ти Бо́жия, Предста́тельнице і Засту́пнице на́ша усе́рдная."]},{"h":"Кондак 2","ps":["Ви́дя іко́ну Твою́, Пресвята́я Ді́во, на дре́ві стоя́щу, князь благочести́вий Костромськи́й у́жасом мно́гим содрога́шеся недоумі́я, что бисть ви́дініє сіє́. Хотя́щу же єму́ прия́ти ю і от сего́ сви́ше уде́ржану єму́ би́вшу, не можа́ше; уві́дів, я́ко чу́дно єсть іко́ни тоя́ явле́ніє, воззва́ к Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зумом жела́я разумі́ти князь благочести́вий прише́ствіє пречу́днаго Твоєго́ о́браза во град Кострому́, Богоро́дице, душе́ю ра́дованія преіспо́лненною себі́ предаде́ води́тельству Бо́жию, і прекло́нь колі́на, со стра́хом вопія́ше Тебі́:","Ра́дуйся, Ді́во, я́вльшая о́браз Свой чу́дно;","ра́дуйся, Благослове́нная, в явле́нії о́браза Своєго́ милосе́рдіє нам явля́ющая.","Ра́дуйся, о всіх чту́щих Си́на Твоєго́ промишля́ющая;","ра́дуйся, всім прося́щим у Тебе́ да́ри, в мі́ру ві́ри, ко спасе́нію подаю́щая.","Ра́дуйся, путь і́стини заблу́дшим показу́ющая;","ра́дуйся, ко го́рнему ми́ру чудеси́ Твої́ми ум наш возводя́щая.","Ра́дуйся, смуще́нія помишле́ній сумни́тельних удаля́ющая;","ра́дуйся, сла́в'ящих Тя всегда́ прославля́ющая.","Ра́дуйся, чистото́ю Твоє́ю чистоті́ нас науча́ющая;","ра́дуйся, чистото́ю Твоє́ю нечистоту́ на́шу облича́ющая.","Ра́дуйся, моле́нія на́ша приє́млющая;","ра́дуйся, рида́ній і слез не отмета́ющая.","Ра́дуйся, Ма́ти Бо́жия, Предста́тельнице і Засту́пнице на́ша усе́рдная."]},{"h":"Кондак 3","ps":["Си́лу Бо́жию благочести́вий князь позна́во во восхожде́нії о́браза чу́днаго Твоєго́, Богома́ти, в явле́нії же ви́дів милосе́рдіє Твоє́ ко всім спасе́ніє хотя́щим получи́ти, рече́: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́в по́мисл стяжа́ти да́руємоє Небе́сноє сокро́вище, лик Твой сві́тлий, Богома́ти, второ́є простре́ держа́вний руку́ к о́бразу нисше́дшему; узрі́в же па́ки єго́ восхожде́ніє, ско́ро по́йде во град і пові́да о би́вших єму́ освяще́нному собо́ру, да прише́дше і ви́дяще іко́ни Твоєя́ явле́ніє возопію́ть с ним ві́рнії:","Ра́дуйся, Цари́це Небесе́ і землі́;","ра́дуйся, Престо́ле Царя́ ца́рствующих.","Ра́дуйся, Пренепоро́чная Ді́во;","ра́дуйся, Ма́ти Непристу́пнаго Сві́та.","Ра́дуйся, честні́йшая Херуви́м;","ра́дуйся, сла́внійшая без сравне́нія Серафи́м.","Ра́дуйся, Небе́сними Си́лами велича́ємая;","ра́дуйся, от всіх земноро́дних ублажа́ємая.","Ра́дуйся, неізрече́нноє Весе́ліє А́нгелов;","ра́дуйся, Ві́нче ца́рственний всіх проро́ков і апо́столов.","Ра́дуйся, правосла́вія Христо́ви Це́ркве огражде́ніє;","ра́дуйся, всіх суєму́дрих уче́ній і єресе́й низложе́ніє.","Ра́дуйся, Ма́ти Бо́жия, Предста́тельнице і Засту́пнице на́ша усе́рдная."]},{"h":"Кондак 4","ps":["Бу́рю внутр імі́я помишле́ній недоумі́нних, освяще́нний собо́р со псалми́ і пі́сньми духо́вними а́біє притече́ ви́діти о́браз Твой, Неіскусобра́чная. Узрі́в же єго́ на дре́ві ди́вно стоя́ща і благолі́пно красото́ю сія́юща, рече́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаша лю́діє честни́я іко́ни Твоєя́, Богоотрокови́це, прише́ствіє і, ко о́ной те́кше, поклоня́хуся, а́ки Самі́й Тебі́ су́щей, і со умиле́нієм і слеза́ми вопія́ху к Тебі́:","Ра́дуйся, Ді́во, Благослове́нная в жена́х, во чре́ві Твоє́м Носи́теля вся́чеських носи́вшая;","ра́дуйся, рожде́нієм Си́на Твоєго́ спасе́ніє ми́ру всему́ я́вльшая.","Ра́дуйся, челові́ки с Бо́гом соєдини́вшая;","ра́дуйся, преви́шшая небе́с, ізба́вльшая нас от кля́тви.","Ра́дуйся, нас к ві́чной жи́зні руководя́щая;","ра́дуйся, Влади́чице ми́ра.","Ра́дуйся, Бо́жиє к сме́ртним благоволе́ніє;","ра́дуйся, сме́ртних к Бо́гу дерзнове́ніє.","Ра́дуйся, благи́х во бла́гости соблюда́ющая;","ра́дуйся, лука́вих на путь благи́й обраща́ющая.","Ра́дуйся, под сінь кро́ва Твоєго́ прибіга́ющих ми́лующая;","ра́дуйся, упова́ющих на Тя вся потре́бная к животу́ і благоче́стію да́рующая.","Ра́дуйся, Ма́ти Бо́жия, Предста́тельнице і Засту́пнице на́ша усе́рдная."]},{"h":"Кондак 5","ps":["Я́ко боготе́чную звізду́ узрі́ша лю́діє іко́ну Твою́, Безневі́стная Ді́во, і, я́ко многосві́тлий світи́льник, поста́виша ю во святі́м собо́рнім хра́мі, ра́дующеся і вопію́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше жи́теліє гра́да Городця́ о́браз Твой, Влади́чице, во хра́мі гра́да Костроми́ стоя́щий, і на руку́ Твоє́ю держи́ма Богомладе́нця Ісу́са, ско́рбію одержи́ма бі́ша, зане́ отше́ствіє єго́ бисть із гра́да їх. Ми же, обра́довани благоволе́нієм Твої́м ко гра́ду на́шему, прино́сим Ті да́ри, і, с любо́вію лобиза́юще Твой святи́й о́браз, вопіє́м Ті:","Ра́дуйся, Звіздо́, Со́лнце пра́вди нам я́вльшая;","ра́дуйся, возлюби́вшая сію́ страну́.","Ра́дуйся, обрі́теніє Тебі́ і́щущих;","ра́дуйся, ра́достію неізрече́нною ві́рних сердця́ ісполня́ющая.","Ра́дуйся, сокро́вище благода́ті неістощи́моє;","ра́дуйся, ми́лости приснотеку́щий істо́чниче.","Ра́дуйся, от тя́жких бід спаса́ющая;","ра́дуйся, от смертно́сния я́зви ізбавля́ющая.","Ра́дуйся, всего́ ми́ра Хода́тайце;","ра́дуйся, всіх неду́гов Ціли́тельнице.","Ра́дуйся, Красото́ несравне́нная;","ра́дуйся, Добро́то несказа́нная.","Ра́дуйся, Ма́ти Бо́жия, Предста́тельнице і Засту́пнице на́ша усе́рдная."]},{"h":"Кондак 6","ps":["Пропові́дници богоно́снії би́ша ви́дівшії о́браз Твой, Богоро́дице. Возвра́щся бо ки́йждо во страну́ свою́, возвіща́ше о прише́ствії єго́ і чудесі́х от него́ бива́ємих, воспіва́я Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́вши благода́ть от чу́днаго о́браза Твоєго́, Чи́стая, ві́ру немощству́ющих утверди́, ві́рних же возвесели́ сердця́ любо́вію. Сего́ ра́ди ра́дующеся вопіє́м Ті:","Ра́дуйся, Пресвята́я Ді́во, сві́том Небе́сния і́стини нас озаря́ющая;","ра́дуйся, мглу гріхо́вную от нас отгоня́ющая.","Ра́дуйся, чудеси́ Твої́ми к богові́дінію нас приводя́щая;","ра́дуйся, всіх ка́ющихся грі́шников ко благоче́стію подвиза́ющая.","Ра́дуйся, всіх притека́ющих к Тебі́ крі́пкоє заступле́ніє;","ра́дуйся, немощству́ющих умо́м утвержде́ніє.","Ра́дуйся, ізнемога́ющих во ві́рі возставля́ющая;","ра́дуйся, ти́хоє приста́нище в мо́ре жите́йстім обурева́ємим.","Ра́дуйся, зли́я сові́ти сино́в поги́бельних открива́ющая;","ра́дуйся, вознесе́нную горди́ню враго́в оте́чества на́шего смиря́ющая.","Ра́дуйся, правосла́вних царе́й Держа́во;","ра́дуйся, всіх христия́н Похвало́.","Ра́дуйся, Ма́ти Бо́жия, Предста́тельнице і Засту́пнице на́ша усе́рдная."]},{"h":"Кондак 7","ps":["Хотя́ просла́вити Син Твой, Богоро́дице, святу́ю іко́ну Твою́ во гра́ді Костроме́, повелі́ ю в день Успе́нія Твоєго́ свято́му великому́ченику Фео́дору Стратила́ту носи́ти по гра́ду сему́, да всі, ви́дяще чу́до сіє́, благода́рним се́рдцем возопію́ть Єму́: Аллилу́я."]},{"h":"Ікос 7","ps":["Чу́до но́воє яви́ нам Госпо́дь мольба́ми Твої́ми, Богоро́дице, єгда́ сгоре́вшу хра́му, в не́мже бі поста́влен святи́й о́браз Твой, сохрани́ єго́ в пе́плі невреди́ма от огня́, і та́ко мне́вших сгоре́вша єго́ печа́ль в ра́дость преложи́. Ми же, чу́до сіє́ ві́дяще, воспіва́єм Ті такова́я:","Ра́дуйся, Купино́ Неопали́мая;","ра́дуйся, о́гненний сто́лпе, су́щия во тьмі наставля́яй.","Ра́дуйся, Киво́те, Ду́хом позлаще́нний, Невмісти́маго Бо́га вмісти́вший;","ра́дуйся, кади́льнице злата́я, я́ко фиміа́м благоуха́нний, моли́тви Твоя́ за ни к Бо́гу Си́ну при́сно вознося́щая.","Ра́дуйся, Же́зле Ааро́нов, к явле́нію в ми́рі Си́на Твоєго́ прозя́бший;","ра́дуйся, Руно́ Гедео́ново, благода́тію Бо́жиєю во спасе́ніє на́ше ороше́нноє.","Ра́дуйся, Горо́ несіко́мая, от Нея́же отсіче́ся краєуго́льний ка́мень Христо́с;","ра́дуйся, Хра́мі одушевле́нний, в Не́мже всели́ся Божество́ тіле́сні.","Ра́дуйся, ді́вства охране́ніє;","ра́дуйся, супру́жества благослове́ніє.","Ра́дуйся, па́че всіх Го́спода возлюби́вшая;","ра́дуйся, па́че всіх от Него́ превознесе́нная.","Ра́дуйся, Ма́ти Бо́жия, Предста́тельнице і Засту́пнице на́ша усе́рдная."]},{"h":"Кондак 8","ps":["Стра́нноє чу́до ви́дівше, на возду́сі іко́ну Богома́тері стоя́щу, а́ки рука́ми а́нгельськими держи́му, єгда́ второ́є сгорі́ храм, в не́мже стоя́ явле́нная сія́ іко́на, отве́ржемся, лю́діє, ми́ра сего́, ум на Небеса́ прело́жше; сего́ бо ра́ди і даде́ся нам чу́дная іко́на Богоро́диці, да, взира́юще на ню, Го́рняя му́дрствуєм, а не земна́я, вопію́ще к Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Во ви́шніх пребива́ющи селе́ніїх, і ни́жніх не разлучи́лася єси́, Богоро́дице, чудеси́ Твої́ми всіх просвіща́ющи приходя́щих к Тебі́ с ві́рою, сего́ ра́ди і сли́шиши от нас сія́:","Ра́дуйся, Ма́ти Христа́ Бо́га на́шего, на Небесі́ пребива́ющая;","ра́дуйся, на землі́ нас не оставля́ющая.","Ра́дуйся, ра́ди вели́чества Твоєго́ на Небесі́ А́нгели окруже́нная;","ра́дуйся, ра́ди сла́ви Твоєя́ на землі́ от челові́к прославля́ємая.","Ра́дуйся, Тебі́ бо слу́жать вся Небе́сния Си́ли;","ра́дуйся, Тебі́ бо, по Бо́зі, хвале́ніє возно́сять Херуви́ми і Серафи́ми.","Ра́дуйся, лице́ Бо́жиє ви́ну на Небесі́ созерца́ющая;","ра́дуйся, пред престо́лом Си́на Твоєго́ Ма́тернії ру́ці Твої́, за ни моля́щися, простира́ющая.","Ра́дуйся, нас, су́щих на землі́, от вся́каго зла омофо́ром Твої́м покрива́ющая;","ра́дуйся, ві́рних от вся́ких душепа́губних діл удаля́ющая.","Ра́дуйся, рожде́нієм Си́на Бо́жия две́рі Ца́рства Христо́ва нам отве́рзшая;","ра́дуйся, наде́ждою прия́тія Небе́сних благ ві́рних ду́ші услажда́ющая.","Ра́дуйся, Ма́ти Бо́жия, Предста́тельнице і Засту́пнице на́ша усе́рдная."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ а́нгельськоє превозно́сить Тя, Ді́во, вели́кия ра́ди любве́ Твоєя́ к ро́ду христия́нському; незри́ма бо і непристу́пна, я́ко Ма́ти Бо́га от землі́ к Небесі́ возше́дшая, пречи́стим Твої́м о́бразом зри́му і присту́пну Себі́ явля́єши всім воспіва́ющим Си́ну Твоєму́: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́я многовіща́нния, я́ко ри́би безгла́сни, зрим о Тебі́, Богоро́дице, недоумі́ють бо глаго́лати о сла́вних чудесі́х, от явле́нния Твоєя́ іко́ни бива́ємих. Ми же о́ним див'я́щеся благода́рно вопіє́м Ті:","Ра́дуйся, сліпи́х прозрі́ніє;","ра́дуйся, хроми́х хожде́ніє.","Ра́дуйся, от те́мних і лука́вих духо́в ісціля́ющая;","ра́дуйся, луча́ми от Твоєго́ пречи́стаго о́браза ізше́дшими враго́в землі́ на́шея отгна́вшая.","Ра́дуйся, больни́м виді́ніє Твоє́ дарова́вшая;","ра́дуйся, моля́щимся явле́нній іко́ні Твоє́й ісціле́ніє подаю́щая.","Ра́дуйся, разсла́бленних от одра́ болі́зні воздвига́ющая;","ра́дуйся, німи́м разріша́ющая уста́.","Ра́дуйся, от плі́на вра́жия возвраща́ющая;","ра́дуйся, лю́тия пло́ті стра́сті утоля́ющая.","Ра́дуйся, ду́ші ві́рних неізрече́нним милосе́рдієм Твої́м умиля́ющая;","ра́дуйся, неізглаго́ланним Твої́м человіколю́бієм унива́ющих ободря́ющая.","Ра́дуйся, Ма́ти Бо́жия, Предста́тельнице і Засту́пнице на́ша усе́рдная."]},{"h":"Кондак 10","ps":["Соблюсти́ хотя́щи в чистоті́ домострої́тельство Це́ркве Правосла́вния, Чи́стая, і, утверди́ти ски́петр держа́ви Россі́йськия, чу́дною іко́ною Твоє́ю вложи́ла єси́ в се́рдці благові́рнаго госуда́ря Михаї́ла Фео́доровича прия́ти віне́ць ца́рський землі́ Россі́йськия, да всі ви́дящії ви́дять, я́ко Ви́шній владі́єть ца́рством, і єму́же хо́щеть дає́ть є, і возопію́ть Єму́: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ необори́мая, Богоро́дице Ді́во, всім к Тебі́ прибега́ющим: нікто́же бо притека́яй к Тебі́ тощ отхо́дить. Сего́ ра́ди ущедря́ємі ми́лостію Твоє́ю, во умиле́нії душі́ возглаша́єм Тебі́:","Ра́дуйся, тве́рдая Стіно́, от враг ви́димих і неви́димих охраня́ющая;","ра́дуйся, крі́пкая Защи́то упова́ніє на Тя возложи́вшим.","Ра́дуйся, позна́нія і́стини чи́стоє Зерца́ло;","ра́дуйся, сохране́нія ві́ри крі́пкоє Забра́ло.","Ра́дуйся, гра́ди і страни́ христия́нськия предста́тельством Твої́м от враго́в спаса́ющая;","ра́дуйся, царе́м благові́рним побора́ющая.","Ра́дуйся, мир во гра́діх селя́щая;","ра́дуйся, благонра́вним благопоспеша́ющая.","Ра́дуйся, си́лою моли́тв Твої́х зли́я по́мисли в нічто́же обраща́ющая;","ра́дуйся, си́ли враго́в бли́жняго сокруша́ющая.","Ра́дуйся, ю́ности наставле́ніє;","ра́дуйся ста́рости поддержа́ніє.","Ра́дуйся Ма́ти Бо́жия, Предста́тельнице і Засту́пнице на́ша усе́рдная."]},{"h":"Кондак 11","ps":["Пі́ніє вся́коє побіжда́ється спростре́тися тща́щеєся мно́жеству мно́гих щедро́т Твої́х; равночи́сленния бо песку́ морсько́му пі́сні а́ще прино́сим Ті, Богоро́дице Ді́во, нічто́же соверша́єм досто́йно, я́же дарова́ла єси́ нам, вопію́щим к Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоприє́мную свіщу́, дре́вле я́вльшуюся, зрим во святі́й іко́ні Твоє́й, Богоро́дице Ді́во, єгда́ град наш защити́ла єси́ от разоре́нія враго́в землі́ на́шея луча́ми, от святи́я Твоєя́ іко́ни ісходя́щими. Сего́ ра́ди с ві́рою припа́дающе к ней і с любо́вію лобиза́юще ю, вопіє́м Ті:","Ра́дуйся, Ма́ти Преві́чнаго Сві́та Христа́, уче́нієм Єго́ ду́ші просвіща́ющая;","ра́дуйся, благода́тію Бо́жиєю неві́рующих к ві́рі в Бо́га приводя́щая.","Ра́дуйся, путеше́ствующим спутеше́ствующая;","ра́дуйся, ну́ждно пла́вающих Ко́рмчая.","Ра́дуйся, от вся́кия ско́рби, гні́ва і ну́жди спаса́ющая;","ра́дуйся, от гла́да, губи́тельства, тру́са і огня́ сохраня́ющая.","Ра́дуйся, ізбавля́ющая от іноплеме́нних;","ра́дуйся, охраня́ющая от междоусо́бния бра́ні.","Ра́дуйся, во святі́й іко́ні Твоє́й, я́ко со́лнце, в Костромськи́х преді́ліх возсія́вшая;","ра́дуйся, зді о́трасль ца́рственную возвели́чившая.","Ра́дуйся, Тобо́ю бо утвержда́ються ца́рства;","ра́дуйся, Тобо́ю бо вінча́ються ца́ріє.","Ра́дуйся, Ма́ти Бо́жия, Предста́тельнице і Засту́пнице на́ша усе́рдная."]},{"h":"Кондак 12","ps":["Благода́ть прия́вшая от Бо́га Си́на Твоєго́, Ді́во Богоро́дице, і ту дре́вле ізлія́вшая на всіх прибіга́ющих к о́бразу Твоєму́, не лиши́ ни́ні і нас бога́тия Твоєя́ ми́лости, да́руй нам покая́ніє о грісі́х, да чи́стим се́рдцем і устни́ взива́єм к возлю́бленному Си́ну Твоєму́ і Бо́гу на́шему: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твоєя́ ми́лості і чудеса́, хва́лим Тя всі, Богоро́дице, і, я́ко дре́влій Ізра́їль ко киво́ту Заві́та, притека́єм ко о́бразу лиця́ Твоєго́, і із глубини́ ду́ші вопіє́м: воздви́гни ру́ці Твоя́ к Си́ну Твоєму́, да пода́сть нам вся блага́я і спаси́тельная с ві́рою і любо́вію вопію́щим Ті:","Ра́дуйся, Утіше́ніє на́ше в ско́рбіх;","ра́дуйся, Утоле́ніє печа́лей на́ших.","Ра́дуйся, Ра́досте на́ша безконе́чная;","ра́дуйся, Сві́тлосте і Отра́до серде́чная.","Ра́дуйся, Наде́ждо на́ша крі́пкая;","ра́дуйся, си́рим Прия́телище.","Ра́дуйся, стра́нним Прибі́жище;","ра́дуйся, оби́димим Покрови́тельнице.","Ра́дуйся, оклевета́ємих Оправда́ніє;","ра́дуйся, благи́х Защище́ніє.","Ра́дуйся, ті́ла моєго́ Врачева́ніє;","ра́дуйся, ду́ші моєя́ Спасе́ніє.","Ра́дуйся, Ма́ти Бо́жия, Предста́тельнице і Засту́пнице на́ша усе́рдная."]},{"h":"Кондак 13","ps":["О Премилосе́рдая Засту́пнице на́ша, вели́кия ра́ди ми́лости Твоєя́ дарова́вшая оте́честву і гра́ду на́шему чудотво́рную іко́ну Твою́ во освяще́ніє, утіше́ніє і огражде́ніє на́ше, ни́нішнєє приє́мши славосло́віє, от вся́каго зла́го обстоя́нія ізба́ви раби́ Твоя́. Ски́петр благові́рнаго Імпера́тора на́шего утверди́, да́руй єму́ здра́віє і спасе́ніє, на враги́ побі́ду і одолі́ніє і всіх нас ві́чних мук свободи́, устна́ми, душе́ю же і се́рдцем вопію́щих: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Арха́нгел Гавриї́л от Бо́га по́слан бисть во град Назаре́т ко Пречи́стій Ді́ві Марі́ї, і вшед к Ней рече́: Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю, благослове́нна Ти в жена́х. Арха́нгельському гла́су подража́юще, і ми, грі́шнії, ра́дости і благодаре́нія в се́рдці своє́м іспо́лнені, пред явле́нним о́бразом Твої́м благохвале́нія на́ша возноси́ти к Тебі́ дерза́єм, Пресвята́я Богоро́дице:","Ра́дуйся, о́трасле от ко́рене Дави́дова благослове́нная;","ра́дуйся, обі́том роди́телей в же́ртву Бо́гу принесе́нная.","Ра́дуйся, святи́х пра́ведних Іоаки́ма і А́нни Дщи Богода́нная;","ра́дуйся, тріє́х літ во храм Бо́жий введе́нная і та́мо воспита́нная.","Ра́дуйся, та́мо смире́нієм і чистото́ю всіх удиви́вшая;","ра́дуйся, та́мо арха́нгельськия бесі́ди сподо́бльшаяся.","Ра́дуйся, Ді́во, о зача́тії Бо́га Сло́ва благові́стіє во смире́нії приі́мшая;","ра́дуйся, ізбра́нная Отрокови́це, к зача́тію Бо́га Сло́ва си́лою сви́ше осіне́нная.","Ра́дуйся, та́йну воплоще́нія Си́на Бо́жия, от віко́во в Бо́зі сокрове́нную, откри́вшая;","ра́дуйся, А́гнице, ро́ждшая А́гнця Христа́, взе́мшаго гріхи́ ми́ра.","Ра́дуйся, Тобо́ю бо ізбавля́ємся мук а́дових;","ра́дуйся, Тобо́ю бо сподобля́ємся ві́чния жи́зні.","Ра́дуйся, Ма́ти Бо́жия, Предста́тельнице і Засту́пнице на́ша усе́рдная."]},{"h":"Кондак 1","ps":["Взбра́нней Воєво́ді, Пренепоро́чній Ді́ві Богоро́диці, Засту́пниці на́шей і Предста́тельству христия́н непости́дному, явле́нієм чу́дния іко́ни Своєя́ ра́дованіє пода́вшей земле́ Росси́йстій і вся ві́рная ча́да Це́ркве просвети́вшей, благодаре́ніє усе́рдно прино́сим Ті, Богоро́дице, і припа́дающе пречу́дному о́бразу Твоєму́, уми́льно глаго́лем: спаси́, Госпоже́, і поми́луй раби́ Твоя́, зову́щия:","Ра́дуйся, Ма́тер Бо́жия, Предста́тельнице і Засту́пнице на́ша усе́рдная."]},{"h":"Молитва перша","ps":["О Премилосе́рдая Госпоже́, Цари́це, Богоро́дице, прийми́ смире́нноє моле́ніє на́ше, і не отри́ни нас, Заступле́ніє і Прибі́жище на́ше, і не возгнуша́йся нас, недосто́йних, но, я́ко Милосе́рдая, не преста́ни моля́щи, Єго́же родила́ єси́, да да́руєть нам проще́ніє мно́гих согріше́ній на́ших, да спасе́ть нас, і́миже вість судьба́ми. Поми́луй нас, Влади́чице, поми́луй нас, ність бо нам спасе́ніє от діл. Ті́мже ві́рно вопіє́м Ті: поми́луй раби́ Твоя́ і непло́дноє се́рдце на́ше покажи́ плодоно́сно благи́х діл. При́зри на нас, недосто́йних, Ти бо упова́ніє і покро́в наш, жизнь і світ се́рдцю на́шему. Я́ко Невече́рній Світ от чре́ва Твоєго́ воздви́гшая, озари́ ду́шу на́шу, Чи́стая, і отжени́ вся́ку мглу сердця́ на́шего. Да́руй нам умиле́ніє, покая́ніє і сокруше́ніє серде́чноє. Сподо́би нас по вся дні живота́ на́шего твори́ти во́лю Си́на Твоєго́ і Бо́га на́шего і во всем благоугожда́ти Єму́ Єди́ному. О Богома́ти, не преста́ни моля́щи Ро́ждшагося от Тебе́ за вся, притека́ющия с ві́рою к сему́ чудотво́рному о́бразу Твоєму́, і подава́й їм ско́рую по́мощ і утіше́ніє в ско́рбіх і напа́стіх і злострада́ніїх, ізба́ви їх от клевети́ і зло́би челові́чеськія, от враг ви́димих і неви́димих і вся́кия ну́жди і печа́лі. Спаси́ оте́чество на́ше, град сей і вся гра́ди і страни́ от вся́ких бід і нужд і сотвори́ ми́лостива нам би́ти Бо́га на́шего, отврати́ вся́кий гнів Єго́, на ни дви́жимий, і ізба́ви ни от належа́щаго і пра́веднаго Єго́ преще́нія. О Боголюби́вая Влади́чице, А́нгелов украше́ніє, му́чеников сла́во і всіх святи́х ра́досте, с ни́ми моли́ Го́спода, да сподо́бит нас в покая́нії сконча́ти живота́ на́шего тече́ніє. Во сме́рті же час, Пресвята́я Ді́во, ізба́ви нас от вла́сті бісо́вськия і осужде́нія, і отві́та, і стра́шнаго іспита́нія, і мита́рств го́рких, і огня́ ві́чнаго, да, сподо́бльшеся сла́внаго Ца́рствія Бо́жия, велича́єм Тя і сла́вим вопло́щшагося от Тебе́ Христа́, Бо́га на́шего, Єму́же сла́ва со Отце́м і Святи́м Ду́хом, ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О Пресвята́я Влади́чице Богоро́дице і Присноді́во Марі́є, єди́ная Наде́ждо нам, грі́шним, к Тебі́ прибіга́єм і Тебі́ мо́лим, я́ко ве́ліє і́маши дерзнове́ніє пред ро́ждшимся от Тебе́ по пло́ті Го́сподом Бо́гом і Спаси́телем на́шим Ісу́сом Христо́м. Не пре́зри слез на́ших, не возгнуша́йся воздиха́ній на́ших, не отри́ни ско́рби на́шея, не посрами́ упова́нія на́шего на Тя, но Ма́терніми моле́нії Твої́ми умоли́ Го́спода Бо́га, да сподо́бит нас грі́шних і недосто́йних свободи́тися от гріхо́в і страсте́й душе́вних і тіле́сних, умре́ти ми́ру і жи́ти Єму́ Єди́ному во вся дні живота́ на́шего.","О Пресвята́я Влади́чице Богоро́дице, путеше́ствующим спутеше́ствуй і огражда́й і охраня́й о́ния, ізба́ви пліне́нних от пліне́нія, свободи́ стра́ждущих от бід, уті́ши су́щих в печа́лі, ско́рбіх і напа́стіх, облегчи́ нищету́ і вся́ко злострада́ніє тіле́сноє і да́руй всім вся потре́бная к животу́, благоче́стію і жи́зні вре́менній. Спаси́, Влади́чице, вся страни́ і гра́ди і сію́ страну́ і сей град, і́мже сія́ чудотво́рная і свята́я іко́на Твоя́ даде́ся во утіше́ніє і огражде́ніє, ізба́ви я от гла́да, губи́тельства, тру́са, пото́па, огня́, меча́, наше́ствія іноплеме́нних, междоусо́бния бра́ні і отврати́ вся́кий гнів на ни пра́ведно дви́жимий. Да́руй нам вре́м'я на покая́ніє і обраще́ніє, ізба́ви нас от внеза́пния сме́рти і во вре́м'я ісхо́да на́шего предста́ни нам я́вльшися, Ді́во Богоро́дице, і ізба́ви нас от возду́шних мита́рств князе́й ві́ка сего́, сподо́би на Стра́шнім Суди́щі Христо́вім ста́ти одесну́ю і соді́лай нас снаслі́дники ві́чних благ, да сла́вим во ві́ки великолі́поє і́м'я Си́на Твоєго́ і Бо́га на́шего со Безнача́льним Єго́ Отце́м і Святи́м і Благи́м і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Прише́ствієм честни́я Твоєя́ іко́ни, Богоотрокови́це, / обра́дованний днесь Богохрани́мий град Кострома́, / я́коже дре́вній Ізра́їль ко киво́ту Заві́та, / притека́єть ко ізображе́нію лиця́ Твоєго́ / і воплоти́вшагося от Тебе́ Бо́га на́шего, / да Твої́м Ма́тернім к Нему́ предста́тельством / при́сно хода́тайствуєши всім, / под сінь кро́ва Твоєго́ прибега́ющим, // мир і ве́лію ми́лость."]},{"h":"Інший тропар, глас 4","ps":["Днесь сві́тло красу́ється преймени́тий град Кострома́ / і вся Ру́ськая страна́, / созива́ющи к весе́лію вся боголюби́вия наро́ди христия́нськия, / на пресла́вноє торжество́ Бо́жия Ма́тере, / прише́ствія ра́ди чудотво́рнаго Єя́ і многоціле́бнаго о́браза, / днесь бо яви́ся нам пресві́тлоє вели́коє со́лнце, / прийді́те, всі Богоізбра́ннії лю́діє, но́вий Ізра́їль, / ко істо́чнику цільбоно́сному, / істоча́єть бо нам неоску́дния ми́лості Пресвята́я Богоро́диця / і ізбавля́єть вся гра́ди і страни́ христия́нськия / невреди́ми от всіх наві́т вра́жиїх. / Но, о Всеми́лостивая Госпоже́, Ді́во Богоро́дице, Влади́чице, / спаси́ страну́ на́шу, і архієре́ї, і вся лю́ди Твоєго́ достоя́нія от всіх бід / по вели́цій Твоє́й ми́лості, да зове́м Ті: // ра́дуйся, Ді́во, христия́ном похвало́."]},{"h":"Кондак, глас 8","ps":["Благода́рственная принося́ще Ті, раби́ Твої́, Богороди́тельнице, о всіх, / і́миже благоді́яла єси́ гра́ду на́шему, / із глубини́ душі́ взива́єм к Тебі́ і ми́лі ся ді́єм: / не преста́ни, Влади́чице, / Ма́терніми к Си́ну Твоєму́ і Бо́гу на́шему моли́твами / подава́ти вся блага́я і спаси́тельная всім, / ві́рою і любо́вію вопію́щим Ті: // ра́дуйся, Ді́во, христия́н похвало́."]},{"h":"Інший кондак, глас 8","ps":["Притеце́м, лю́діє, всі к ти́хому і до́брому приста́нищу, / в дом Бо́жия Ма́тере, / чу́дному о́бразу Цари́ці і Богоро́диці, / за неізрече́нную ми́лость Єя́ явле́нному, / ві́рно припа́дающе і вопію́ще: / о Всеми́лостивая Влади́чице, / за спаси́тельноє Твоє́ смотре́ніє, / чу́днаго о́браза к нам прише́ствіє, / посіти́ нас, грі́шних, сві́тло сотворя́ющих пра́зднество Твоє́, / укріпи́ страну́ на́шу, / ди́вно на враги́ побі́ду подаю́щи, і ві́ру утверди́. / Це́рков Си́на Твоєго́ непоколеби́му соблюди́, / притека́ющих к Тебі́ спаси́, от вся́ких напа́стей ізба́ви, / сохраня́ющи в ми́рі все Правосла́віє, да зове́м Ті: // ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтем о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Неупиваєма Чаша»","e":"Akathist to the Theotokos before her icon “The Inexhaustible Chalice”","secs":[{"h":"Кондак 1","ps":["Ізря́дноє і ди́вноє вспоможе́ніє нам дарова́ся, о́браз Твой честни́й, Богоро́дице Ді́во, я́ко ізба́вльшеся явле́нієм єго́ неду́гов душе́вних і тіле́сних і ско́рбних обстоя́ній, благода́рния хвали́ прино́сим Ті, всеми́лостивая Засту́пнице. Ти же, Госпоже́, приклони́ся благоутро́бно к на́шим воздиха́нієм і во́плем серде́чним, і ісціле́ніє пода́ждь стра́ждущим, да с ві́рою воззове́м Ті:","Ра́дуйся, Влади́чице, Неупива́ємая Ча́ше, духо́вную жа́жду на́шу утоля́ющая."]},{"h":"Ікос 1","ps":["А́нгельстії чи́ни і пра́ведников со́нми непреста́нно сла́в'ять Тя, Цари́цю Богоро́дицю, Хода́таїцю о ро́ді челові́честім, в беззако́ніїх погруже́ннем і во грісі́х пребива́ющем, да́руєши бо нам во утіше́ніє і спасе́ніє ми́лость Свою́ чрез чудотво́рния іко́ни Твоя́, ї́хже, я́ко зві́зди небе́сния, по всей землі́ на́шей зрим. Ко єди́ному же от сих образо́в, Неупива́ємая Ча́ша імену́ємому, припа́дающе, із глубини́ се́рдця взива́єм Ті:","Ра́дуйся, непристу́пнаго Божества́ селе́ніє;","ра́дуйся, непреста́нноє челові́ков удивле́ніє.","Ра́дуйся, скорбми́ гріхи́ на́ша очища́ющая;","ра́дуйся, печа́льми на́ша не́мощі врачу́ющая.","Ра́дуйся, ми́лость Свою́ нам сви́ше посила́ющая;","ра́дуйся, ско́рбная сердця́ на́ша веселя́щая.","Ра́дуйся, пречу́дноє всіх с Бо́гом примире́ніє;","ра́дуйся, му́ки ві́чния ізві́стноє ізбавле́ніє.","Ра́дуйся, Влади́чице, Неупива́ємая Ча́ше, духо́вную жа́жду на́шу утоля́ющая."]},{"h":"Кондак 2","ps":["Ви́дящи, Пречи́стая Влади́чице, ско́рби серде́чния, му́ки душе́вния, покая́ніє і́скреннєє челові́ков, губи́тельним поро́ком пія́нства одержи́мих, благоволи́ла єси́ дарова́ти богоспаса́ємому гра́ду Се́рпухову ми́лость Твою́ явле́нієм пречу́днаго о́браза Твоєго́, да всі, с ві́рою і сокруше́нним се́рдцем к нему́ припа́дающії і ісціле́ніє от тя́жкаго неду́га своєго́ обріта́ющії, усе́рдно вопію́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́в трикра́тноє явле́ніє преподо́бнаго Варлаа́ма і повелі́ніє от него́ во град Се́рпухов ше́ствовати, челові́к ні́кий, стра́стію пія́нства одержи́мий, обрі́те та́мо в монастирі́ іко́ну Твою́ святу́ю, Неупива́ємая Ча́ша імену́ємую. Ми же, ви́дяще таково́є о нас, грі́шних, попече́ніє, со благогові́нієм воспіва́єм Ті такова́я:","Ра́дуйся, сла́ву чуде́с Твої́х грі́шним открива́ющая;","ра́дуйся, Путеводи́тельнице, путь благи́й їм явля́ющая.","Ра́дуйся, ко спасе́нію нас привлека́ющая;","ра́дуйся, благодаре́нію нас науча́ющая.","Ра́дуйся, ско́рби на́шея в ра́дость претворе́ніє;","ра́дуйся, несумні́нною наде́ждою возвеселе́ніє.","Ра́дуйся, губи́тельния стра́сті потребля́ющая;","ра́дуйся, благи́м намі́ренієм посо́бствующая.","Ра́дуйся, Влади́чице, Неупива́ємая Ча́ше, духо́вную жа́жду на́шу утоля́ющая."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго благода́тію Влади́чиці укріпи́ ні́коєго челові́ка, неду́гом пія́нства стра́ждущаго, єгда́ той, разсла́блене іми́й но́зі, потща́ся гра́да Се́рпухова дости́гнути, повелі́ніє Богоро́диці, чрез преподо́бнаго Варлаа́ма рече́нноє, ісполня́я. Обрі́т же во гра́ді сем іко́ну Пречи́стия Богома́тере, а́біє ісцілі́ от неду́га своєго́, душе́внаго і тіле́снаго, і с тре́петом воззва́ Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще істо́чник неоскудіва́ємий, неупива́ємую ча́шу небе́сних дарова́ній, не то́кмо лю́діє гра́да Се́рпухова, но і всі правосла́внії христия́не от іни́х градо́в і ве́сей, к Твоєму́ пречу́дному о́бразу притека́юще і пред сим ісціле́нія обріта́юще, благода́рними усти́ вопію́ть Ті си́це:","Ра́дуйся, Є́юже ско́рби на́ша потребля́ються;","ра́дуйся, Є́юже ра́дость спасе́нія ізлива́ється.","Ра́дуйся, не́мощі душе́вния і тіле́сния врачу́ющая;","ра́дуйся, стра́сті моли́твами Твої́ми укроща́ющая.","Ра́дуйся, коєму́ждо прося́щему поле́зная да́рующая;","ра́дуйся, безчи́сленния щедро́ти всім подаю́щая.","Ра́дуйся, ми́лости сокро́вище нам отверза́ющая;","ра́дуйся, милосе́рдіє к па́дшим явля́ющая.","Ра́дуйся, Влади́чице, Неупива́ємая Ча́ше, духо́вную жа́жду на́шу утоля́ющая."]},{"h":"Кондак 4","ps":["Бу́рю внутр іму́ще помишле́ній сумни́тельних, оба́че с покая́нієм і́скренним к Твоєму́ неізрече́нному милосе́рдію притека́юще, пія́нственною стра́стію одержи́мії ісціле́ніє получа́ють, і от всея́ душі́ зову́ть рожде́нному от Тебе́ Спаси́телю на́шему: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша Госпо́дь тя́жкия ско́рби, во́пли і плач жен, ста́риць, діте́й, ї́хже сро́дниці обурева́ємі суть пія́нственною стра́стію іли́ безу́мієм наркоти́чеським одержи́ми, дарова́ їм, Пренепоро́чная, Твою́ іко́ну, от нея́же всі прося́щії утіше́ніє і ра́дость духо́вную обріта́ють, і вопію́ть Ті со слеза́ми такова́я:","Ра́дуйся, А́гнице, А́гнця ро́ждшая, гріхи́ ми́ра взе́млющаго;","ра́дуйся, Ча́ше, от Істо́чника безсме́ртія че́рплющая.","Ра́дуйся, ма́терей ско́рбних укріпле́ніє;","ра́дуйся, ненаде́жних благо́є наді́яніє.","Ра́дуйся, притека́ющих к Тебі́ благода́тноє охране́ніє;","ра́дуйся, скорб'я́щих отра́до і утіше́ніє.","Ра́дуйся, волне́ніє страсте́й в нас усмиря́ющая;","ра́дуйся, ру́ку по́мощі тре́бующим простира́ющая.","Ра́дуйся, Влади́чице, Неупива́ємая Ча́ше, духо́вную жа́жду на́шу утоля́ющая."]},{"h":"Кондак 5","ps":["Боготе́чную звізду́, честну́ю іко́ну Твою́, показа́ла єси́ нам, Влади́чице ми́ра, ю́же зря́ще і с ві́рою серде́чною моля́щеся Тебі́, Богоро́дице, глаго́лем: пія́нством і іни́ми неду́ги душе́вними іли́ тіле́сними стра́ждущия ісціли́, ві́рния же научи́ воспіва́ти хвалу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дяще чудеса́ пресла́вная і зна́менія пречу́дная, не то́кмо от іко́ни Твоєя́, Богома́ти, во гра́ді Се́рпухове явле́нния, бива́ємая, но і от я́же по подо́бію сея́ іко́ни ізображе́ній, припа́дающе к ним, смире́нно глаго́лем Ті:","Ра́дуйся, притека́ющих к Тебі́ ско́рая Предста́тельнице;","ра́дуйся, моле́ній на́ших благосе́рдная Усли́шательнице.","Ра́дуйся, град Се́рпухов благослове́нієм Твої́м осіни́вшая;","ра́дуйся, в преді́ліх моско́вських сла́ву чуде́с Твої́х яви́вшая.","Ра́дуйся, сокро́вище ісціле́ній неоскудіва́ємоє;","ра́дуйся, возде́ржником всемо́щная Покрови́тельнице.","Ра́дуйся, проти́ву ми́ра і дия́вола подвиза́ющимся Споспі́шнице;","ра́дуйся, в ми́рі благоче́стно живу́щих усе́рдная Засту́пнице.","Ра́дуйся, Влади́чице, Неупива́ємая Ча́ше, духо́вную жа́жду на́шу утоля́ющая."]},{"h":"Кондак 6","ps":["Пропові́дующе чудеса́ Твоя́, Богороди́тельнице, мо́лим Тя, Пречи́стая, со слеза́ми: ізба́ви всіх нас от па́губнаго к винопи́тію пристра́стія і от паде́ній гріхо́вних, подвиза́ющи воспіва́ти Бо́гові: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ сві́тлость Боже́ственния сла́ви от іко́ни Твоєя́, Ді́во Богоотрокови́це, іді́же Госпо́дь наш Ісу́с Христо́с я́ко Младе́нець зри́ться, о́браз Та́їн Свої́х Пречи́стих нам явля́яй, і от страсте́й ме́рзьких с ві́рою притека́ющим ізбавле́ніє да́руєть. Ми же Тебі́, Пречи́стій Єго́ Ма́тері, ви́ну о нас Си́на Своєго́ умоля́ющей, гла́си немо́лчния прино́сим сицеви́я:","Ра́дуйся, я́ко о Тебі́ ра́дується а́нгельський собо́р;","ра́дуйся, я́ко о Тебі́ торжеству́єть челові́чеський род:","Ра́дуйся, похвали́ небе́сния і земни́я сла́вою превосходя́щая;","ра́дуйся, рожде́ннаго Тобо́ю А́гнця нам ди́вно показу́ющая.","Ра́дуйся, ко врато́м жи́зні ві́чния приводя́щая;","ра́дуйся, от істо́чника нетлі́нія жа́ждущия напая́ющая.","Ра́дуйся, от паде́ній гріхо́вних возставля́ющая;","ра́дуйся, неіссяка́ємою бла́гостію нікого́же оставля́ющая.","Ра́дуйся, Влади́чице, Неупива́ємая Ча́ше, духо́вную жа́жду на́шу утоля́ющая."]},{"h":"Кондак 7","ps":["Хотя́ челові́к ні́кий возблагодари́ти Тя, Влади́чице, ісціле́нія ра́ди от неду́га пія́нственнаго, украси́ Твою́, Богома́ти, пречу́дную іко́ну, во гра́ді Се́рпухове пребива́ющую, со благодаре́нієм воспіва́я Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вная чудеса́ ви́дим, Пречи́стая, от іко́ни Твоєя́ святи́я: стра́стію пія́нства стра́ждущії, к Твоєму́ ма́тернему предста́тельству прибіга́юще, от тя́жкаго неду́га своєго́ ізбавля́ються, і хвалу́ Тебі́ принося́ще, зову́ть такова́я:","Ра́дуйся, живоно́сний Істо́чниче ісціле́ній;","ра́дуйся, Купе́ле Небе́сная Боже́ственних дарова́ній.","Ра́дуйся, ріко́ ісціле́ній приснотеку́щая;","ра́дуйся, мо́ре, стра́сті на́ша потопля́ющеє.","Ра́дуйся, во гріхи́ впа́дшим наде́жду подаю́щая;","ра́дуйся, ма́тернима рука́ма Твої́ма тіх возставля́ющая.","Ра́дуйся, сердца́ благочести́вих возвеселя́ющая;","ра́дуйся, вся блага́я проше́нія на́ша ісполня́ющая.","Ра́дуйся, Влади́чице, Неупива́ємая Ча́ше, духо́вную жа́жду на́шу утоля́ющая."]},{"h":"Кондак 8","ps":["Стра́нно і сумни́тельно неве́рующим сли́шати, ка́ко іко́на Твоя́ свята́я Боже́ственних ісціле́ній істоча́єть струї́. Ми же, о́ной благогові́йно поклоня́ющеся, лобиза́єм ю, вопію́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Все упова́ніє стра́ждущії неду́гом пія́нства на Тя, Ді́во Чи́стая, возлага́ють: приклони́ся к не́мощем на́шим, уврачу́й стра́сті. Кто бо нас грі́шних ізведе́ть із ро́ва поги́белі, а́ще не Ти, Влади́чице? Сего́ ра́ди, колі́на пред Твої́м честни́м о́бразом прекло́ньше, воспіва́єм Ті та́ко:","Ра́дуйся, моле́нія грі́шников не отверга́ющая;","ра́дуйся, призива́ющим Тя небе́сную по́мощ ниспосила́ющая.","Ра́дуйся, глубину́ милосе́рдія Твоєго́ грі́шним показу́ющая;","ра́дуйся, отча́янних і безнаде́жних ободря́ющая.","Ра́дуйся, одержи́мим стра́стію пія́нства поможе́ніє;","ра́дуйся, терпіли́вих страда́льцев благода́тноє утіше́ніє.","Ра́дуйся, неду́гов на́ших блага́я Ціли́тельнице.","Ра́дуйся, от суєти́ мирськи́я на́ша Охрани́тельнице.","Ра́дуйся, Влади́чице, Неупива́ємая Ча́ше, духо́вную жа́жду на́шу утоля́ющая."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ а́нгельськоє удиви́ся ді́лу Твоєго́ милосе́рдія, Го́споди, я́ко дарова́л єси́ грі́шному ро́ду челові́чеському тве́рдую Засту́пницю і Помо́щницю, к на́шим не́мощем приклоня́ющуюся і от го́ркаго неду́га пія́нства свобожда́ющую, ві́рния же науча́ющую пі́ти Тебі́: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії недоумі́ють восхвали́ти по достоя́нію ди́вноє, Богома́ти, іко́ни Твоєя́ явле́ніє, ніже́ ми, грі́шнії, от скве́рних усте́н на́ших возмо́жем просла́вити Засту́пницю на́шу, я́коже подоба́єть. Оба́че, душе́ю і се́рдцем ра́дующеся, Тебі́ глаго́лем:","Ра́дуйся, я́ко лик Твой свяще́нний явля́єть чудеса́;","ра́дуйся, я́ко ско́роє єси́ посрамле́ніє отверга́ющих Тя.","Ра́дуйся, от бід і скорбе́й при́сноє огражде́ніє;","ра́дуйся, прибіга́ющих к Тебі́ от зла сохране́ніє.","Ра́дуйся, кро́тким сія́нієм Твої́м мглу страсте́й разгоня́ющая;","ра́дуйся, ду́ші на́ша любо́вію к Тебі́ і Си́ну Твоєму́ ісполня́ющая.","Ра́дуйся, ко стезя́м покая́нія прему́драя Наста́внице;","ра́дуйся, до́браго нам отві́та пред Судіє́ю Пра́ведним Хода́тайце.","Ра́дуйся, Влади́чице, Неупива́ємая Ча́ше, духо́вную жа́жду на́шу утоля́ющая."]},{"h":"Кондак 10","ps":["Спасти́ хотя́щи мно́гія, чу́дную іко́ну Твою́, Присноді́во, пія́нством неду́гующим дарова́ла єси́, да всі одержи́мії се́ю стра́стію к чудотво́рному о́бразу Твоєму́ притека́ють і, ісціле́ніє получи́вше, во умиле́нії взива́ють Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ і щит, Богома́ти, пія́нства неду́гом стра́ждущим, і всім усе́рдно к Тебі́ притека́ющим і іко́ну Твою́ святу́ю благогові́йно чту́щим, сію́ бо нам дарова́ благи́х Пода́тель Госпо́дь в по́мощ і цільбу́ от губи́тельния стра́сті, і тім наказу́єть нам пі́ти Тебі́ такова́я:","Ра́дуйся, врачева́ній ло́жних гро́зноє іспроверже́ніє;","ра́дуйся, благода́ті Врача́ І́стиннаго к нам привлече́ніє.","Ра́дуйся, Твоє́ю чистото́ю на́шу скве́рну очища́ющая;","ра́дуйся, Твоє́ю благода́тію на́ше недосто́їнство просвіща́ющая.","Ра́дуйся, єстество́ на́ше тлі́нноє в нетлі́ніє облека́ющая;","ра́дуйся, моле́нія на́ша Твої́м предста́тельством укріпля́ющая.","Ра́дуйся, от неможе́нія на́шего нас восставля́ющая;","ра́дуйся, об'є́мшій нас о́блак страсте́й разгоня́ющая.","Ра́дуйся, Влади́чице, Неупива́ємая Ча́ше, духо́вную жа́жду на́шу утоля́ющая."]},{"h":"Кондак 11","ps":["Пі́ніє на́ше смире́нноє, от любве́ і усе́рдія Тебі́ приноси́моє, не пре́зри, Чи́стая, і не отврати́ ли́ка Твоєго́ от стра́ждущих неду́гом пія́нства і отча́явшихся, но помози́ їм і нам очи́ститися от вся́кия скве́рни гріхо́вния, да возмо́жем досто́йно і пра́ведно пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоприє́мную свіщу́ зрим Тя, Пресвята́я Ді́во, Твой бо о́браз святи́й луча́ми благода́ті Твоєя́ мглу гріхо́вную прогоня́єть і на сві́тлую стезю́ доброді́телей наставля́єть с ві́рою зову́щих Ті такова́я:","Ра́дуйся, от суєти́ ми́ра сего́ многом'яте́жнаго нас ізима́ющая;","ра́дуйся, прираже́нія страсте́й плотськи́х отража́ти нам помога́ющая.","Ра́дуйся, мисль бла́гу в се́рдці на́ше полага́ющая;","ра́дуйся, омраче́нную со́вість на́шу просвіща́ющая.","Ра́дуйся, мучи́тельними неду́ги стра́ждущих ізбавля́ющая;","ра́дуйся, ко і́скреннему покая́нію і ісправле́нію призива́ющая.","Ра́дуйся, ду́ші всіх озло́бленних укріпля́ющая;","ра́дуйся, і́м'я Твоє́ сла́в'ящих спаса́ющая.","Ра́дуйся, Влади́чице, Неупива́ємая Ча́ше, духо́вную жа́жду на́шу утоля́ющая."]},{"h":"Кондак 12","ps":["Благода́ть Бо́жия, предста́тельством Твої́м, о Богома́ти, подава́ється всім скорб'я́щим, обездо́ленним, вдова́м і ста́рицям, найпа́че же пія́нственним неду́гом стра́ждущим, і не тщи отхо́дять сі́ї, Пречи́стая, от неупива́ємия ча́ші Боже́ственних дарова́ній Твої́х, но неоску́дно цільби́ получа́юще, Всеблага́я, благода́рственно вопію́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твоя́ чудеса́ і ве́лію ми́лость, стра́стію пія́нства одержи́мим явле́нную, мо́лим Тя, Влади́чице, спаси́ і поми́луй, і наста́ви на стезю́ пра́ву, і не оста́ви нас, покро́ва Твоєго́ і́щущих і зову́щих Ті:","Ра́дуйся, ро́су ми́лости Твоєя́ нам низводя́щая;","ра́дуйся, от пристра́стія ко хмельно́му питію́ свобожда́ющая.","Ра́дуйся, от пія́нственния стра́сті врачева́ніє;","ра́дуйся, в разслабле́нії су́щим крі́пкоє поможе́ніє.","Ра́дуйся, го́рдия смиря́ющая;","ра́дуйся, смире́нния возвиша́ющая.","Ра́дуйся, малоду́шних ди́вноє ободре́ніє;","ра́дуйся, благоду́шних ве́лія ра́досте.","Ра́дуйся, Влади́чице, Неупива́ємая Ча́ше, духо́вную жа́жду на́шу утоля́ющая."]},{"h":"Кондак 13","ps":["О Преми́лостивая Ма́ти Сладча́йшаго Го́спода на́шего Ісу́са Христа́! Ни́нішнєє на́ше усли́ши моле́ніє і ізба́ви нас от всіх неду́гов душе́вних і тіле́сних, найпа́че же ісціли́ пія́нством стра́ждущия, да не во злі поги́бнуть, но да спасе́ннії Тобо́ю при́сно вопію́ть Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельстії чи́ни і пра́ведников со́нми непреста́нно сла́в'ять Тя, Цари́цю Богоро́дицю, Хода́таїцю о ро́ді челові́честім, в беззако́ніїх погруже́ннем і во грісі́х пребива́ющем, да́руєши бо нам во утіше́ніє і спасе́ніє ми́лость Свою́ чрез чудотво́рния іко́ни Твоя́, ї́хже, я́ко зві́зди небе́сния, по всей землі́ на́шей зрим. Ко єди́ному же от сих образо́в, Неупива́ємая Ча́ша імену́ємому, припа́дающе, із глубини́ се́рдця взива́єм Ті:","Ра́дуйся, непристу́пнаго Божества́ селе́ніє;","ра́дуйся, непреста́нноє челові́ков удивле́ніє.","Ра́дуйся, скорбми́ гріхи́ на́ша очища́ющая;","ра́дуйся, печа́льми на́ша не́мощі врачу́ющая.","Ра́дуйся, ми́лость Свою́ нам сви́ше посила́ющая;","ра́дуйся, ско́рбная сердця́ на́ша веселя́щая.","Ра́дуйся, пречу́дноє всіх с Бо́гом примире́ніє;","ра́дуйся, му́ки ві́чния ізві́стноє ізбавле́ніє.","Ра́дуйся, Влади́чице, Неупива́ємая Ча́ше, духо́вную жа́жду на́шу утоля́ющая."]},{"h":"Кондак 1","ps":["Ізря́дноє і ди́вноє вспоможе́ніє нам дарова́ся, о́браз Твой честни́й, Богоро́дице Ді́во, я́ко ізба́вльшеся явле́нієм єго́ неду́гов душе́вних і тіле́сних і ско́рбних обстоя́ній, благода́рния хвали́ прино́сим Ті, всеми́лостивая Засту́пнице. Ти же, Госпоже́, приклони́ся благоутро́бно к на́шим воздиха́нієм і во́плем серде́чним, і ісціле́ніє пода́ждь стра́ждущим, да с ві́рою воззове́м Ті:","Ра́дуйся, Влади́чице, Неупива́ємая Ча́ше, духо́вную жа́жду на́шу утоля́ющая."]},{"h":"Молитва","ps":["О Премилосе́рдая Влади́чице! К Твоєму́ заступле́нію ни́ні прибіга́єм, моле́ній на́ших не пре́зри, но ско́ро ісціли́ тя́жким неду́гом пія́нства одержи́мих бра́тій і сестр на́ших і того́ ра́ди от ма́тере своєя́, Це́ркве Христо́ви, і от спасе́нія отпада́ющих. О Всеми́лостивая Ма́ти Бо́жия, косни́ся серде́ць їх і ско́ро возста́ви от паде́ній гріхо́вних, ісціли́ я і ко спаси́тельному воздержа́нію приведи́. Умоли́ Си́на Своєго́, Христа́ Бо́га на́шего, да прости́ть нам согріше́нія на́ша і не отврати́ть ми́лости Своєя́ от люде́й Свої́х, но да укріпи́ть їх в трезве́нії і цілому́дрії. Прийми́, Пресвята́я Богоро́дице, моли́тви роди́телей, о ча́діх свої́х сле́зи пролива́ющих; жен, о мужеіх свої́х рида́ющих; чад, си́рих і убо́гих, заблу́ждшими оста́вленних, і всіх нас, к іко́ні Твоє́й припа́дающих, – і да при́йдеть сей вопль наш моли́твами Твої́ми ко Престо́лу Всеви́шняго. Покри́й і соблюди́ нас от лука́ваго ловле́нія і всіх ко́зней вра́жиїх, в стра́шний же час ісхо́да на́шего помози́ проіти́ непреткнове́нно возду́шная мита́рства і моли́твами Твої́ми ізба́ви ві́чнаго осужде́нія, да покри́єть нас ми́лость Бо́жия во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Днесь притеце́м ві́рнії / к Боже́ственному і пречу́дному о́бразу Пресвяти́я Богома́тері, / напоя́ющей ві́рних сердця́ / небе́сною Неупива́ємою Ча́шею Своєго́ милосе́рдія / і лю́дем ві́рним чудеса́ показу́ющей. / Я́же ми ви́дяще і сли́шаще / духо́вно пра́зднуєм і те́плі вопіє́м: / Влади́чице преми́лостивая, / ісціли́ на́ша неду́ги і стра́сті / моля́щи Си́на Твоєго́ Христа́ Бо́га на́шего // спасти́ ду́ші на́ша."]},{"h":"Кондак, глас 6","ps":["Предста́тельство христия́н непости́дноє, хода́тайство ко Творцю́ непрело́жноє, не пре́зри грі́шних моле́ній гла́си, но предвари́, я́ко Блага́я, на по́мощ нас, ві́рно зову́щих Ті; ускори́ на моли́тву і потщи́ся на умоле́ніє, предста́тельствующи при́сно, Богоро́дице, чту́щих Тя."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтем о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Прибавлення ума»","e":"Akathist to the Theotokos before her icon “Increaser of Intellect”","secs":[{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́в Бо́жієй Ма́тері, Небесе́ і землі́ Цари́це, врачевство́ духо́вноє всему́ ми́ру подаю́щей, благода́рная пі́нія прино́сим о дарова́нії Боже́ственнаго сокро́вища, чудотво́рния іко́ни Єя́, Прибавле́ніє ума́ нарече́нния, є́юже огражда́єми, ра́дуємся сві́тло і с любо́вію взива́єм:","Ра́дуйся, Всеми́лостивая Влади́чице, прему́дрость і ра́зум ві́рним лю́дем Твої́м да́рующая."]},{"h":"Ікос 1","ps":["А́нгел предста́тель по́слан бисть во град Назаре́т к чи́стій Отрокови́це Марі́ї рещи́: \"Ра́дуйся, Тобо́ю бо Син Бо́жий воплоти́ться\". Пречи́стая же Ді́ва, благові́стіє Арха́нгела сли́шавши, во смире́нії се́рдця отвіща́: \"Се, Раба́ Госпо́дня, бу́ди Мні по глаго́лу твоєму́\". Ми же грі́шнії, благогові́йно чту́ще Ма́тер Христа́ Бо́га на́шего, я́ко от А́нгела научи́хомся, та́ко со умиле́нієм вопіє́м Благода́тній:","Ра́дуйся, Благослове́нная в жена́х;","ра́дуйся, у Го́спода обрі́тшая благода́ть.","Ра́дуйся, си́лою Всеви́шняго осіне́нная;","ра́дуйся, Ду́хом Святи́м освяще́нная.","Ра́дуйся, ві́рная Рабо́ Госпо́дня;","ра́дуйся, Спаси́теля ми́ра ро́ждшая.","Ра́дуйся, Богоізбра́нная Отрокови́це;","ра́дуйся, Небесе́ і землі́ Цари́це.","Ра́дуйся, Ма́ти Сві́та, всіх просвіща́ющаго;","ра́дуйся, ві́рних сми́сли озаря́ющая.","Ра́дуйся, прему́дрих превосходя́щая ра́зум;","ра́дуйся, я́ко Тя ублажа́ють всі ро́ди.","Ра́дуйся, Всеми́лостивая Влади́чице, прему́дрость і ра́зум ві́рним лю́дем Твої́м да́рующая."]},{"h":"Кондак 2","ps":["Ви́дящи, Всенепоро́чная, жела́ніє люде́й новопросвіще́нних, благослови́ла єси́ єва́нгельських та́їн благові́стника апо́стола Луку́ написа́ти пречи́стаго ли́ка Твоєго́ ізображе́ніє і проглаго́лала єси́: \"С сим о́бразом благода́ть Моя́ і си́ла да бу́деть\". Ті́мже благогові́йно покланя́ющеся пред святи́ми іко́нами Твої́ми, і́миже весь мир христия́нський украси́ла єси́, благода́рственно вопіє́м о Тебі́ Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум Небе́сний открива́ющи, Пречи́стая Ді́во, мно́гажди благоволи́ла єси́ яви́ти всім ві́рним, какова́ єсть во́ля Бо́жия, блага́я і соверше́нная, і всяк ум превосходя́щая. При́зри на нас, Всепі́тая Богоро́дице, озари́ сві́том і́стини, уті́ши нас я́ко Ма́ти, наста́ви нас на путь пра́вди, да возопіє́м моля́щеся Тебі́ та́ко:","Ра́дуйся, Бо́жию Прему́дрость, Христа́, роди́вшая;","ра́дуйся, Бо́га челові́ком соєдини́вшая.","Ра́дуйся, сві́том ра́зума ду́ші на́ша просвіща́ющая;","ра́дуйся, неізрече́нную сла́ву Бо́жию вмеща́ющая.","Ра́дуйся, почита́ющих святи́я іко́ни освяща́ющая;","ра́дуйся, духо́вная сокро́вища ще́дро раздаю́щая.","Ра́дуйся, честни́м Твої́м іко́нам благода́ть да́рующая;","ра́дуйся, поклоне́ніє пред о́брази Твої́ми Сама́ приє́млющая.","Ра́дуйся, ісціле́нія от іко́н Твої́х ізлива́ющая;","ра́дуйся, к Небесе́м уми́ і сердця́ на́ша возводя́щая.","Ра́дуйся, всю вселе́нную луча́ми Твоєя́ благода́ті озаря́ющая;","ра́дуйся, с Си́ном Твої́м і Бо́гом ві́чно ца́рствующая.","Ра́дуйся, Всеми́лостивая Влади́чице, прему́дрость і ра́зум ві́рним лю́дем Твої́м да́рующая."]},{"h":"Кондак 3","ps":["Си́лою благода́тною осіня́ємі, благочести́вії лю́діє во град Назаре́т прийдо́ша і обріто́ша та́мо дом Богоро́дичен, іді́же Пречи́стая Ді́ва роди́ся і благові́стіє Арха́нгела прия́т, і пренесо́ша дом той в зе́млю Італі́йськую, во град Лоре́то. Верху́ же до́ма о́наго дони́ні єсть о́браз Богоро́дичен, от дре́ва ре́зан, єго́же А́нгельськия Небе́сния Си́ли неви́димо окружа́ють і благолі́пно честву́ють, ра́достні вопію́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи к ро́ду христия́нському Ма́тернєє милосе́рдіє, вся конці́ землі́ ко спасе́нію призива́єши, Пречи́стая, ті́мже у́бо наро́ди разноязи́чнії от мно́гих стран прихо́дять в дом Твой, і пред іко́ною Твоє́ю покая́ніє прино́сять, і к жи́зні но́вій благода́тноє укріпле́ніє приє́млють. Сего́ ра́ди от восто́ка до за́пада просла́влена бисть іко́на Твоя́ чудеси́ мно́гими, і ізба́вленнії от болі́зней, скорбе́й і напа́стей лю́діє прино́сять Ті благодаре́нія, взива́юще:","Ра́дуйся, до́ме, єго́же созда́ Себі́ Прему́дрость Бо́жия;","ра́дуйся, гра́де Бо́жий, і́же от ма́лаго гра́да Назаре́та проізи́де.","Ра́дуйся, дом Бо́жий вхожде́нієм Твої́м озари́вшая;","ра́дуйся, Отрокови́це, Свята́я Святи́х бо́льшая.","Ра́дуйся, с Предві́чним Богомладе́нцем в Назаре́т прише́дшая;","ра́дуйся, та́їнству спасе́нія ро́да челові́чеськаго послужи́вшая.","Ра́дуйся, лі́ствице, є́юже восхо́дим от землі́ на Не́бо;","ра́дуйся, всему́ ми́ру преди́вний покро́ве.","Ра́дуйся, я́ко с ві́рою покланя́ємся пречи́стаго ли́ка Твоєго́ ізображе́нію;","ра́дуйся, я́ко от него́ приє́млем благода́тния да́ри во спасе́ніє.","Ра́дуйся, ди́вная зна́менія іко́нами Твої́ми соверша́ющая;","ра́дуйся, род христия́нський держа́вно заступа́ющая.","Ра́дуйся, Всеми́лостивая Влади́чице, прему́дрость і ра́зум ві́рним лю́дем Твої́м да́рующая."]},{"h":"Кондак 4","ps":["Бу́рею ско́рби ве́лія одержи́м бі ізо́граф ні́кий в помраче́нії ра́зума, от земни́х враче́й по́льзи не получи́вий. Тогда́ Пречи́стая Ма́ти Го́спода яви́ся боля́щему в том же о́бразе, і́же і дом Єя́ во гра́ді Лоре́то освяща́єть, і запові́да іко́ну написа́ти. Сіє́ іспо́лнив, ізо́граф ісціли́ся і от сего́ іко́ну новопи́санную Прибавле́ніє ума́ нарече́, поя́ пред не́ю хвале́бную піснь Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше лю́діє землі́ Ру́ськия, я́ко благоізво́ли Пресвята́я Богоро́диця да́ти їм в ра́дость і утіше́ніє іко́ну Свою́, Прибавле́ніє ума́ нарече́нную, украси́ша хра́ми і до́ми своя́ мно́гими спи́сками єя́, от ни́хже ди́вная зна́менія і чудеса́ оби́льно содіва́ються всім притека́ющим с ві́рою і пою́щим Преблагослове́нній такова́я:","Ра́дуйся, о́браз Твой честни́й во утіше́ніє і освяще́ніє нам дарова́вшая;","ра́дуйся, со іко́нами Твої́ми благода́тними неви́димо в до́ми на́ша входя́щая.","Ра́дуйся, болі́зні душе́вния і тіле́сния іко́ною Твоє́ю ско́ро врачу́ющая;","ра́дуйся, лю́б'ящия і чту́щия Твой о́браз от вся́ких бід ізбавля́ющая.","Ра́дуйся, оста́вленних врача́ми на Свої́ всемо́щнеї ру́ці приє́млющая;","ра́дуйся, благослове́ніє, здра́віє і ра́дованіє тім подаю́щая.","Ра́дуйся, я́ко от восто́ка і до за́пада і́м'я Твоє́ ублажа́ється;","ра́дуйся, зе́млю на́шу покро́вом ми́лости Твоєя́ осіня́ющая.","Ра́дуйся, помраче́нних умо́в ісціле́ніє;","ра́дуйся, по́мислов на́ших просвіще́ніє.","Ра́дуйся, позна́нія і́стини чи́стоє зерца́ло;","ра́дуйся, ві́ри пра́вия крі́пкоє забра́ло.","Ра́дуйся, Всеми́лостивая Влади́чице, прему́дрость і ра́зум ві́рним лю́дем Твої́м да́рующая."]},{"h":"Кондак 5","ps":["Боготе́чній звізді́ подо́бна яви́ся іко́на Твоя́, Богома́ти: страну́ бо на́шу і гра́ди єя́ освяща́єть, су́щих во тьмі неві́жества сві́том богові́дінія озаря́єть, ра́зум наш, страстьми́ помраче́нний, просвіща́єть, заблу́ждшия наставля́єть на путь ді́ланія за́повідей Си́на Твоєго́ і Бо́га, Єму́же благода́рственно вопіє́м: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше ди́вную іко́ну Богома́тере і позна́вше ю і́стинноє Боже́ственноє сокро́вище, к ней усе́рдно притека́єм, в неду́зіх ісціле́ніє, в ско́рбіх утіше́ніє, в біда́х ізбавле́ніє приє́млем і ра́достно поє́м Засту́пниці на́шей:","Ра́дуйся, Ма́ти Сві́та присносу́щнаго, благода́тію всю вселе́нную озари́вшаго;","ра́дуйся, Со́лнце Пра́вди, Христа́ Бо́га на́шего, яви́вшая.","Ра́дуйся, мрак неві́дінія на́шего разгоня́ющая;","ра́дуйся, заря́ми благода́ті нас просвіща́ющая.","Ра́дуйся, свіще́ неугаси́мая, пла́мень ві́ри возжига́ющая;","ра́дуйся, світ богові́дінія всім пролива́ющая.","Ра́дуйся, доброді́телі путь освіща́ющая;","ра́дуйся, ве́сну спасе́нія нам возвіща́ющая.","Ра́дуйся, явле́нієм іко́ни Твоєя́ ві́рних осіява́ющая;","ра́дуйся, от бід і напа́стей крі́пкою руко́ю ізима́ющая.","Ра́дуйся, любве́ Боже́ственния світи́льниче;","ра́дуйся, святи́ні преми́рния істо́чниче.","Ра́дуйся, Всеми́лостивая Влади́чице, прему́дрость і ра́зум ві́рним лю́дем Твої́м да́рующая."]},{"h":"Кондак 6","ps":["Пропові́дуєть мир весь ми́лості Твоя́, Ма́ти Го́спода на́шего, во всіх бо конці́х землі́ іко́на Твоя́, Прибавле́ніє ума́ імену́ємая, луча́ми чуде́с сія́єть, просвіща́ющи ду́ші на́ша сві́том Бо́жия благода́ті і подвиза́ющи пі́ти просла́вльшему Тя Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ в честні́й іко́ні Твоє́й, Богоро́дице, світ спасе́нія всім блужда́ющим во тьмі гріхо́в і страсте́й, і всім моля́щимся пред не́ю с ві́рою і благогові́нієм ско́рая по́мощ подає́ться. Умо́в на́ших омраче́ніє сві́том Твої́м отжени́, Всепі́тая, і да́руй і́стинний Світ узрі́ти всім с любо́вію вопію́щим Ті си́це:","Ра́дуйся, звіздо́ незаходи́мая, Со́лнце Пра́вди в мир вводя́щая;","ра́дуйся, Ма́ти Сві́та і́стиннаго, ду́ші ві́рних просвіща́ющаго.","Ра́дуйся, сві́тлим покро́вом ум наш омраче́нний осіня́ющая;","ра́дуйся, заре́ невече́рняя, мглу на́ших гріхо́в разгоня́ющая.","Ра́дуйся, во благода́тнем уче́нії наставля́ющая;","ра́дуйся, тьми і ві́чних мук нас ізбавля́ющая.","Ра́дуйся, от сіте́й вра́жиїх свобожда́ющая;","ра́дуйся, безу́міє ми́ра побіжда́ющая.","Ра́дуйся, душевре́дних уче́ній низложе́ніє;","ра́дуйся, душеполе́зних зна́ній дарова́ніє.","Ра́дуйся, іко́ною Твоє́ю нас утіша́ющая;","ра́дуйся, сві́том ра́дости ду́ші веселя́щая.","Ра́дуйся, Всеми́лостивая Влади́чице, прему́дрость і ра́зум ві́рним лю́дем Твої́м да́рующая."]},{"h":"Кондак 7","ps":["Хотя́щи всім челові́ком спасти́ся і в ра́зум і́стини прийти́, Пречи́стая Ма́ти Свой о́браз, Прибавле́ніє ума́ імену́ємий, дарова́ла єсть нам, да всі с ві́рою моля́щіїся пред ним, крі́пость сло́ва, і ра́зум, і му́дрость приі́мше, в тишині́ помисло́в Царю́ і Бо́гу на́шему пою́ть: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вая і пресла́вная чудеса́ явля́єши, Ма́ти Бо́жия, ві́рним лю́дем свято́ю іко́ною Твоє́ю: си́лою благода́ті Христо́ви помраче́нния умо́м просвіща́єши, от безу́мія отвраща́єши, разсла́бленния укріпля́єши і всім притека́ющим к ціле́бному Твоєму́ о́бразу ско́рую по́мощ подає́ши, подвиза́ющи пі́ти Тебі́ такова́я:","Ра́дуйся, із глубини́ неві́дінія ізвлача́ющая;","ра́дуйся, мно́гія в ра́зумі просвіща́ющая.","Ра́дуйся, сло́во прему́дрости прося́щим да́рующая;","ра́дуйся, несми́сленних разу́мни содева́ющая.","Ра́дуйся, гріхо́вния по́мисли отгоня́ющая;","ра́дуйся, сердца́ ожесточе́нная ум'ягча́ющая.","Ра́дуйся, ум к Бо́гу возвиша́ющая;","ра́дуйся, нему́дрия умудря́ющая.","Ра́дуйся, ко благоче́стію наставля́ющая;","ра́дуйся, ві́чною ра́достію одаря́ющая.","Ра́дуйся, к Си́ну Твоєму́ і Бо́гу моли́тви ві́рних принося́щая;","ра́дуйся, і Сама́ непреста́нно у Престо́ла Вседержи́теля о всіх моля́щаяся.","Ра́дуйся, Всеми́лостивая Влади́чице, прему́дрость і ра́зум ві́рним лю́дем Твої́м да́рующая."]},{"h":"Кондак 8","ps":["Стра́нно єсть ви́діти, ка́ко іко́на Твоя́, Пречи́стая Богоро́дице Ді́во, руко́ю челові́чеською напи́санная, си́лою Твоє́ю Боже́ственною духо́в тьми прогоня́єть, не́мощію ума́ одержи́мим ра́зум подає́ть і всіх неудо́б уча́щихся сві́тло умудря́єть; ті́мже і ми, во грісі́х погиба́ющії, мо́лим Тя со слеза́ми: ізба́ви нас от враг ви́димих і неви́димих, от тьми неразу́мія і мра́ка пре́лести, да всегда́ поє́м Спаси́телю і Бо́гу на́шему: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся земля́ на́ша преіспо́лнена єсть, а́ки звізда́ми богосві́тлими, чудотво́рними о́бразами Твої́ми, Богоро́дице Ді́во, в не́йже і сія́ іко́на Твоя́, Прибавле́ніє ума́ нарече́нная, благода́тію сія́єть і согріва́єть оледені́вшая сердця́ на́ша зна́меньми ми́лости Твоєя́ к нам грі́шним. Сего́ ра́ди пред ли́ком Твої́м святи́м прекло́ньше колі́на, воспіва́єм Тя, Всепречи́стая Ма́ти на́ша, та́ко:","Ра́дуйся, ско́рби на́ша в ра́дость претворя́ющая;","ра́дуйся, от разжже́нних стріл лука́ваго нас защища́ющая.","Ра́дуйся, ві́рних ра́зум просвіща́ющая;","ра́дуйся, неві́рния посрамля́ющая.","Ра́дуйся, младе́нцев воспита́ніє і благода́тноє охране́ніє;","ра́дуйся, ю́них наставле́ніє і цілому́дренноє огражде́ніє.","Ра́дуйся, неудо́б уча́щимся ра́зум подаю́щая;","ра́дуйся, помраче́нния умо́м ісціля́ющая.","Ра́дуйся, вра́жия сі́ті разруша́ющая;","ра́дуйся, благода́тію де́мони прогоня́ющая.","Ра́дуйся, Ма́ти щедро́т і милосе́рдія;","ра́дуйся, спасе́нія на́шего наде́ждо.","Ра́дуйся, Всеми́лостивая Влади́чице, прему́дрость і ра́зум ві́рним лю́дем Твої́м да́рующая."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ А́нгельськоє благогові́йно Тебі́ слу́жить, Небесе́ і землі́ Цари́це, челові́чеський же род хвали́ Тебі́ прино́сить і Твою́ святу́ю іко́ну почита́єть, сію́ бо во отра́ду і утіше́ніє дарова́ла єси́ нам. Научи́ нас, о Всеблага́я, досто́йно сла́вити Тя і воспіва́ти ро́ждшемуся от Тебе́ Спаси́телю ми́ра: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії челові́честії недоуміва́ють позна́ти та́йну служе́нія Твоєго́ ро́ду христия́нському, Богоро́дице, ніже́ мо́гуть із'ясни́ти си́лу чудотво́рную, от іко́н Твої́х проісходя́щую на вся́ку по́льзу душе́вную і тіле́сную челові́ком. Ми же правосла́внії, со слеза́ми ра́дости пред іко́ною Твоє́ю свято́ю предстоя́ще, прославля́єм Тя, Благода́тная, і глаго́лем:","Ра́дуйся, А́нгелов ра́дованіє;","ра́дуйся, Арха́нгелов ликова́ніє.","Ра́дуйся, Ю́же на возду́сі сріта́ють Херуви́ми;","ра́дуйся, Є́йже похва́льная прино́сять Серафи́ми.","Ра́дуйся, сві́тлоє Це́ркве Небе́сния і земни́я украше́ніє;","ра́дуйся, всіх челові́к і безпло́тних удивле́ніє.","Ра́дуйся, от во́їнств Небе́сних почита́ємая;","ра́дуйся, от земноро́дних поклоне́нієм прославля́ємая.","Ра́дуйся, о́бразом Твої́м уми́ на́ша возводя́щая к ми́ру Го́рнему;","ра́дуйся, Путеводи́тельнице на́ша ко Оте́честву Небе́сному.","Ра́дуйся, всіх нас при Кресті́ Си́на Твоєго́ усинови́вшая;","ра́дуйся, сія́нієм душі́ Твоєя́ всю зе́млю просвіти́вшая.","Ра́дуйся, Всеми́лостивая Влади́чице, прему́дрость і ра́зум ві́рним лю́дем Твої́м да́рующая."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ мир от безу́мія і пре́лести вра́жия, Человіколю́бець Госпо́дь чу́дную іко́ну Твою́, Богома́ти, дарова́, пред не́юже помраче́ннії умо́м ісціля́ються, бісну́ющіїся от де́монов свобожда́ються, скорб'я́щії утіше́ніє і ра́дость обріта́ють. Ті́мже прославля́юще Бо́га, подаю́щаго нам такови́я ми́лости, вопіє́м Єму́ благода́рні: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ необори́мая і покро́в нам, Всенепоро́чная, сопроти́в ополче́ній ви́димих і неви́димих враг, огражда́ющи нас от вся́ких бід і болі́зней. Сего́ ра́ди припа́дающе ко іко́ні Твоє́й с ві́рою в по́мощ благода́тную і врачевство́ всіх неду́гов душе́вних і тіле́сних, ра́достно вопіє́м Ті си́це:","Ра́дуйся, от путе́й поги́бельних нас удаля́ющая;","ра́дуйся, на вся́ку і́стину і пра́вду наставля́ющая.","Ра́дуйся, ду́ха болі́зні і уни́нія отгна́ніє;","ра́дуйся, ду́ха ра́зума і крі́пости стяжа́ніє.","Ра́дуйся, враги́ си́лою Бо́жиєю посрамля́ющая;","ра́дуйся, сові́ти нечести́вих разоря́ющая.","Ра́дуйся, бесну́ющимся здра́віє подаю́щая;","ра́дуйся, вся лю́тия неду́ги врачу́ющая.","Ра́дуйся, от сме́рти духо́вния нас ізбавля́ющая;","ра́дуйся, слеза́ми Твої́ми гріхи́ на́ша омива́ющая.","Ра́дуйся, ра́достію духо́вною нас ди́вно насища́ющая;","ра́дуйся, в жизнь бу́дущаго ві́ка нас вводя́щая.","Ра́дуйся, Всеми́лостивая Влади́чице, прему́дрость і ра́зум ві́рним лю́дем Твої́м да́рующая."]},{"h":"Кондак 11","ps":["Пі́ніє благода́рственноє прино́сим пред пречи́стим о́бразом Твої́м, Пренепоро́чная, за неізрече́нноє Твоє́ милосе́рдіє і мо́лимся, о Богоблагода́тная: огради́ ум наш і се́рдце от тлітво́рних уче́ній, неві́рія і суєві́рія, сохрани́ зе́млю на́шу от вся́ких нестроє́ній, врага́ми ві́ри воздвиза́ємих, і сподо́би нас чи́стим се́рдцем сла́вити Созда́теля на́шего, пою́ще піснь: Аллилу́я."]},{"h":"Ікос 11","ps":["Я́ко світоприє́мную свіщу́ зрим іко́ну Твою́, Богома́ти, сія́нієм чуде́с зе́млю на́шу просвіща́ющую, на путь спасе́нія нас наставля́ющую і сердця́ на́ша любо́вію воспламеня́ющую к Тебі́, Пречи́стій Ма́тері Го́спода. Ми же, ві́дуще си́лу благода́ті Твоєя́, пі́сньми ра́достними прославля́єм Тя си́це:","Ра́дуйся, прему́дростію Соломо́на преви́шшая;","ра́дуйся, сокрове́нния та́йни Бо́жия ві́рним открива́ющая.","Ра́дуйся, любому́дрия нему́дрия явля́ющая;","ра́дуйся, мо́лніє, ду́ші просвіща́ющая.","Ра́дуйся, су́єтную му́дрость ві́ка сего́ посрамля́ющая;","ра́дуйся, осліпле́нния є́ю на путь пра́вий наставля́ющая.","Ра́дуйся, і́скренні моля́щимся ум обновля́ющая;","ра́дуйся, в час недоумі́ній мисль бла́гу на се́рдці полага́ющая.","Ра́дуйся, прему́дрости і бла́гости Бо́жия открове́ніє;","ра́дуйся, яви́вшая нам ди́вную іко́ну Твою́ я́ко дар Небе́сний.","Ра́дуйся, істо́чниче ра́дости непреста́нния;","ра́дуйся, Го́рняго ми́ра красото́ неізрече́нная.","Ра́дуйся, Всеми́лостивая Влади́чице, прему́дрость і ра́зум ві́рним лю́дем Твої́м да́рующая."]},{"h":"Кондак 12","ps":["Благода́ть Боже́ственную іспроси́ у Си́на Твоєго́ і Бо́га, о Всеблага́я, пода́ждь нам ру́ку по́мощі, да не поги́бнем во грісі́х на́ших; согрі́й нас любо́вію Твоє́ю, очи́сти уми́ на́ша от гордели́вих помисло́в, просвіти́ серде́чния о́чі на́ші к зрі́нію путі́ смире́нія і сподо́би нас в жи́зні сей і в Ца́рстві Небе́снім воспіва́ти Творцю́ і Созда́телю на́шему: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще чудеса́, от іко́ни Твоєя́ явле́нная, Влади́чице, хва́лим, сла́вим і велича́єм Тя, честні́йшую воі́стину Херуви́м і сла́внійшую без сравне́нія Серафи́м. При́зри с Небесе́, Богоро́дице, на предстоя́щия пред свято́ю іко́ною Твоє́ю і благода́ть Твою́ низпосли́ нам, ізба́ви от вся́ких бід і іскуше́ній вра́жиїх всіх я́ко Засту́пнице і Храни́тельнице на́шей вопію́щих Ті:","Ра́дуйся, моли́твами Твої́ми весь мир спаса́ющая;","ра́дуйся, сві́том чистоти́ Твоєя́ всіх просвіща́ющая.","Ра́дуйся, ни́нішняго ско́рбнаго ві́ка утіше́ніє;","ра́дуйся, во́лі Госпо́дні открове́ніє.","Ра́дуйся, зе́млю Ру́ськую в достоя́ніє Себе́ ізбра́вшая;","ра́дуйся, явле́нієм чудотво́рних іко́н Твої́х сію́ благослови́вшая.","Ра́дуйся, чудеси́ от о́браза Твоєго́ к Сві́ту і́стини нас возводя́щая;","ра́дуйся, почита́ющих лик Твой незри́мо благода́тію осіня́ющая.","Ра́дуйся, ра́дость благода́тную в сердця́ боголюби́вая ізлива́ющая;","ра́дуйся, две́рі милосе́рдія Бо́жия хода́тайством Твої́м отверза́ющая.","Ра́дуйся, в стяжа́нії даро́в Свята́го Ду́ха нам поможе́ніє;","ра́дуйся, Же́но, єди́на Чи́стая і Благослове́нная.","Ра́дуйся, Всеми́лостивая Влади́чице, прему́дрость і ра́зум ві́рним лю́дем Твої́м да́рующая."]},{"h":"Кондак 13","ps":["О всепі́тая Ма́ти Присносу́щнаго Сві́та і О́тчія Прему́дрости! Ти єси́ світ омраче́нних, прибавле́ніє ума́ і ра́дость серде́ць на́ших; усли́ши і прийми́ моле́ніє нас грі́шних, умудри́ нас неразу́мних і наста́ви на пі́ніє і моли́тву пред іко́ною Твоє́ю ди́вною. Не преста́й моли́ти Си́на Твоєго́ і Бо́га о нас, недосто́йних рабі́х Твої́х, сла́в'ящих Тя і пою́щих Єму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел предста́тель по́слан бисть во град Назаре́т к чи́стій Отрокови́це Марі́ї рещи́: \"Ра́дуйся, Тобо́ю бо Син Бо́жий воплоти́ться\". Пречи́стая же Ді́ва, благові́стіє Арха́нгела сли́шавши, во смире́нії се́рдця отвіща́: \"Се, Раба́ Госпо́дня, бу́ди Мні по глаго́лу твоєму́\". Ми же грі́шнії, благогові́йно чту́ще Ма́тер Христа́ Бо́га на́шего, я́ко от А́нгела научи́хомся, та́ко со умиле́нієм вопіє́м Благода́тній:","Ра́дуйся, Благослове́нная в жена́х;","ра́дуйся, у Го́спода обрі́тшая благода́ть.","Ра́дуйся, си́лою Всеви́шняго осіне́нная;","ра́дуйся, Ду́хом Святи́м освяще́нная.","Ра́дуйся, ві́рная Рабо́ Госпо́дня;","ра́дуйся, Спаси́теля ми́ра ро́ждшая.","Ра́дуйся, Богоізбра́нная Отрокови́це;","ра́дуйся, Небесе́ і землі́ Цари́це.","Ра́дуйся, Ма́ти Сві́та, всіх просвіща́ющаго;","ра́дуйся, ві́рних сми́сли озаря́ющая.","Ра́дуйся, прему́дрих превосходя́щая ра́зум;","ра́дуйся, я́ко Тя ублажа́ють всі ро́ди.","Ра́дуйся, Всеми́лостивая Влади́чице, прему́дрость і ра́зум ві́рним лю́дем Твої́м да́рующая."]},{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́в Бо́жієй Ма́тері, Небесе́ і землі́ Цари́це, врачевство́ духо́вноє всему́ ми́ру подаю́щей, благода́рная пі́нія прино́сим о дарова́нії Боже́ственнаго сокро́вища, чудотво́рния іко́ни Єя́, Прибавле́ніє ума́ нарече́нния, є́юже огражда́єми, ра́дуємся сві́тло і с любо́вію взива́єм:","Ра́дуйся, Всеми́лостивая Влади́чице, прему́дрость і ра́зум ві́рним лю́дем Твої́м да́рующая."]},{"h":"Молитва","ps":["О Пречи́стая Богоро́дице, даро́в духо́вних Пода́тельнице, до́ме, єго́же созда́ Себі́ Прему́дрость Бо́жия, от ми́ра к преми́рним ум наш возводя́щая і всіх к позна́нію ра́зума приводя́щая! Прийми́ моле́бноє пі́ніє от нас, недосто́йних рабо́в Твої́х, с ві́рою і умиле́нієм покланя́ющихся пред пречи́стим о́бразом Твої́м. Умоли́ Си́на Твоєго́ і Бо́га на́шего, да да́руєть власте́м на́шим му́дрость і си́лу, судія́м пра́вду і нелицеприя́тіє, па́стирем му́дрость духо́вную і ре́вность, наста́вником смиренному́дріє, ча́дом послуша́ніє, всім же нам дух ра́зума і благоче́стія, дух смире́нія і кро́тости, дух чистоти́ і пра́вди. Пода́ждь нам, всепі́тая Ма́ти, ума́ прибавле́ніє, умири́, соєдини́ во вражді́ і разділе́нії су́щия і положи́ їм сою́з любве́ неразруши́мий, всіх заблу́ждших от неразу́мія к сві́ту і́стини Христо́ви обрати́, на путь стра́ха Бо́жия, воздержа́нія і трудолю́бія наста́ви, сло́во прему́дрості і душа́м поле́зноє зна́ніє прося́щим да́руй, осіни́ нас ві́чною ра́достію, Херуви́мов честні́йшая і Серафи́мов сла́внійшая су́щи. Ми же, ди́вная діла́ і многоразу́мную прему́дрость Бо́жию в ми́рі і жи́зні на́шей ви́дяще, устрані́мся земни́я суєти́ і лука́вих попече́ній, і уми́ і сердця́ на́ша на Небеса́ возведе́м, я́ко да Твої́м заступле́нієм і по́мощію сла́ву, хвалу́, благодаре́ніє і поклоне́ніє за вся в Тро́йці сла́вимому Бо́гу і всіх Созда́телю воздади́м, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 3","ps":["Во́лею Отця́ Небе́снаго зачала́ Си́на Бо́жия, / без сі́мені земна́го отця́, / пре́жде творе́нія ми́ра от отця́ без ма́тері рожде́ннаго / пло́тію родила́ єси́, / і Єго́же моли́ о дарова́нії нам ума́ // ко спасе́нію душ на́ших."]},{"h":"Кондак, глас 6","ps":["Рожде́ннаго Ду́хом от Отця́ Небе́снаго, / пре́жде сотворе́нія денни́ці, / Тобо́ю пло́тію Рожде́ннаго без отця́, / не наруши́в ді́вства, / Того́ умоли́ помо́ч нам победи́ть / за́вистью одержи́маго па́дшаго денни́цю. / Да одержи́м по́лную побі́ду / над дья́волом, ми́ром і пло́тію, // Твої́ми моли́твами, Богоневі́стная."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтем о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Визволення від бід страждущих»","e":"Akathist to the Theotokos before her icon “Deliverance of the Suffering from Woes”","secs":[{"h":"Кондак 1","ps":["Возбрани́ враго́м на́шим озлобля́ти нас і от Го́спода на́шего отлуча́ти, а нас научи́ пі́ти Тебі́ ве́село:","Ра́дуйся, от го́ря, ги́белі і бід стра́ждущих нас Ізбавле́ніє."]},{"h":"Ікос 1","ps":["А́нгелов мно́жество, по Твоєму́, Ма́ти на́ша, велі́нію, ополча́ються на ізбавле́ніє на́ше гро́зно, Ти же прийми́ моли́тву сію́:","Ра́дуйся, А́нгелов на спасе́ніє на́ше посила́ющая;","ра́дуйся, Цари́це го́рних чино́в, їх небе́сную по́мощ нам даю́щая.","Ра́дуйся, А́нгелом храни́ти нас повеліва́ющая;","ра́дуйся, Во́їнством А́нгельським враго́в на́ших поража́ющая.","Ра́дуйся, от го́ря, ги́белі і бід стра́ждущих нас Ізбавле́ніє."]},{"h":"Кондак 2","ps":["Ви́дя бе́дствующия толи́кую і такову́ю по́мощ Твою́ серде́чно Тя призива́ющим, наставля́ють тім пі́ти Си́ну Твоєму́ непреста́нно: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́ють мно́зі, я́ко дарова́ Тя Син Твой, Ізбавле́ніє от бід стра́ждущих, призива́ющим Тя си́це:","Ра́дуйся, бі́дствующих Ма́ти;","ра́дуйся, стра́ждущих утіше́ніє.","Ра́дуйся, безнаде́жних наде́ждо;","ра́дуйся, безпомо́щних по́моще.","Ра́дуйся, от го́ря, ги́белі і бід стра́ждущих нас Ізбавле́ніє."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго дарова́ Тя на по́мощ і спасе́ніє ми́ру, в біда́х погиба́ющу, і кто Тобо́ю ізба́влен бисть, поє́ть Си́ну Твоєму́: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи непостижи́мую любо́в к ро́ду челові́чеському, кі́ї сле́зи не отве́ргла єси́, і того́ не прину́дила призва́ти Тя, вопію́ще:","Ра́дуйся, бі́дствующих ско́роє усли́шаніє;","ра́дуйся, пліне́нних свобожде́ніє.","Ра́дуйся, погиба́ющих би́строє спасе́ніє;","ра́дуйся, печа́льних і ско́рбних утіше́ніє.","Ра́дуйся, от го́ря, ги́белі і бід стра́ждущих нас Ізбавле́ніє."]},{"h":"Кондак 4","ps":["Бу́ря несча́стій налета́єть на ни. Спаси́ нас, погиба́ющих, спаси́, Ізбавле́ніє от бід стра́ждущих, бу́рю поги́бельную на землі́ укроща́ющая і приє́млющая на́шу піснь: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша челові́честії ро́ди всю Твою́ ко христия́ном ди́вную любо́в і Твоє́ мо́щноє ізбавле́ніє от вся́ких находи́вших на них лю́тих, научи́шася пі́ти Тебі́:","Ра́дуйся, челові́чеськаго ро́да от бід Ізбавле́ніє;","ра́дуйся, уни́нія прогони́тельнице.","Ра́дуйся, бур жите́йських прекраще́ніє;","ра́дуйся, ра́дости по ско́рбі нам пода́тельнице.","Ра́дуйся, от го́ря, ги́белі і бід стра́ждущих нас Ізбавле́ніє."]},{"h":"Кондак 5","ps":["Боготе́чной звізді́ подо́б'ящаяся, мрак і темноту́ в гріхолюби́вих сердця́х разгоня́ющая, да во сві́ті Твоєя́ любві́ у́зрять Го́спода і вопію́ть Єму́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дяще лю́діє Росси́йстії Твоє́ неча́янноє от многообра́зних бід ізбавле́ніє, ра́достно пою́ть си́це:","Ра́дуйся, в біда́х на́ших От'я́тельнице;","ра́дуйся, печа́лей на́ших отгна́ніє.","Ра́дуйся, в ско́рбіх на́ше утіше́ніє;","ра́дуйся, в ра́достіх на́ше воздержа́ніє.","Ра́дуйся, от го́ря, ги́белі і бід стра́ждущих нас Ізбавле́ніє."]},{"h":"Кондак 6","ps":["Пропові́дають по́мощ Твою́ і любо́в Твою́, Ма́ти, все ісціле́нния, уте́шенния, оправда́нния і спасе́нния Тобо́ю от бід і пою́ть Твоєму́ Високодержа́вному Си́ну: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ нам світ спасе́нія во мглі поги́белі, окружи́вшей нас, і наста́вил єсть пі́ти Тебі́:","Ра́дуйся, мглу гріха́ разгоня́ющая;","ра́дуйся, тьму гріхо́вную істребля́ющая.","Ра́дуйся, мрак душі́ моєя́ просвіща́ющая;","ра́дуйся, сві́том ра́дости ду́шу мою́ ободря́ющая.","Ра́дуйся, от го́ря, ги́белі і бід стра́ждущих нас Ізбавле́ніє."]},{"h":"Кондак 7","ps":["Хотя́щим нам коне́чному отча́янію преда́тися отовсю́ду біда́м належа́щим, поми́слихом о Тебі́, Ізбавле́ніє от бід стра́ждущих, і ободри́хомся, і уті́шихомся, пою́ще Си́ну Твоєму́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую і нежда́нную показа́ Ти нам ми́лость Свою́, под Держа́вную ру́ку Твою́ нас восприя́вши, і отсю́да вопіє́м Ті:","Ра́дуйся, Цари́ця Держа́вная;","ра́дуйся, под Твою́ Держа́ву нас восприя́вшая.","Ра́дуйся, защи́ту Твою́ нам дарова́вшая;","ра́дуйся, враго́в на́ших пораже́ніє.","Ра́дуйся, от го́ря, ги́белі і бід стра́ждущих нас Ізбавле́ніє."]},{"h":"Кондак 8","ps":["Стра́нноє чу́до — на поги́бель обрече́нния, в ну́ждах том'я́щіяся, безчи́сленния внеза́пу спасе́ніє і ізбавле́ніє получа́ють от Тебе́, Вселю́б'ящей Ма́ти, пою́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Всі су́щії во мра́ці скорбе́й, всі обурева́ємия бу́рей несча́стій, прийді́те к до́брому приста́нищу і на́шему поможе́нію — покро́ву Ді́ви, Ізбавле́ніє от бід стра́ждущих, вопію́ще Єй:","Ра́дуйся, от гла́да нас ізбавля́ющая;","ра́дуйся, вредонося́щеє єстество́ от расти́тельнаго ми́ра отгоня́ющая.","Ра́дуйся, посі́ви, і ліса́, і все расту́щеє от поги́белі спаса́ющая;","ра́дуйся, земледі́льцев скорб'я́щих утіше́ніє і отра́до благослове́нная.","Ра́дуйся, от го́ря, ги́белі і бід стра́ждущих нас Ізбавле́ніє."]},{"h":"Кондак 9","ps":["Все существо́ челові́чеськоє хва́лить Тя, всі воспіва́ють Тя, многоразли́чноє ізбавле́ніє єму́ несу́щую і вмі́сто печа́лей ра́дость подаю́щую, пою́щим: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́я і многоу́мнії обезу́міша, ви́дяще Твоє́ би́строє, чуде́сноє от бід стра́ждущих ізбавле́ніє і умолко́ша нам, пою́щим Ті:","Ра́дуйся, чудеса́ми нас укріпи́вшая;","ра́дуйся, бі́ди чудеса́ми істреби́вшая.","Ра́дуйся, чудеса́ми нас вразуми́вшая;","ра́дуйся, іко́ною Твоє́ю нас возвесели́вшая.","Ра́дуйся, от го́ря, ги́белі і бід стра́ждущих нас Ізбавле́ніє."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ вся́кую ду́шу челові́чеськую любо́вію пече́шися о ней, до́ндеже не научи́ши ю пі́ти Си́ну Твоєму́: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіно́ю мир христия́нський храня́щи і ка́ждую ду́шу от враго́в огражда́ющи обрі́теся і прояви́ся ди́вний о́браз Твой, «Ізбавле́ніє от бід стра́ждущих», да просла́вим єго́, поклоні́мся і притеце́м к Твоєму́ заступле́нію, Ма́ти Бо́жия, воспіва́я:","Ра́дуйся, Ізба́вительнице на́ша;","ра́дуйся, наста́внице на́ша.","Ра́дуйся, весе́ліє на́ше;","ра́дуйся, ві́чная ра́досте на́ша.","Ра́дуйся, от го́ря, ги́белі і бід стра́ждущих нас Ізбавле́ніє."]},{"h":"Кондак 11","ps":["Пі́ніє непреста́нноє прино́сять Ті Тобо́ю ізба́вленнії і Тобо́ю па́ки ра́дость обрі́тшії, Боже́ственному Си́ну Твоєму́ пою́ть ра́достно: Аллилу́я."]},{"h":"Ікос 11","ps":["Світосія́ющим світи́лом лучеза́рним во мра́ці гріха́ яви́ся нам Твоя́ іко́на, «Ізбавле́ніє от бід стра́ждущих», ті́мже ра́дуємся ми, грі́шнії, іму́ще такову́ю чу́дную іко́ну Твою́ в хра́мі своє́м, я́ко зало́г Твоєго́ к нам і ко Оби́телі на́шей благоволе́нія, і наді́яся на Твоя́ ма́тернія моли́тви і ско́роє їх усли́шаніє, уми́льно глаго́лем:","Ра́дуйся, ра́достей істо́чниче;","ра́дуйся, печа́лей прогна́ніє.","Ра́дуйся, бід уменьше́ніє;","ра́дуйся, вся́каго поко́я пода́тельнице.","Ра́дуйся, от горя́, ги́белі і бід стра́ждущих нас Ізбавле́ніє."]},{"h":"Кондак 12","ps":["Благода́ть от іко́ни Твоєя́, «Ізбавле́ніє от бід стра́ждущих», теку́щая, ісціле́ній струї́ оби́льно подаю́щая і сердця́ весе́лієм оживля́ющая, побужда́єть всіх во́льной во́лей пі́ти о Тебі́, Ма́ти, Си́ну Твоєму́ і Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Воспіва́єм Твоєя́ іко́ни ди́вноє обновле́ніє, воспіва́єм Твоє́ ми́лостивноє на нас, грі́шних, призрі́ніє і, воспіва́юще, поє́м:","Ра́дуйся, от сме́рти і ві́чнаго огня́ ізима́ющая;","ра́дуйся, ме́ртвих воскреша́ющая.","Ра́дуйся, предсме́ртноє на́ше упова́ніє і защи́то;","ра́дуйся, по сме́рті на́ше упокоє́ніє.","Ра́дуйся, от го́ря, ги́белі і бід стра́ждущих нас Ізбавле́ніє."]},{"h":"Кондак 13","ps":["О, Всепі́тая, Вселюби́мая на́ша Ма́ти, умилосе́рдися ни́ні і поми́луй нас, в лю́тих і безисхо́дних біда́х су́щих, Єди́ному су́щу, нас ізбавля́ющу, і научи́ нас серде́чно воспіва́ти Бо́гу, спаса́ющему нас: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов мно́жество, по Твоєму́, Ма́ти на́ша, велі́нію, ополча́ються на ізбавле́ніє на́ше гро́зно, Ти же прийми́ моли́тву сію́:","Ра́дуйся, А́нгелов на спасе́ніє на́ше посила́ющая;","ра́дуйся, Цари́це го́рних чино́в, їх небе́сную по́мощ нам даю́щая.","Ра́дуйся, А́нгелом храни́ти нас повеліва́ющая;","ра́дуйся, Во́їнством А́нгельським враго́в на́ших поража́ющая.","Ра́дуйся, от го́ря, ги́белі і бід стра́ждущих нас Ізбавле́ніє."]},{"h":"Кондак 1","ps":["Возбрани́ враго́м на́шим озлобля́ти нас і от Го́спода на́шего отлуча́ти, а нас научи́ пі́ти Тебі́ ве́село:","Ра́дуйся, от го́ря, ги́белі і бід стра́ждущих нас Ізбавле́ніє."]},{"h":"Молитва","ps":["Ма́ти Бо́жия, по́моще і защи́то! Єгда́ потре́буєм, бу́ди Ізбавле́нієм нам, стра́ждущим і погиба́ющим от лю́тих бід, на Тя бо упова́єм і всегда́ вседу́шно Тебе́ призива́єм: умилосе́рдися і помози́, пожале́й і ізба́ви от бід стра́ждущих і погиба́ющих нас, от лю́тих сіте́й лука́ваго ісхити́, приклони́ у́хо Твоє́, і на́ші сле́зния, ско́рбния моли́тви прийми́ і, я́коже хо́щеши, упоко́й і обра́дуй нас. Научи́ послуша́ніє Го́споду Бо́гу приноси́ти, всім се́рдцем, все́ю душе́ю, всім єстество́м Си́на Твоєго́ возлюби́ти, плоди́ трудо́в досто́йни Єму́ приноси́ти. Умири́ сердця́ на́ша, да в єди́ном Ду́хі і всі́ми діла́ми на́шими просла́вим Безнача́льнаго Отця́ со Єдиноро́дним Єго́ Си́ном і с Пресвяти́м Благи́м і Животворя́щим Єго́ Ду́хом, і Твоє́ ми́лостивноє Ма́тернєє предста́тельство, ни́ні, і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Я́ко пресві́тлая звізда́ просія́ Боже́ственними чудеси́ святи́й Твой о́браз, луча́ми благода́ті і милосе́рдія Твоєго́ озари́во в нощі́ скорбе́й. Пода́ждь у́бо і нам, Всеблага́я Ді́во, Ізбавле́ніє от бід стра́ждущих, ісціле́ніє неду́гов душе́вних і тіле́сних, спасе́ніє і ве́лію ми́лость."]},{"h":"Кондак, глас 8","ps":["Ко іко́ні Твоє́й, пресвята́я Госпоже́, бедствующиє с верой притека́ють, заступле́нієм Твої́м ізбавляємиє от злих, но я́ко Ма́ти Христа́ Бо́га і нас свободи́ от лю́тих обстоя́ній, вре́менних і ві́чних, да зове́м Ті: Ра́дуйся, Ізбавле́ніє стра́ждущих от всіх бід."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтим О́браз Твой Святи́й, і́мже то́чиши ісціле́нія всім, с ві́рою притекающим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Всецариця» (Пантанасса)","e":"Akathist to the Theotokos before her icon “Queen of All” (Pantanassa)","secs":[{"h":"Кондак 1","ps":["Новоя́вленній Твоє́й іко́ні предстоя́ще ві́рнії уми́льно, воспіва́єм Ті, Всецари́це, раби́ Твої́; низпосли́ цільби́ к Тебі́ притека́ющим, да всі ра́достно зове́м Ті:","Ра́дуйся, Всецари́це, неду́ги на́ша благода́тію ісціля́ющая."]},{"h":"Ікос 1","ps":["А́нгел предста́тель с Небесе́ сшед, рече́ Всецари́це: ра́дуйся! І боговіща́нним гла́сом воплоща́єма Тя зря, Го́споди, возопи́ к Ней такова́я:","Ра́дуйся, глави́зно на́шего спасе́нія;","ра́дуйся, ісполне́ніє Зижди́телева смотре́нія.","Ра́дуйся, я́ко Тобо́ю Бог воплоти́ся;","ра́дуйся, я́ко Неви́димий в Тебі́ ізобрази́ся.","Ра́дуйся, Ми́лость ми́ра внутр прия́вшая;","ра́дуйся, одія́ніє пло́ті Сло́ву істка́вшая.","Ра́дуйся, уму́ непости́жная го́рняя сла́во;","ра́дуйся, сердца́ оживи́вшая небе́сная ма́нно.","Ра́дуйся, звіздо́, благода́ті сія́ніє;","ра́дуйся, істо́чниче, живи́я води́ ізлія́ніє.","Ра́дуйся, Богоро́дице, в жена́х благослове́нная;","ра́дуйся, ро́ждшая Спа́са Ді́во нетлі́нная.","Ра́дуйся, Всецари́це, неду́ги на́ша благода́тію ісціля́ющая."]},{"h":"Кондак 2","ps":["Безнача́льноє Сло́во Отроча́ мла́до Тобо́ю бисть, ісціле́нія подая́ Тя, Ді́во, чту́щим і неізрече́нноє Єго́ Рождество́ воспіва́ющим: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум недоразуміва́ємий разумі́ти Ді́ва і́щущи, возопи́ к служа́щему: «Я́ко Отрокови́ця чи́стая, ка́ко бу́ду Ви́шняго Ма́ти – із'ясни́ Мі?». К Ней же Гавриї́л рече́ со стра́хом, зови́й такова́я:","Ра́дуйся, Сові́та Ви́шняго ізбра́ннице;","ра́дуйся, гла́са моля́щихся скоропослу́шнице.","Ра́дуйся, Сокро́вище Христо́ва ми́ра;","ра́дуйся, люде́й Твої́х наде́ждо і си́ло.","Ра́дуйся, ра́ковия я́зви ди́вная губи́тельнице;","ра́дуйся, про́чих болі́зней ісціли́тельнице.","Ра́дуйся, єди́ноє ми́ру заступле́ніє;","ра́дуйся, ві́рноє в ско́рбіх ізбавле́ніє.","Ра́дуйся, плач і сле́зи при́сно утоля́ющая;","ра́дуйся, спасе́нія вхо́ди всім отверза́ющая.","Ра́дуйся, держа́вний покро́ве Афо́н населя́ющих;","ра́дуйся, же́зле мона́хов і миря́н.","Ра́дуйся, Всецари́це, неду́ги на́ша благода́тію ісціля́ющая."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго осіни́вши Тя, Отрокови́це, плоть прия́т неізрече́нно, показа́ Тя село́ сла́дкоє хотя́щим жа́ти спасе́ніє і пою́щим: Аллилу́я."]},{"h":"Ікос 3","ps":["Просла́вися ди́вно свята́я іко́на Твоя́, «Всецари́ця» імену́ємая, єгда́ цельбоно́сно яви́ся Твоє́, Богома́ти, ізображе́ніє; вопію́щим же пред ним с ві́рою ісціле́нія подає́ши, да умножа́ються пі́сні сицеви́я:","Ра́дуйся, Ма́ти незаходи́маго Сві́та;","ра́дуйся, претерпі́вших до конця́ побі́до.","Ра́дуйся, в болі́зніх і ско́рбіх су́щим врачева́ніє;","ра́дуйся, сиро́т і вдови́ць неруши́мая стіно́.","Ра́дуйся, две́рі ра́йськія отверза́ющая;","ра́дуйся, тружда́ющихся і обремене́нних заступа́ющая.","Ра́дуйся, о спасе́нії ві́рних хода́тайце;","ра́дуйся, за род челові́чеський моли́твеннице.","Ра́дуйся, лі́ствице небе́сная, возводя́щая от землі́ к небесі́;","ра́дуйся, водо́ жива́я, омива́ющая сме́ртния гріхи́.","Ра́дуйся, а́гнице, сердца́ незло́бивих храня́щая;","ра́дуйся, покро́ве, чад Це́ркве осіня́ющий.","Ра́дуйся, Всецари́це, неду́ги на́ша благода́тію ісціля́ющая."]},{"h":"Кондак 4","ps":["Живо́т ми́рові да́руя, Влади́ка ми́ра всели́ся во утро́бу Твою́ неіскусому́жно, Ма́тер ві́рних Тя показа́в, в ми́рі тіх воспіва́ти призва́: Аллилу́я."]},{"h":"Ікос 4","ps":["Пресла́вная соді́яшася о Тебі́, Гра́де Бо́жий, ісціле́нієм бива́ющим от святи́я іко́ни Твоєя́; сего́ ра́ди цільбоно́сния струї́ врачева́ній приє́млюще, благода́рственно, о Всецари́ці, вопіє́м:","Ра́дуйся, сна́добіє, боль утоля́ющеє;","ра́дуйся, прохла́до, жар неду́жних остужа́ющая.","Ра́дуйся, прижига́ющая ра́ковия я́зви а́ки пла́менем;","ра́дуйся, подима́ющая со одра́ оста́вленних врачми́.","Ра́дуйся, лик Свой пречи́стий ізбра́нним явля́ющая;","ра́дуйся, от гріхо́вних уз разріша́ющая.","Ра́дуйся, я́ко Тобо́ю ізбавле́ніє от сме́рти дарова́ся;","ра́дуйся, я́ко Тобо́ю неізче́тний сонм ві́рних оправда́ся.","Ра́дуйся, висото́, челові́чеськими по́мисли неізслі́дованная;","ра́дуйся, глубино́, єди́ним Сло́вом ізве́данная.","Ра́дуйся, проро́чествіє пре́жде Тебі́ би́вших патріа́рхов;","ра́дуйся, наста́внице Тебі́ моли́вшихся ієра́рхов.","Ра́дуйся, Всецари́це, неду́ги на́ша благода́тію ісціля́ющая."]},{"h":"Кондак 5","ps":["Пречи́стий Храм Спа́сов позна́хом Тя, Отрокови́це; к Тебі́ припа́даєм, Чи́стая, да нас соді́лаєши хра́ми Божества́, вопію́щих Єму́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́діша чи́ни а́нгельстії на руку́ Твоє́ю Созда́вшаго руко́ю челові́ки, і я́ко Влади́чицю разуміва́юще Тя єди́ну, а́ще і Рабо́ю Себі́ нарекла́ єси́, потща́шася пі́сньми послужи́ти Ті, Благослове́нній, сицеви́ми:","Ра́дуйся, Бо́гом поста́вленная преви́ше Небе́сних Сил;","ра́дуйся, чуде́сними ісціле́ньми ісполня́ющая мир.","Ра́дуйся, хвалу́ і сла́ву от небе́с сли́шащая;","ра́дуйся, благодаре́ніє от землі́ приє́млющая.","Ра́дуйся, я́ко сі́м'я тлі в сердця́х потреби́ла єси́;","ра́дуйся, я́ко ко́зней дия́вольських яре́м сокруши́ла єси́.","Ра́дуйся, юдо́ль плаче́вную іспо́лнившая ра́достію;","ра́дуйся, ско́рби ізміня́ющая в небе́сную сла́дость.","Ра́дуйся, благоуха́ніє Бо́гу прия́тноє;","ра́дуйся, ка́ющихся грі́шников весе́ліє ізря́дноє.","Ра́дуйся, броне́ пра́вди от іскуше́ній;","ра́дуйся, щі́те огражде́нія от вражди́ і нестроє́ній.","Ра́дуйся, Всецари́це, неду́ги на́ша благода́тію ісціля́ющая."]},{"h":"Кондак 6","ps":["Пропові́дници богоглаго́ливії, Спа́сови ученици́, предста́ша Ті, Ді́во, чу́дно, єгда́ от землі́ к небесі́ восходи́ла єси́, да єди́ним се́рдцем і усти́ воспою́ть Бо́гові: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ ди́вно благода́ть от іко́ни Твоєя́, Всецари́це, єгда́ ю́ноша, уче́ньми сатани́нськими омраче́нний, пред не́ю паде́ і недви́жим бисть; па́че ча́янія же от уз мра́чних свобожде́нний, со стра́хом і ра́достію взива́ше Ті си́це:","Ра́дуйся, ісправле́ніє нечести́ваго житія́;","ра́дуйся, утіше́ніє стра́ждущих лю́ті.","Ра́дуйся, бісо́вських по́лчищ от Це́ркве отгна́ніє;","ра́дуйся, мгли гріхо́вния разсі́яніє.","Ра́дуйся, ко́зней неви́димих упраздне́ніє;","ра́дуйся, де́монських чар всемо́щноє одолі́ніє.","Ра́дуйся, світи́льниче, прельще́нних наставля́яй;","ра́дуйся, о́блаче, неви́нних от зла покрива́яй.","Ра́дуйся, хо́лмі, небе́сною ма́нною пита́ющий;","ра́дуйся, доли́но, смире́нієм Христо́вим насища́ющая.","Ра́дуйся, ка́меню Небе́снаго Ца́рствія;","ра́дуйся, зерца́ло преві́чнаго Сві́та.","Ра́дуйся, Всецари́це, неду́ги на́ша благода́тію ісціля́ющая."]},{"h":"Кондак 7","ps":["Хотя́ да́ти Себі́ в снідь ві́рним, Христе́ Бо́же, благоволи́л єси́ от Ді́ви воплоти́тися, да приє́млюще Пречи́стоє Ті́ло і Кров Твою́, позна́ють Тя Бо́га соверше́ннаго; ті́мже див'я́щеся неізрече́нній прему́дрості сей зове́м: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє показа́ та́їнство я́влься Зижди́тель, со ученики́ сверши́вий Та́йную Свою́ Ве́черю; ми же, моля́ще Всецари́цю удосто́іти нас Боже́ственния Святи́ні, воспису́єм Єй сицева́я:","Ра́дуйся, пода́тельнице Небе́снаго Хлі́ба;","ра́дуйся, роди́тельнице Ві́чнаго Живота́.","Ра́дуйся, ча́ше, Христу́ приобща́ющая;","ра́дуйся, ду́шу і ті́ло с Бо́гом сочетава́ющая.","Ра́дуйся, лжи́ці злата́я, іспо́лнь Боже́ственних Та́їн;","ра́дуйся, драги́й киво́те, вмісти́лище вели́кия Святи́ні.","Ра́дуйся, пе́рсті, на святу́ю Євхари́стію указу́яй;","ра́дуйся, трапе́зо, предлага́ющая нам Пи́щу Святу́ю.","Ра́дуйся, досто́йних прича́стников одесну́ю поставля́ющая;","ра́дуйся, ревни́телей Боже́ственния Литургі́ї от а́да ізбавля́ющая.","Ра́дуйся, приводя́щая сме́ртних к Істо́чнику безсме́ртія;","ра́дуйся, огражда́ющая чад Свої́х ми́ром і крі́постію.","Ра́дуйся, Всецари́це, неду́ги на́ша благода́тію ісціля́ющая."]},{"h":"Кондак 8","ps":["Стра́нноє Рождество́ ви́дівше, жите́йськоє вся́коє отло́жше попече́ніє, горі́ імі́їм сердца́; на сіє́ бо Ви́шній яви́ся, во є́же привлещи́ Тому́ вопію́щия: Аллилу́я."]},{"h":"Ікос 8","ps":["Неотсту́пно в ні́дріх Оте́чеських пребива́я, Сло́во неопи́санноє на землі́ плоть бисть; Бог Ве́лій сотвори́ вели́чіє Ді́ві і призрі́ на смире́ніє Раби́ Своєя́, сли́шащия сицева́я:","Ра́дуйся, невмісти́маго Бо́га вмісти́вшая;","ра́дуйся, надми́рнаго Творця́ ми́ру яви́вшая.","Ра́дуйся, я́ко сокруши́ся сме́рті держа́ва;","ра́дуйся, я́ко ісціли́ся Ада́мова ра́на.","Ра́дуйся, пла́стирю, стру́пи душе́вния заживля́яй;","ра́дуйся, єле́є, я́зви тіле́сния умаща́яй.","Ра́дуйся, утоле́ніє болі́зней ражда́ющих;","ра́дуйся, облегче́ніє мук умира́ющих.","Ра́дуйся, нане́сшая пораже́ніє а́ду;","ра́дуйся, притупи́вшая сме́рти жа́ло.","Ра́дуйся, ча́яніє всео́бщаго воскресе́нія;","ра́дуйся, правосла́вних несумні́нноє спасе́ніє.","Ра́дуйся, Всецари́це, неду́ги на́ша благода́тію ісціля́ющая."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ а́нгельськоє і челові́чеськоє удиви́ся вели́чію непостижи́маго Твоєго́ воплоще́нія, Сло́ве; недоуміва́юще же о сей ве́лієй та́йні благоче́стія, со стра́хом і тре́петом благода́рственно зове́м Ті: Аллилу́я."]},{"h":"Ікос 9","ps":["Многоразли́чними неду́ги одержи́мії, о Всецари́ці, от святи́я іко́ни Твоєя́ па́че ча́янія ісціле́нія получа́ють, да приє́мше ві́рою благода́ть, велегла́сно взива́ють Ті:","Ра́дуйся, здра́вих чад при́сноє сохране́ніє;","ра́дуйся, боля́щих ко здра́вію преложе́ніє.","Ра́дуйся, діте́й неду́гующих ісціле́ніє;","ра́дуйся, ю́них страда́льцев Ма́ти.","Ра́дуйся, воста́ніє на одр болі́зні пове́рженних;","ра́дуйся, отра́до стра́хом сме́ртним одержи́мих.","Ра́дуйся, вне́млющая челові́ков рида́ніям;","ра́дуйся, призрева́ющая на на́ша стена́нія.","Ра́дуйся, бо́лей земни́х небе́сною ра́достію растворе́ніє;","ра́дуйся, лю́ті обурева́ємих пачеєсте́ственноє терпі́ніє.","Ра́дуйся, я́ко уготовля́єши пла́чущим ра́дость;","ра́дуйся, я́ко снабдева́єши кро́тких крило́ма моли́тви.","Ра́дуйся, Всецари́це, неду́ги на́ша благода́тію ісціля́ющая."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ Зижди́тель істлі́вшеє гріхо́м челові́чеськоє єстество́, сни́де на Тя, я́ко дождь на руно́, і купину́ Тя соді́лав неопали́мую, Бог сий бисть челові́к, да воспіва́єм Єму́: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ ді́вам, Отрокови́це чи́стая, і всім о чистоті́ радя́щим: в Тя бо всели́ся Бог, очища́яй разу́мная созда́нія Своя́, да ізби́вше вся́кия скве́рни, предлага́єм Ті сицева́я:","Ра́дуйся, молча́нія взиску́ющих собесі́днице;","ра́дуйся, ві́нче храня́щих ді́вство.","Ра́дуйся, нача́ло і коне́ць духо́внаго соверше́нія;","ра́дуйся, храни́лище Боже́ственнаго Открове́нія.","Ра́дуйся, Тро́їчеськаго Сові́та таї́ннице;","ра́дуйся, спасе́нія челові́ков вино́внице.","Ра́дуйся, верши́но, го́рдим умо́м непристу́пная;","ра́дуйся, убі́жище, смире́нним сердця́м досту́пноє.","Ра́дуйся, чи́стая, небесе́ чисті́йшая;","ра́дуйся, Херуви́мов і Серафи́мов честні́йшая.","Ра́дуйся, обра́дованная, я́ко прия́ла єси́ от Арха́нгела ра́дованіє;","ра́дуйся, уте́шенная, я́ко ру́ці Твої́ осяза́сте воскре́сшаго Христа́.","Ра́дуйся, Всецари́це, неду́ги на́ша благода́тію ісціля́ющая."]},{"h":"Кондак 11","ps":["Пі́ніє тща́щеся разу́мноє Спа́су приноси́ти, всегда́ неключи́ми, Влади́чице, остає́мся раби́ Твої́; кто бо мо́жеть досто́йно воспі́ти Бо́га, Єго́же і́м'я я́ко ми́ро ізлія́нноє? Сего́ ра́ди вопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Світ ве́лій возсія́во во тьмі сідя́щим, посіти́ нас Восто́к сви́ше, Син і Бог Твой, о Ді́во; Тя соді́лав свіще́ю на сві́щниці, світоно́сним ча́дом церко́вним наказу́єть приноси́ти Ті сицева́я:","Ра́дуйся, заре́ У́мнаго Со́лнця;","ра́дуйся, вмісти́лище Боже́ственнаго Огня́.","Ра́дуйся, сві́те, я́ко одія́ніє святи́х сотка́ла єси́;","ра́дуйся, свіще́, я́ко тьму бісо́вськую отгна́ла єси́.","Ра́дуйся, ко́сних умо́в Просвіще́ніє;","ра́дуйся, грі́шних серде́ць Озаре́ніє.","Ра́дуйся, десни́це, із мо́ря су́єтствій ізводя́щая;","ра́дуйся, луче́, путеводя́щая к Ца́рствію спаса́ющихся.","Ра́дуйся, мо́лніє, нераска́янних поража́ющая;","ра́дуйся, гро́ме, губи́телей устраша́ющий.","Ра́дуйся, омраче́нния со́вісти просвітле́ніє;","ра́дуйся, Бо́жия Суда́ умилостивле́ніє.","Ра́дуйся, Всецари́це, неду́ги на́ша благода́тію ісціля́ющая."]},{"h":"Кондак 12","ps":["Благода́ть да́ти восхоті́в, Зако́на Ве́тхаго Пода́тель Заві́т Но́вий нам дарова́; ми же, благода́ть приі́мше, не ді́ли зако́на, но єди́ною ві́рою спасе́ніє улучи́вше, воспису́єм всі: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твоє́ рождество́, Богома́ти, я́коже дре́вле Ізра́їль в кимва́ліх сіно́вную ски́нію воспіва́ше, та́ко ми ни́ні Тя, Ски́нію і́стинну, доброді́тельми прославля́єм, да сли́шиши от всіх сицева́я:","Ра́дуйся, песне, воспіва́ємая горі́;","ра́дуйся, псалмі́, слишимий ни́зу.","Ра́дуйся, Єди́ному Бо́гу досто́йно послужи́вшая;","ра́дуйся, Боже́ственній Тро́йце смире́нієм угоди́вшая.","Ра́дуйся, ві́ки Нося́щаго носи́вшая в Себі́;","ра́дуйся, престо́ле Содержа́щаго Вселе́нную в ру́ці.","Ра́дуйся, та́йно неізрече́нная віко́в і време́н;","ра́дуйся, упова́ніє тве́рдоє наро́дов і племе́н.","Ра́дуйся, серде́чноє ра́дованіє ієре́єв благогові́йних;","ра́дуйся, би́строє сли́шаніє моли́тв церко́вних і келейних.","Ра́дуйся, Прему́дрости до́ме богозда́нний;","ра́дуйся, Ми́лости сосу́де, Бо́гом ізбра́нний.","Ра́дуйся, Всецари́це, неду́ги на́ша благода́тію ісціля́ющая."]},{"h":"Кондак 13","ps":["О, Всецари́ці Ма́ти, ро́ждшая всіх святи́х Святі́йшеє Сло́во, ни́нішнєє на́ше приє́мши піснопі́ніє, от вся́кия сме́ртния болі́зні ісціли́ ни і бу́дущаго ізба́ви осужде́нія вопію́щих: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел предста́тель с Небесе́ сшед, рече́ Всецари́це: ра́дуйся! І боговіща́нним гла́сом воплоща́єма Тя зря, Го́споди, возопи́ к Ней такова́я:","Ра́дуйся, глави́зно на́шего спасе́нія;","ра́дуйся, ісполне́ніє Зижди́телева смотре́нія.","Ра́дуйся, я́ко Тобо́ю Бог воплоти́ся;","ра́дуйся, я́ко Неви́димий в Тебі́ ізобрази́ся.","Ра́дуйся, Ми́лость ми́ра внутр прия́вшая;","ра́дуйся, одія́ніє пло́ті Сло́ву істка́вшая.","Ра́дуйся, уму́ непости́жная го́рняя сла́во;","ра́дуйся, сердца́ оживи́вшая небе́сная ма́нно.","Ра́дуйся, звіздо́, благода́ті сія́ніє;","ра́дуйся, істо́чниче, живи́я води́ ізлія́ніє.","Ра́дуйся, Богоро́дице, в жена́х благослове́нная;","ра́дуйся, ро́ждшая Спа́са Ді́во нетлі́нная.","Ра́дуйся, Всецари́це, неду́ги на́ша благода́тію ісціля́ющая."]},{"h":"Кондак 1","ps":["Новоя́вленній Твоє́й іко́ні предстоя́ще ві́рнії уми́льно, воспіва́єм Ті, Всецари́це, раби́ Твої́; низпосли́ цільби́ к Тебі́ притека́ющим, да всі ра́достно зове́м Ті:","Ра́дуйся, Всецари́це, неду́ги на́ша благода́тію ісціля́ющая."]},{"h":"Молитва","ps":["О, Пречи́стая Богома́ти, Всецари́це! Усли́ши многоболі́зненноє воздиха́ніє на́ше пред чудотво́рною іко́ною Твоє́ю, із уде́ла Афо́нськаго в Россі́ю принесе́нною, при́зри на чад Твої́х, неісці́льними неду́ги стра́ждущих, ко свято́му о́бразу Твоєму́ с ві́рою припа́дающих! Я́коже пти́ця крило́ма покрива́єть птенці́ своя́, та́ко і Ти ни́ні, при́сно жи́ва су́щи, покри́й нас многоціле́бним Твої́м омофо́ром. Та́мо, іді́же наде́жда ісчеза́єть, несумні́нною Наде́ждою бу́ди. Та́мо, іді́же лю́тия ско́рби превозмога́ють, Терпі́нієм і Осла́бою яви́ся. Та́мо, іді́же мрак отча́янія в ду́ші всели́ся, да возсія́єть неізрече́нний світ Божества́! Малоду́шния уті́ши, немощни́я укріпи́, ожесточе́нним сердця́м ум'ягче́ніє і просвіще́ніє да́руй. Ісціли́ боля́щия лю́ди Твоя́, о всеми́лостивая Цари́це! Ум і ру́ки врачу́ющих нас благослови́; да послу́жать ору́дієм Всемо́щнаго Врача́ Христа́ Спа́са на́шего. Я́ко живі́й Ті су́щей с на́ми мо́лимся пред іко́ною Твоє́ю, о Влади́чице! Простри́ ру́ці Твої́, іспо́лненнеї ісціле́нія і врачби́, Ра́досте скорб'я́щих, в печа́ліх Утіше́ніє, да чудотво́рную по́мощ ско́ро получи́вше, прославля́єм Живонача́льную і Неразді́льную Тро́йцю, Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["О́бразом Твої́м радостотво́рним, / Влади́чице, Всецари́це Богоро́дице, / болі́зні і неду́ги на́ша ісціли́ / і от вся́ких бід і напа́стей огради́, // к заступле́нію Твоєму́ при́сно прибіга́ющих."]},{"h":"Інший тропар, глас 4","ps":["О́бразом радостотво́рним честни́я Всецари́ці, / жела́нієм те́плим взиска́ющих благода́ті Твоєя́ спаси́, Влади́чице, / ізба́ви от обстоя́ній к Тебі́ прибіга́ющих; / от вся́кия напа́сти огради́ ста́до Твоє́, // к заступле́нію Твоєму́ взива́ющеє при́сно."]},{"h":"Кондак, глас 8","ps":["Новоя́вленній іко́ні Богоро́диці Всецари́ці предстоя́ще / і на лик Тоя́ взира́юще, / со умиле́нієм і любо́вію глаго́лем: / низпосли́, Влади́чице, цільби́ к Тебі́ притека́ющим, / і пода́ждь утіше́ніє в ско́рбі су́щим, / да, восприє́мше ми́лость, благода́рні воззове́м Ті: // Ра́дуйся, Всецари́це, неду́ги на́ша благода́тію ісціля́ющая."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Ма́ти Христа́ Бо́га на́шего, і чтим о́браз Твой святи́й, от него́же істоча́єши ісціле́нія всім, с ві́рою к Тебі́ притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Скоропослушниця»","e":"Akathist to the Theotokos before her icon “Quick to Hear”","secs":[{"h":"Кондак 1","ps":["Ізбра́нной от всіх родо́в Бо́жієй Ма́тері і Цари́ці, скоропослу́шливо вне́млющей моли́твам смире́нним, і то́ки ціле́бния ізлива́ющей ві́рним от іко́ни Своєя́ святи́я, благода́рственноє прино́сим пі́ніє: Ти же, всеми́лостивая Засту́пнице, преклони́ся благоутро́бно ко гла́сом на́шим хвале́бним і от вся́ких бід свободи́ ни, зову́щия Ті:","Ра́дуйся, всеблага́я Скоропослу́шнице, проше́нія на́ша во бла́го ісполня́ющая."]},{"h":"Ікос 1","ps":["А́нгелов ли́ци благогові́йно Тебі́ слу́жать, і вся Небе́сния Си́ли немо́лчними гла́си Тя ублажа́ють, Богоро́дице Ді́во, я́ко ро́ждшую а́нгелов Царя́ Христа́ Бо́га, ми же грі́шнії, подража́ти їм дерза́юще і досто́йно благохвали́ти Тя недоумі́юще, смиренному́дренно вопіє́м Ті:","Ра́дуйся, непристу́пнаго Божества́ селе́ніє;","ра́дуйся, А́нгельськоє непрестаю́щеє удивле́ніє.","Ра́дуйся, Трапе́зо свята́я, хлі́бом жи́зні нас пита́ющая;","ра́дуйся, ма́слино благопло́дная, єле́єм ми́лости сердця́ на́ша умаща́ющая.","Ра́дуйся, даро́в Бо́жия благода́ті сокро́вищнице неістощи́мая;","ра́дуйся, чуде́с ріко́ приснотеку́щая.","Ра́дуйся, оби́димих Засту́пнице;","ра́дуйся, печа́льних Уті́шительнице.","Ра́дуйся, бі́дствующих Помо́щнице;","ра́дуйся, боля́щих Ціли́тельнице.","Ра́дуйся, разсла́бленних укрепи́тельнице;","ра́дуйся, пліне́нних свободи́тельнице.","Ра́дуйся, всеблага́я Скоропослу́шнице, проше́нія на́ша во бла́го ісполня́ющая."]},{"h":"Кондак 2","ps":["Ви́дяще милосе́рдіє Твоє́ неісче́тноє, Влади́чице, і мно́гая чудеса́, Тобо́ю явле́нная і при́сно явля́ємая чрез святи́я іко́ни Твоя́, ї́миже, я́ко зві́здами богосві́тлими, весь мир христия́нський украси́ла єси́, велича́єм Тя, возвели́чившую род наш Твої́м благоволе́нієм, і с любо́вію покланя́ємся пречи́стаго ли́ка Твоєго́ ізображе́нію, зову́ще Си́ну Твоєму́ Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум небе́сний открива́я, Богоро́дице, благоволи́ла єси́ в земно́м жре́бії Твоє́м, Святі́й Горі́ Афо́нстій, мно́гими чудеси́ просла́вити іко́ну Твою́, ю́же Сама́ Скоропослу́шницею найменова́ла єси́ гла́сом Боже́ственним от нея́ ізше́дшим, да всі ві́дуще таково́є Твоє́ о ней благоволе́ніє, пі́сненно Тебі́ вопію́ть:","Ра́дуйся, милосе́рдая всіх нас о Христі́ Ма́ти;","ра́дуйся, Ду́ха Свята́го жили́ще.","Ра́дуйся, любве́ Бо́жия к челові́ком проявле́ніє;","ра́дуйся, ро́да челові́чеськаго возвише́ніє.","Ра́дуйся, сві́тлая пала́то Бо́га Сло́ва;","ра́дуйся, свята́я святи́х бо́льшая.","Ра́дуйся, ро́ждшая Боже́ственнаго А́гнця;","ра́дуйся, возрасти́вшая нам клас живота́.","Ра́дуйся, бра́шна неги́блющаго ста́мно всезлата́я;","ра́дуйся, Пита́тальнице Пита́теля вселе́нния.","Ра́дуйся, я́ко предста́тельством Твої́м спасти́ся упова́єм;","ра́дуйся, я́ко моли́твами Твої́ми наслі́діє небе́сноє получи́ти ча́єм.","Ра́дуйся, всеблага́я Скоропослу́шнице, проше́нія на́ша во бла́го ісполня́ющая."]},{"h":"Кондак 3","ps":["Си́лою Бо́жиєю ді́йствующи, неблагогові́йно ходи́вшаго пред свято́ю Твоє́ю іко́ною Дохія́рськия оби́телі трапе́заря Ни́ла сліпото́ю і разслабле́нієм ті́ла наказа́ла єси́, Богоро́дице Ді́во, да про́чеє не дерза́єть оскорбля́ти Тя в пречи́стім Твоє́м о́бразе, єго́же в зало́г благоволе́нія Твоєго́ всей Афо́нстій го́ре дарова́ла єси́ ми́лостиво, да все насе́льници єя́ гла́си преподо́бними вопію́ть ро́ждшемуся от Тебе́ Бо́гу Сло́ву: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я любо́во ве́лію к лю́дем, іскупле́нним Кро́вію Си́на Твоєго́ і Бо́га, Влади́чице Всеблага́я, покая́ніє трапе́заря Ни́ла ми́лостиво прия́ла єси́ і ісціле́ніє єму́ от сліпоти́ і разслабле́нія дарова́ла єси́, да слу́жить непреста́нно Тебі́ і моли́тви немо́лчния прино́сить Ті пред многоціле́бною Твоє́ю іко́ною, взива́я си́це:","Ра́дуйся, Іоаки́ма і А́нни прозябе́ніє свято́є;","ра́дуйся, ро́ждшая Сокруши́вшаго главу́ дре́вняго змі́я.","Ра́дуйся, Преблагослове́нная в жена́х;","ра́дуйся, ро́ждшая нетлі́нно Спа́са душ на́ших.","Ра́дуйся, ді́вство і рождество́ чуде́сно сочета́вшая;","ра́дуйся, во обою́ непоро́чно Себі́ сохра́ньшая.","Ра́дуйся, всея́ вселе́нния ве́ліє чу́до;","ра́дуйся, всіх родо́в земни́х удивле́ніє.","Ра́дуйся, согріша́ющих ісправле́ніє;","ра́дуйся, ка́ющихся в доброді́телі утвержде́ніє.","Ра́дуйся, непам'ятозло́бная наказа́тельнице;","ра́дуйся, благосе́рдая вразуми́тельнице.","Ра́дуйся, всеблага́я Скоропослу́шнице, проше́нія на́ша во бла́го ісполня́ющая."]},{"h":"Кондак 4","ps":["Бу́ри жите́йськія ізбіжа́вшії і в ти́хоє приста́нище спасе́нія на Го́ру́ Афо́нськую прите́кшії, обріта́ють зді утіше́ніє благода́тноє і по́мощ Боже́ственную от святи́я іко́ни Твоєя́, Богоро́дице, от нея́же лучи́ чуде́с іспуща́єши, і то́ки ми́лости Твоєя́ ізлива́єши неоску́дно. Ті́мже всі хотя́щії в пусти́ніх Афо́на жа́ти спасе́ніє, велича́я Ма́тернія щедро́ти Твоя́, благода́рственно воспіва́ють Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав глас Боже́ственний от святи́я іко́ни Твоєя́, Влади́чице, трапеза́р Нил позна́ Тя Скоропослу́шницю би́ти всім, с ві́рою і любо́вію притека́ющим к чудотво́рному Твоєму́ о́бразу, і, прия́в от него́ вразумле́ніє своєму́ неве́жествію і прозрі́ніє свої́м слепо́тствующим очесе́м, возгласи́ Тебі́ благода́рственно от душі́:","Ра́дуйся, вре́менним наказа́нієм неві́жд умудря́ющая;","ра́дуйся, согріша́ющих покая́ніє ми́лостиво приє́млющая.","Ра́дуйся, на путь ісправле́нія заблужда́ющихся направля́ющая;","ра́дуйся, ра́ни гріхо́вния благоутро́бно врачу́ющая.","Ра́дуйся, в нераді́нії косне́ющих любвеоби́льно облича́ющая;","ра́дуйся, го́рестію тіле́сних страда́ній ві́чних мук ізбавля́ющая.","Ра́дуйся, волне́ніє страсте́й утиша́ющая;","ра́дуйся, руку́ по́мощі Твоєя́ погиба́ющим простира́ющая.","Ра́дуйся, безнаде́жних наде́ждо;","ра́дуйся, скорб'я́щих отра́до.","Ра́дуйся, наги́х одія́ніє;","ра́дуйся, си́рих призрі́ніє.","Ра́дуйся, всеблага́я Скоропослу́шнице, проше́нія на́ша во бла́го ісполня́ющая."]},{"h":"Кондак 5","ps":["Боговіща́нния глаго́ли Твоєя́ уві́дівше, і́ноці оби́телі Дохія́рськия Тебі́, Боже́ственній Скоропослу́шнице, храм сооруди́ша при трапе́зі, іді́же чудотво́рная іко́на Твоя́ пребива́єть, Пречи́стая Ді́во, і вся ві́рния утіша́єть зна́меньми Твоєя́ ми́лости, єя́же не лиши́ і нас смире́нних, по до́лгу Тебі́ воспіва́ющих, і вопію́щих чуде́с Творцю́ Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше то́ки чуде́с, от святи́я іко́ни Твоєя́ Скоропослу́шници істоча́ємия, всі і́ноці Гори́ Афо́нськия стека́хуся к ней на поклоне́ніє. Ти же, Ма́ти Бо́жия, всім, по коєго́ждо потре́бі, да́ри ми́лости Твоєя́ неоску́дно подава́ла єси́ от чудотво́рнаго Твоєго́ о́браза, подвиза́я благода́рно вопи́ти Тебі́:","Ра́дуйся, Ма́ти милосе́рдія і щедро́т;","ра́дуйся, одушевле́нний Престо́ле Вседержи́теля.","Ра́дуйся, Си́ну Бо́жию плоть заімода́вшая;","ра́дуйся, черто́же безсі́меннаго уневі́щенія.","Ра́дуйся, Безпло́тнаго воплоти́вшая;","ра́дуйся, Бо́га с челові́ки соєдини́вшая.","Ра́дуйся, преподо́бних всежела́тельноє зрі́ніє;","ра́дуйся, по́стников Боже́ственноє ра́дованіє.","Ра́дуйся, пустинножи́телей ти́хоє весе́ліє;","ра́дуйся, і́ноков крі́пкоє упова́ніє.","Ра́дуйся, де́монськия полки́ побіжда́ющая;","ра́дуйся, враги́ спасе́нія челові́чеськаго посрамля́ющая.","Ра́дуйся, всеблага́я Скоропослу́шнице, проше́нія на́ша во бла́го ісполня́ющая."]},{"h":"Кондак 6","ps":["Пропові́дуєть Гора́ Афо́нськая ми́лості і чудеса́ Твоя́, Преблагослове́нная Ма́ти Го́спода на́шего, і сві́тло красу́ється мно́гими чудотво́рними Твої́ми іко́нами, посреді́ ко́їх іко́на Твоя́, Скоропослу́шниця Тобо́ю нарече́нная, я́ко луна́ по́лная, луча́ми чуде́с немерца́ємо сія́єть, просвіща́я ду́ші на́ша сві́том Бо́жия благода́ті і подвиза́я нас хвале́бно взива́ти просла́вльшему Тя Трієди́ному Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ в пречи́стій іко́ні Твоє́й, Марі́є Богоро́дице, світ спасе́нія всім, блужда́ющим во тьмі гріхо́в і страсте́й, і сію́ нарекла́ єси́ Скоропослу́шницею, моля́щимся пред не́ю с ві́рою і благогові́нієм от душі́, ско́рую по́мощ Твою́ подаю́щи вопію́щим Ті такова́я:","Ра́дуйся, мо́лніє, ду́ші просвіща́ющая;","ра́дуйся, гро́ме, соблазня́ющия устраша́ющая.","Ра́дуйся, благооти́шноє прибі́жище утомле́нних треволне́нієм жите́йськаго мо́ря;","ра́дуйся, небу́рноє приста́нище обурева́ємих волна́ми страсте́й.","Ра́дуйся, ю́них наста́внице цілому́дрія;","ра́дуйся, покро́ве і огражде́ніє ді́вства.","Ра́дуйся, окамене́ніє серде́чноє ум'ягча́ющая;","ра́дуйся, хла́дность душе́вную благода́тно согріва́ющая.","Ра́дуйся, на стезю́ спасе́нія ві́рних наставля́ющая;","ра́дуйся, от путе́й поги́бельних претика́ющихся удаля́ющая.","Ра́дуйся, Спору́чнице на́ша к Си́ну Твоєму́ і Бо́гу;","ра́дуйся, при́сно умоля́ющая Єго́ о поми́лованії нас грі́шних.","Ра́дуйся, всеблага́я Скоропослу́шнице, проше́нія на́ша во бла́го ісполня́ющая."]},{"h":"Кондак 7","ps":["Хотя́щи всім показа́ти любо́в Твою́ ве́лію ко христия́нському ро́ду, Богоро́дице Преблага́я, в жре́бій Твой земни́й Го́ру Афо́нськую ізбра́ла єси́ і в ней селе́нія і́ночеськая умно́жила єси́, да всі обурева́ємії мирсько́ю суєто́ю, возмо́гуть обріта́ти зді ти́хоє і удо́бноє приста́нище ко спасе́нію, і Тобо́ю вспомоществу́ємі, сподо́б'яться наслі́дія Небе́снаго, і пі́ти со святи́ми Пресвяті́й Тро́йце: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє зна́меніє милосе́рдія Твоєго́ яви́ла єси́, Влади́чице, в чуде́снім прославле́нії святи́я іко́ни Твоєя́ Скоропослу́шници, не то́кмо і́ноком Гори́ Афо́нськия, но і всім правосла́вним христия́ном, в ни́хже благогові́йно честву́ється сея́ іко́ни Твоєя́ ізображе́ніє, да всі Тебі́ зову́ть:","Ра́дуйся, Бо́га на́шего Ма́ти;","ра́дуйся, в рождестві́ і по рождестві́ Ді́во.","Ра́дуйся, я́ко Тя блажа́ть всі ро́ди;","ра́дуйся, я́ко сотвори́ Тебі́ вели́чіє Си́льний.","Ра́дуйся, я́ко призрі́ на смире́ніє Твоє́ Госпо́дь;","ра́дуйся, я́ко возжелі́ добро́ти Твоєя́ Цар царе́й.","Ра́дуйся, Дщи благослове́нная Отця́ Небе́снаго;","ра́дуйся, Роди́тельнице неіскусому́жная Си́на Предві́чнаго.","Ра́дуйся, прия́телище непоро́чноє Ду́ха Свята́го;","ра́дуйся, Таї́ннице Боже́ственния благода́ті.","Ра́дуйся, го́рняго ми́ра украше́ніє;","ра́дуйся, до́льняго ми́ра заступле́ніє.","Ра́дуйся, всеблага́я Скоропослу́шнице, проше́нія на́ша во бла́го ісполня́ющая."]},{"h":"Кондак 8","ps":["Стра́нники і прише́льці єсьми́ на землі́ і, по глаго́лу апо́стола, не і́мами зді пребива́ющаго гра́да, но ко кому́ прибі́гнем, Влади́чице, в ско́рбіх стра́нствія на́шего, а́ще не к Тебі́, Всеблага́я? Не отве́ржи нас, Ма́ти Бо́жия, не рци нам: «Не вім вас, гріхо́в ра́ди ва́ших!», но поми́луй нас, си́рих і безпомо́щних, і прийми́ нас во ві́чния кро́ви, Покрови́тельнице на́ша, да ра́достно вопіє́м во сла́ві небе́сній Царю́ сла́ви Христу́: Аллилу́я."]},{"h":"Ікос 8","ps":["Всім ві́рним уті́шительно єсть взира́ти на святу́ю іко́ну Твою́, Влади́чице, на не́йже зрим Тя, на руку́ Твоє́ю держа́щую Предві́чнаго Младе́нця Го́спода на́шего Ісу́са Христа́, Єму́же покланя́ющеся боголі́пно, я́ко Творцю́ і Бо́гу на́шему, Тебі́, і́стинній Богоро́дице, умиле́нно глаго́лем:","Ра́дуйся, обра́дованная арха́нгельським благове́щенієм, Присноді́во;","ра́дуйся, Неві́сто Неневі́стная.","Ра́дуйся, Ма́ти Сві́та у́мнаго, всіх ду́ші просвіща́ющаго;","ра́дуйся, Престо́ле одушевле́нний Небесе́ і землі́ Творця́.","Ра́дуйся, кро́ткая голуби́це;","ра́дуйся, непоро́чная а́гнице.","Ра́дуйся, ча́ше, че́рплющая ра́дость;","ра́дуйся, неісчерпа́ємий сосу́де води́ живо́тния.","Ра́дуйся, мирополо́жнице благоуха́нія Христо́ва;","ра́дуйся, Є́юже злосмра́діє страсте́й на́ших отго́ниться.","Ра́дуйся, Є́юже позна́хом Си́на Бо́жия;","ра́дуйся, Є́юже научи́хомся покланя́тися Трієди́ному Бо́гу.","Ра́дуйся, всеблага́я Скоропослу́шнице, проше́нія на́ша во бла́го ісполня́ющая."]},{"h":"Кондак 9","ps":["Всі ро́ди блажа́ть Тя по до́лгу, благослове́нная Марі́є Богоро́дице, от восто́ка бо і до за́пада хва́льно і́м'я Твоє́, і́ноков же ли́ци Покрови́тельницю Тя свою́ імену́ють, найпа́че подвиза́ющієся в жре́бії Твоє́м Горі́ Афо́нстій, ю́же осо́бим благоволе́нієм Твої́м осени́ла єси́, мно́гая чудеса́ в ней содіва́ющи, і ми́лості Твоя́ бога́тия насе́льником єя́ явля́ющи, да благода́рно вопію́ть о Тебі́ Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї суєму́дреннії недоуміва́ють позна́ти та́йну Твоєго́ присноді́вства, Богоро́дице, ніже́ мо́гуть із'ясни́ти си́лу чудотво́рную, от іко́н Твої́х проістека́ющую, во ісціле́ніє неду́жних і на вся́ку по́льзу душе́вную і тіле́сную челові́ком. Ми же правосла́вно і несомні́нно Присноді́вою Тя іспові́дующе, ві́рно покланя́ємся іко́ні Твоє́й святі́й і вопіє́м Ті си́це:","Ра́дуйся, неві́рних сомни́тельноє сли́шаніє;","ра́дуйся, ві́рних ізві́стная похвало́.","Ра́дуйся, із боку́ чи́сту Христа́ нетлі́нно ро́ждшая;","ра́дуйся, ключи́ ді́вства невреди́вшая в Рождестві́ Твоє́м.","Ра́дуйся, Ма́ти і Ді́во преблагослове́нная;","ра́дуйся, Богоро́дице препросла́вленная.","Ра́дуйся, дів велича́ніє;","ра́дуйся, ма́терей при́сноє ра́дованіє.","Ра́дуйся, єди́на непоро́чная і до́брая в жена́х;","ра́дуйся, ро́ждшая обітова́ннаго Сокруши́теля глави́ змі́я.","Ра́дуйся, па́дших прароди́телей осужде́нія дре́вняго ізба́вльшая;","ра́дуйся, Єде́м, заключе́нний челові́ком, отве́рзшая Рождество́м Твої́м.","Ра́дуйся, всеблага́я Скоропослу́шнице, проше́нія на́ша во бла́го ісполня́ющая."]},{"h":"Кондак 10","ps":["Спасе́ніє устроя́ющи христоімени́тим лю́дем, благоволи́ла єси́, Богоро́дице, земни́й жре́бій Твой, Го́ру Афо́нськую, в населе́ніє і́ноком опреділи́ти, і рекла́ єси́ во виді́нії пе́рвому пустинножи́телю афо́нському, преподо́бному Петру́, би́ти Го́ре сей в жили́ще і́ноком при́сноє, обітова́нії благи́ми уте́шивши єго́, я́ко бу́деши Помо́щниця і Покрови́тельниця всім, подвиза́ющимся в ней богоуго́дно, да́рами потре́бними їх снабдіва́ющи і от вся́ких бід спаса́ющи, да невозбра́нно пою́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ заступле́нія, Ді́во, і́ноком правосла́вним і всім подви́жником ді́вства і чистоти́. Ті́мже жре́бій Твой земни́й, Го́ру Афо́нськую, невхо́дну жена́м сотвори́ла єси́, да без собла́зна гріхо́внаго пребива́ють в ней і́ноці, на Тебі́ єди́ну по Бо́зі наде́жду спасе́нія возлага́юще і Тебі́ зову́ще си́це:","Ра́дуйся, неув'яда́ємий цві́те ді́вства;","ра́дуйся, кри́не се́льний чистоти́.","Ра́дуйся, світоно́сная сі́не небе́сная, ревни́телей чистоти́ осіня́ющая;","ра́дуйся, прему́дрости Бо́жия сви́тче, рачи́телей цілому́дрія умудря́ющая.","Ра́дуйся, і́ноком благоподвиза́ющимся Хода́тайце спасе́нія;","ра́дуйся, пустинножи́телей Гори́ Афо́нськия Покро́ве і Огражде́ніє.","Ра́дуйся, ра́дость благода́тную ізлива́ющая в сердця́ боголюби́вия;","ра́дуйся, утіше́ніє духо́вноє подаю́щая душа́м огорче́нним.","Ра́дуйся, младопита́тельнице дів і безма́терніх сиро́т;","ра́дуйся, любо́вію Жениха́ безсме́ртнаго ді́вственная ликостоя́нія услажда́ющая.","Ра́дуйся, в тя́жкой борбі́ с прираже́ніями страсте́й плотськи́х крі́пкая помо́щнице;","ра́дуйся, оби́телей і́ночеських неуси́пная блюсти́тельниці.","Ра́дуйся, всеблага́я Скоропослу́шнице, проше́нія на́ша во бла́го ісполня́ющая."]},{"h":"Кондак 11","ps":["Пі́ніє на́ше смире́нноє, от полноти́ любве́ і усе́рдія Тебі́ приноси́моє, не пре́зри, Чи́стая, і не отврати́ся от нас, оскверне́нних мно́гими гріхми́, но помози́ нам, Всеблага́я, покая́нієм очи́ститися от скве́рни гріхо́вния і преуспі́ти в чи́стім і богоуго́днім житії́, Тя подвигополо́жницю і помо́щницю в сем іму́ще, да возмо́жем досто́йно і пра́ведно вопи́ти ко Го́споду: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́тлими луча́ми чуде́с свята́я іко́на Твоя́ немерца́ємо сія́єть, Богоро́дице Ді́во, і весь мир благода́тно озаря́єть, прогоня́ющи вся́коє вра́жиє ді́йство си́лою Бо́жиєю, от нея́ ісходя́щею; ті́мже ра́дуємся ми, грі́шнії, іму́ще такови́й зало́г Твоєго́ к нам благоволе́нія, і Тебі́, Скоропослу́шнице моле́ній на́ших, благода́рственно взива́єм:","Ра́дуйся, денни́це со́лнця незаходи́маго;","ра́дуйся, заре́ дне невече́рняго.","Ра́дуйся, у́тро спасе́нія нам возсія́вшая;","ра́дуйся, ро́ждшая Жениха́ безсме́ртнаго душ челові́чеських.","Ра́дуйся, жела́нія на́ша богоуго́дная ісполня́ющая;","ра́дуйся, в ско́рбіх і обстоя́ніїх на по́мощ к нам благоутро́бно ускоря́ющая.","Ра́дуйся, раю́ ми́сленний, вся́каго утіше́нія духо́внаго преіспо́лненний;","ра́дуйся, от ісполне́нія Твоєго́ і нам ка́плі утіше́нія істоча́ющая.","Ра́дуйся, зной страсте́й на́ших прохлажда́ющая;","ра́дуйся, благода́тноє безстра́стіє і́щущим єго́ усе́рдно подаю́щая.","Ра́дуйся, всіх в чистоті́ цілому́дрія живу́щих зіло́ лю́б'ящая;","ра́дуйся, в со́ніїх і виді́ніїх ізбра́нники Бо́жия посіща́ющая.","Ра́дуйся, всеблага́я Скоропослу́шнице, проше́нія на́ша во бла́го ісполня́ющая."]},{"h":"Кондак 12","ps":["Благода́ть Бо́жия, прису́щая святі́й іко́ні Твоє́й, Скоропослу́шниця Тобо́ю нарече́нній, Богома́ти Влади́чице, влече́ть к ней всіх скорб'я́щих і обремене́нних, і нетщи́ отхо́дять они́ от сего́ істо́чника Твої́х ми́лостей і щедро́т: в ско́рбіх отра́ду, в напа́стіх защи́ту, в болі́зніх цільбу́ неоску́дно получа́я от чудотво́рнаго о́браза Твоєго́, Всеблага́я, і благода́рственно вопію́ть благи́х пода́телю Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще чудеса́ Твоя́, Влади́чице, і ве́лію ми́лость Твою́ ко христия́нському ро́ду, ві́ми, я́ко недово́льни єсьми́ к досто́йному прославле́нію Тебі́, Честні́йшей Херуви́м і Сла́внейшей без сравне́нія Серафи́м, оба́че наді́ющеся на безприкла́дноє милосе́рдіє Твоє́, Всеблага́я, смиренному́дренно прино́сим Ті пі́сні такови́я:","Ра́дуйся, приста́нище небу́рноє подви́жников благоче́стія;","ра́дуйся, безмо́лвствующих сла́дкая собесі́днице.","Ра́дуйся, в пусти́ніх і гора́х скита́ющихся благода́тная отра́до;","ра́дуйся, та́йних среди́ ми́ра рабо́в Бо́жиїх та́йноє вразумле́ніє.","Ра́дуйся, грі́шников ка́ющихся с Бо́гом примире́ніє;","ра́дуйся, Гори́ Афо́нськия верхо́вная Прави́тельнице.","Ра́дуйся, Петра́ пустиннолюби́ваго посіще́нієм Твої́м зді озари́вшая;","ра́дуйся, Афана́сія богому́драго явле́нієм Твої́м облагода́тствовавшая.","Ра́дуйся, мно́гія преподо́бния Афо́нськия сла́вою небе́сною просла́вльшая;","ра́дуйся, насе́льником Гори́ сея́ осо́бую любо́в Твою́ явля́ющая.","Ра́дуйся, тіле́с на́ших безме́здная Ціли́тельнице;","ра́дуйся, душ на́ших к Ца́рствію Го́рнему Путеводи́тельнице.","Ра́дуйся, всеблага́я Скоропослу́шнице, проше́нія на́ша во бла́го ісполня́ющая."]},{"h":"Кондак 13","ps":["О Всепі́тая Ма́ти, Скоропослу́шницею наре́кшаяся во святі́й іко́ні Твоє́й, Богоро́дице Марі́є! Прийми́ ми́лостивно сіє́ ма́лоє моле́ніє на́ше, є́же от усе́рдія на́шего принесо́хом Ті с ві́рою і любо́вію, і умоли́ приснопокланя́ємую Тро́йцю ізба́вити ни геє́нни о́гненния, тьми несвіти́мия і муче́нія ві́чнаго: да предста́тельством Твої́м унасле́дим Ца́рствіє Небе́сноє, і сподо́бимся со святи́ми пі́ти Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов ли́ци благогові́йно Тебі́ слу́жать, і вся Небе́сния Си́ли немо́лчними гла́си Тя ублажа́ють, Богоро́дице Ді́во, я́ко ро́ждшую а́нгелов Царя́ Христа́ Бо́га, ми же грі́шнії, подража́ти їм дерза́юще і досто́йно благохвали́ти Тя недоумі́юще, смиренному́дренно вопіє́м Ті:","Ра́дуйся, непристу́пнаго Божества́ селе́ніє;","ра́дуйся, А́нгельськоє непрестаю́щеє удивле́ніє.","Ра́дуйся, Трапе́зо свята́я, хлі́бом жи́зні нас пита́ющая;","ра́дуйся, ма́слино благопло́дная, єле́єм ми́лости сердця́ на́ша умаща́ющая.","Ра́дуйся, даро́в Бо́жия благода́ті сокро́вищнице неістощи́мая;","ра́дуйся, чуде́с ріко́ приснотеку́щая.","Ра́дуйся, оби́димих Засту́пнице;","ра́дуйся, печа́льних Уті́шительнице.","Ра́дуйся, бі́дствующих Помо́щнице;","ра́дуйся, боля́щих Ціли́тельнице.","Ра́дуйся, разсла́бленних укрепи́тельнице;","ра́дуйся, пліне́нних свободи́тельнице.","Ра́дуйся, всеблага́я Скоропослу́шнице, проше́нія на́ша во бла́го ісполня́ющая."]},{"h":"Кондак 1","ps":["Ізбра́нной от всіх родо́в Бо́жієй Ма́тері і Цари́ці, скоропослу́шливо вне́млющей моли́твам смире́нним, і то́ки ціле́бния ізлива́ющей ві́рним от іко́ни Своєя́ святи́я, благода́рственноє прино́сим пі́ніє: Ти же, всеми́лостивая Засту́пнице, преклони́ся благоутро́бно ко гла́сом на́шим хвале́бним і от вся́ких бід свободи́ ни, зову́щия Ті:","Ра́дуйся, всеблага́я Скоропослу́шнице, проше́нія на́ша во бла́го ісполня́ющая."]},{"h":"Молитва","ps":["Преблагослове́нная Влади́чице, Присноді́во Богоро́дице, Бо́га Сло́ва па́че вся́каго сло́ва на спасе́ніє на́ше ро́ждшая, і благода́ть Єго́ преізоби́льно па́че всіх прия́вшая, мо́ре я́вльшаяся Боже́ственних дарова́ній і чуде́с приснотеку́щая ріка́, ізлива́ющая благода́ть всім, с ві́рою к Тебі́ прибега́ющим! Чудотво́рному Твоєму́ о́бразу припа́дающе, мо́лимся Тебі́, всеще́дрій Ма́тері человіколюби́ваго Влади́ки: удиви́ на нас пребога́тия ми́лості Твоя́, і проше́нія на́ша, приноси́мая Тебі́, Скоропослу́шнице, ускори́ іспо́лнити все, є́же на по́льзу во утіше́ніє і спасе́ніє, коєму́ждо устроя́ющи. Посіти́, Преблага́я, раби́ Твоя́ благода́тію Твоє́ю, пода́ждь неду́гующим цільбу́ і соверше́нноє здра́віє, обурева́ємим тишину́, пліне́нним свобо́ду і разли́чними о́брази стра́ждущих уті́ши; ізба́ви Всеми́лостивая Госпоже́, всяк град і страну́ от гла́да, я́зви, тру́са, пото́па, огня́, меча́ і іни́я ка́зні вре́менния і ві́чния, Ма́терним Твої́м дерзнове́нієм отвраща́ющи гнів Бо́жий; і душе́внаго разслабле́нія, обурева́нія страсте́й і гріхопаде́ній свободи́ раби́ Твоя́, я́ко да непреткнове́нно, во вся́ком благоче́стії пожи́вше в сем ві́ці, і в бу́дущем ві́чних благ сподо́бимся благода́тію і человіколю́бієм Си́на Твоєго́ і Бо́га, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м і Пресвяти́м Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["К Богоро́диці притеце́м, су́щії в біда́х, / і святі́й іко́ні Єя́ ни́ні припаде́м, / с ві́рою зову́ще із глубини́ душі́: / ско́ро на́ше усли́ши моле́ніє, Ді́во, / я́ко Скоропослу́шниця наре́кшаяся, / Тебі́ бо раби́ Твої́ в ну́ждах // гото́вую Помо́щницю і́мами."]},{"h":"Кондак, глас 8","ps":["В мо́рі жите́йстім обурева́ємії, / треволне́нію подпа́даєм страсте́й і іскуше́ній. / Пода́ждь у́бо нам, Госпоже́, ру́ку по́мощі, я́коже Петро́ві Син Твой, / і ускори́ от бід ізба́вити ни, да зове́м Ті: // ра́дуйся, всеблага́я Скоропослу́шнице."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтем о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Достойно є» (Милуюча)","e":"Akathist to the Theotokos before her icon “It Is Truly Meet” (The Merciful)","secs":[{"h":"Кондак 1","ps":["Ізбра́нній Бо́гом от челові́чеськаго ро́да послужи́ти воплоще́нію предві́чнаго Сло́ва, преблагослове́нній Ді́ві Богоро́диці, досто́йно воспеваємой от А́нгел на Небесі́, ми грі́шнії на землі́ дерза́єм приноси́ти хвале́бноє пі́ніє; є́же ми́лостиво от нас приє́мши, всемилующая Цари́це Богоро́дице, от вся́ких бід нас спаси́ і ві́чних мук свободи́, да зове́м Ті:","Ра́дуйся, христия́ном Помо́щнице і милосе́рдая о грі́шних Предста́тельнице."]},{"h":"Ікос 1","ps":["Арха́нгел Гавриї́л с небесе́ по́слан бисть от Тебе́, Богоро́дице, к смире́нному послу́шнику гори́ Афо́нськия, в пусти́нній келії воспевавшему Ті хвале́бния пі́сні пред свято́ю Твоє́ю іко́ною, да научи́ть єго́ пі́ти піснь небе́сную, є́юже славосло́в'ять Тя А́нгели в Сіо́ні го́рнем. Ті́мже і ми до́льнії, воспомина́я таково́є Твоє́ о лю́діх благопромишле́ніє, со благодаре́нієм вопіє́м Ті си́це:","Ра́дуйся, досто́йно восхваля́ємая от Арха́нгел і А́нгел;","ра́дуйся, ублажа́ємая от всіх небе́сних сил.","Ра́дуйся, Присноблаже́нная і Пренепоро́чная;","ра́дуйся, Ма́ти Бо́га на́шего.","Ра́дуйся, честні́йшая Херуви́м;","ра́дуйся, сла́внійшая без сравне́нія Серафи́м.","Ра́дуйся, без істлі́нія Бо́га Сло́ва ро́ждшая;","ра́дуйся, воі́стину су́щая Богоро́дице.","Ра́дуйся, величаємая на небесі́ і на землі́;","ра́дуйся, воспіва́ємая го́рними і до́льними.","Ра́дуйся, єди́на благослове́нная в жена́х;","ра́дуйся, ізрасти́вшая нам плод живота́.","Ра́дуйся, христия́ном Помо́щнице і милосе́рдая о грі́шних Предста́тельнице."]},{"h":"Кондак 2","ps":["Ви́дів послу́шник пусти́нний ди́внаго прише́льця, в келію єго́ прише́дшаго і піснь пресладкую Тебе́, Влади́чице, воспі́вшаго, не уразумі́ в нем А́нгела би́ти, но зіло́ услади́ся пі́нієм єго́ небе́сним і проси́, да напи́шеть єму́ словеса́ поє́мия пі́сні; єгда́ же узрі́, я́ко под пе́рстом єго́ ка́менная дська ум'ягчи́ся, і пи́шемая словеса́ на ней углуби́шася, я́ко на песці́, позна́ в сем чуде́сноє ді́йство і возопи́ к ро́ждшемуся от Тебе́ Бо́гу Сло́ву: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зумом богоозаренним но́вую піснь открива́я, рече́ Арха́нгел послу́шнику, я́ко та́ко воспіва́ють Тя, Богоро́дице, А́нгелов ли́ци в оби́теліх го́рних, і повелі́ єму́, да возвісти́ть челові́ком словеса́ пі́сні небе́сния і научи́ть їх ангелоподо́бно пі́ти Тебі́:","Ра́дуйся, благода́тная Марі́є;","ра́дуйся, я́ко Госпо́дь с Тобо́ю.","Ра́дуйся, благослове́нная в жена́х;","ра́дуйся, неіскусобра́чная роди́тельнице Бо́га Сло́ва.","Ра́дуйся, непоро́чноє селе́ніє Ду́ха Свята́го;","ра́дуйся, зача́тіє несказа́нноє яви́вшая.","Ра́дуйся, рождество́ нетлі́нноє показа́вшая;","ра́дуйся, Матерю і Ді́вою преби́вшая.","Ра́дуйся, во обою́ непоро́чно і свя́то себе́ сохра́ньшая;","ра́дуйся, А́нгелов чистото́ю Твоє́ю превозше́дшая.","Ра́дуйся, го́рніх умо́в непрестаю́щеє удивле́ніє;","ра́дуйся, челові́чеськаго ро́да возвише́ніє.","Ра́дуйся, христия́ном Помо́щнице і милосе́рдая о грі́шних Предста́тельнице."]},{"h":"Кондак 3","ps":["Си́лою Бо́жиєю Гавриї́л Арха́нгел тве́рдий ка́мень в м'я́гкий воск претвори́ і на нем пе́рстом свої́м написа́ словеса́ пі́сні хвале́бния Тебі́, Богоро́дице, да всі позна́ють вели́коє чу́до і несомні́нно уві́рують, я́ко та́ко воі́стину воспіва́ють Тя го́ре си́ли небе́сния, і́мже подража́юще, і ми поє́м вели́чія Твоя́, Ді́во, і в ра́дості духо́вній вопіє́м просла́вльшему Тя Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я простоту́ душе́вную і непоро́чноє се́рдце, послу́шник смире́нний сподо́бися а́нгельськия бесі́ди і лицезрі́нія чинонача́льника го́рніх сил, ми же, лука́вством і зло́бою потемненнії, со тре́петом взира́юще на святу́ю іко́ну Твою́, Влади́чице, мо́лим Ті ся прилі́жно, обрати́ ни от злоб на́ших і научи́ нас во смире́нії і кро́тости ду́ха глаго́лати Тебі́:","Ра́дуйся, Го́ру Афо́нськую освяти́вшая Твої́м благода́тним прису́тствієм;","ра́дуйся, хо́лми і де́бри єя́ іспо́лнившая сла́вою Твої́х чуде́с.","Ра́дуйся, а́нгельськаго явле́нія сподо́бльшая пустинножительство Афонськоє;","ра́дуйся, оби́телі і́ночеськия в нем умно́жившая во спасе́ніє душ челові́чеських.","Ра́дуйся, і всім, в пості́ і моли́тві пребива́ющим, обіща́вшая Твоє́ заступле́ніє;","ра́дуйся, от треволне́нія мо́ря жите́йськаго спаса́ющая ка́ющихся.","Ра́дуйся, благода́ть Си́на Твоєго́ і Бо́га низводящая на мі́ста, Тебі́ посвящаємия;","ра́дуйся, рай ми́сленний показа́вшая хра́ми Бо́жия.","Ра́дуйся, приста́нище небу́рноє содевающая в о́ніх іщущим спасе́нія;","ра́дуйся, всім потре́бним ко благоче́стію нас снабдіва́ющая.","Ра́дуйся, жительствующим богоуго́дно Пода́тельнице благ вре́менних і ві́чних;","ра́дуйся, Хода́тайце нам Ца́рствія Небе́снаго.","Ра́дуйся, христия́ном Помо́щнице і милосе́рдая о грі́шних Предста́тельнице."]},{"h":"Кондак 4","ps":["Бу́ря недоумі́нія смути́ ста́рця і́нока, єгда́ усли́ша піснь но́ву і чу́дну із уст своєго́ ученика́ і узрі́ дську ка́менну, я́ко воск, начерта́ніє приі́мшу; єгда́ же уві́да о посіще́нії ди́внаго посіти́теля, Гавриї́лом наре́кшагося, уразумі́, я́ко той єсть, і́же дре́вле благовісти́ Тебі́, Ді́во, безсі́менноє зача́тіє Бо́га Сло́ва. Ті́мже велича́я вели́чія Твоя́, Цари́це го́рних і до́льних, воспіва́ше ра́достно А́нгелов і челові́ков Творцю́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше о посіще́нії Арха́нгелові і́ноці гори́ Афо́нськия, стека́хуся ви́діти дську, на не́йже преєсте́ственно начертана би́ша пи́сьмена пі́сні небе́сния, і воспіва́ху Тя благогові́йно пред свято́ю іко́ною Твоє́ю, Влади́чице, пред не́юже воспі́ Тя Арха́нгел. Прийми́ у́бо і на́ша приноси́мия Тебі́ моли́тви с пі́нієм такови́м:","Ра́дуйся, я́ко о Тебі́ ра́дується а́нгельський собо́р;","ра́дуйся, я́ко о Тебі́ торжеству́єть челові́чеський род.","Ра́дуйся, на ру́ку Твоє́ю носи́вшая Носящего вся́чеськая;","ра́дуйся, вмісти́вшая во чре́ві Твоє́м Невмісти́маго всім ми́ром.","Ра́дуйся, Созда́телю Твоєму́ плоть заімодавшая;","ра́дуйся, Красні́йшаго па́че всіх сино́в челові́чеських ро́ждшая.","Ра́дуйся, млеко́м пита́вшая Пита́ющаго вся́чеськая;","ра́дуйся, попече́ніє імі́вшая о Си́ні Твоє́м, Су́щем Промислителе всея́ тва́рі.","Ра́дуйся, похвало́ ді́вства;","ра́дуйся, ма́терей сла́во.","Ра́дуйся, в рождестві́ ді́вство сохра́ньшая;","ра́дуйся, рождество́ с ді́вством сочета́вшая.","Ра́дуйся, христия́ном Помо́щнице і милосе́рдая о грі́шних Предста́тельнице."]},{"h":"Кондак 5","ps":["Богови́дець Мойсе́й іногда́ на ка́менних скрижа́ліх зако́н Бо́жий, начерта́нний пе́рстом Бо́жиїм, получи́, і́ноці же гори́ Афо́нськия піснь небе́сную во сла́ву Богома́тере, на дські ка́менній начертанную, от Арха́нгела прия́ша і, сим наученнії а́нгельськоє славосло́віє Тебі́ приноси́ти, воспі́ша та́ко благоволи́вшему о них Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше нача́льниці Гори́ Афо́нськия чу́до ве́ліє в явле́нії Арха́нгелові і пі́сні но́вій, до́ску с начертанними от А́нгела письмени́ препроводи́ша к царю́ і патріа́рху Цареграда, во увіре́ніє і́стини пресла́внаго сего́ чудесе́; ті́ї же ра́достно прия́ша ю, я́ко зало́г благоволе́нія Бо́жия, во всей Це́ркві Правосла́вній узако́ниша воспіва́ти піснь а́нгельськую в похвалу́ Тебі́, Богоро́дице, і взива́ху Ті во умиле́нії си́це:","Ра́дуйся, преукраше́нная лі́потами всіх доброді́телей, Ді́во;","ра́дуйся, Неві́сто неневі́стная.","Ра́дуйся, возрасти́вшая цвіт неув'яда́ємий, Христа́;","ра́дуйся, раю́ слове́сний, Дре́во жи́зні нам прозя́бшая.","Ра́дуйся, сі́не небе́сная, от зно́я страсте́й нас сохраня́ющая;","ра́дуйся, покро́ве ми́ру, ши́рший о́блака.","Ра́дуйся, дре́во благосінноли́ственноє, прохладу спаси́тельную ві́рним подаю́щеє;","ра́дуйся, істо́чниче Води́ живи́я, от нея́же пія́й ктому́ не умира́єть.","Ра́дуйся, Судії́ пра́веднаго умоле́ніє;","ра́дуйся, гріхо́в на́ших проще́ніє.","Ра́дуйся, во сла́ві небе́сній одесну́ю Бо́га пребива́ющая;","ра́дуйся, земноро́дних милосе́рдієм Твої́м не оставля́ющая.","Ра́дуйся, христия́ном Помо́щнице і милосе́рдая о грі́шних Предста́тельнице."]},{"h":"Кондак 6","ps":["Пропові́дуєть Свята́я Це́рков вели́чіє чуде́с Твої́х, Марі́є Богоро́дице, і сві́тло красу́ється, воспіва́я Ті піснь а́нгельськую, от небе́с на зе́млю принесе́нную чинонача́льником го́рніх сил Гавриї́лом; с ни́мже помоли́ся, Госпоже́ Пречи́стая, к Си́ну Твоєму́ і Бо́гу, да нези́блему во благоче́стії сохрани́ть Це́рков Свою́ і посрами́ть вся воста́нія єрети́чеськая і раскольничеськая, нас же, чад Єя́, сподо́бит неосужде́нно воспіва́ти Єму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ла єси́ мно́гими луча́ми чуде́с, о ми́лостивая Богома́ти, чрез святу́ю іко́ну Твою́, Влади́чице, і си́ми не то́чію Го́ру Афо́нськую, но і мно́жайшая мі́ста озари́ла єси́, да научі́мся зва́ти Тебі́:","Ра́дуйся, ра́досте на́ша, услажда́ющая ско́рбния се́рдця, к Тебі́ отверстия;","ра́дуйся, блага́я Засту́пнице, на по́мощ к нам ускоря́ющая.","Ра́дуйся, зало́г спаси́тельний нам в іко́ні Твоє́й дарова́вшая;","ра́дуйся, Афо́нськую Го́ру і мно́гія страни́ є́ю просла́вльшая.","Ра́дуйся, Наде́ждо на́ша ізві́стная;","ра́дуйся, упова́ніє на́ше непости́дноє.","Ра́дуйся, скорбе́й на́ших разріше́ніє;","ра́дуйся, печа́лей на́ших утоле́ніє.","Ра́дуйся, ві́ри правосла́вния утвержде́ніє;","ра́дуйся, неві́рія і злові́рія посрамле́ніє.","Ра́дуйся, любве́ Боже́ственния явле́ніє;","ра́дуйся, чуде́с пресла́вних соверше́ніє.","Ра́дуйся, христия́ном Помо́щнице і милосе́рдая о грі́шних Предста́тельнице."]},{"h":"Кондак 7","ps":["Хотя́щим жа́ти спасе́ніє ми́лостивая Покрови́тельниця і Помо́щниця явля́єшися, Ма́ти Бо́жия, і при́сно хода́тайствуєши за них к Си́ну Твоєму́ і Бо́гу, а́ще бо кто і па́даєть в ні́коє согріше́ніє, не́мощію пло́ті обложе́н, оба́че Тобо́ю возста́ніє получа́єть во спасе́ніє, я́ко всім хо́щеши спасти́ся і в ра́зум і́стини прийти́ воспіва́ющим Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́во не́бо і но́ва земля́ уготовани от Си́на Твоєго́ і Бо́га лю́б'ящим Єго́, Госпоже́ Всеблага́я, к ни́мже стяжа́хом Тя Путеводительницю ізря́дну. Ті́мже мо́лим Тя, не попусти́ нас поги́бнути в де́бріх гріхо́вних, но приведи́ нас стезе́ю пра́вою в страну́ сві́та і ра́дости ві́чния, да Тебі́ вопіє́м хвале́бно:","Ра́дуйся, Сіо́на го́рняго пе́рвійшеє украше́ніє;","ра́дуйся, оби́телей до́льних присноготовоє заступле́ніє.","Ра́дуйся, земле́ блага́я, Клас спаси́тельний ми́ру ізрасти́вшая;","ра́дуйся, ни́во неора́нная, оплодотворенная Ду́хом Святи́м.","Ра́дуйся, Огнь Божества́ во чре́во Твоє́ приє́мшая;","ра́дуйся, глад па́дшаго челові́чества Хлі́бом жи́зні утоли́вшая.","Ра́дуйся, Престо́ле Царя́ Сла́ви;","ра́дуйся, пала́то преукраше́нная Вседержи́теля.","Ра́дуйся, хра́мі одушевле́нний Триіпоста́снаго Бо́га;","ра́дуйся, две́ре Госпо́дня, є́юже Син Бо́жий про́йде к нам.","Ра́дуйся, христия́ном Помо́щнице і милосе́рдая о грі́шних Предста́тельнице."]},{"h":"Кондак 8","ps":["Стра́нноє явле́ніє Арха́нгела, на горі́ Афо́нстій іногда́ би́вшеє, смотре́ніє бисть Боже́ственноє, і́мже просла́вися всепі́тоє і́м'я Твоє́, Марі́є Богоро́дице, і всі ві́рнії научи́шася ангелоподо́бно воспіва́ти Тя, Херуви́мов честні́йшую і Серафи́мов сла́внійшую Ма́тер Бо́га на́шего, о Не́йже ра́дується вся́кая твар і род челові́чеський благода́рно взива́єть ко Го́споду: Аллилу́я."]},{"h":"Ікос 8","ps":["Все упова́ніє на́ше на Тя возлага́єм, Ма́ти Бо́жия, і в ско́рбіх на́ших к святі́й іко́ні Твоє́й усе́рдно притека́єм, ча́юще от нея́ утіше́ніє благода́тноє получи́ти. Помози́ у́бо нам, Влади́чице, с терпі́нієм і благодаре́нієм вся́кия ско́рби переносити і вмі́сто ро́пота малоду́шнаго благоумиле́нно взива́ти Тебі́:","Ра́дуйся, всіх скорб'я́щих Ра́досте;","ра́дуйся, всіх печа́льних Утіше́ніє.","Ра́дуйся, тружда́ющихся і обремене́нних сла́дкий поко́є;","ра́дуйся, болі́знующих і огорченних живительная отра́до.","Ра́дуйся, в час ско́рбних недоумі́ній мисль благу́ю на се́рдці полага́ющая;","ра́дуйся, во дні уни́нія наде́ждою ві́чних благ воодушевляющая.","Ра́дуйся, іскуша́ємим ру́ку по́мощі простирающая;","ра́дуйся, гнів Бо́жий от глав на́ших отводя́щая.","Ра́дуйся, ми́рноє устроє́ніє обурева́ємим напа́стьми подаю́щая;","ра́дуйся, во благи́х жела́нія на́ша ди́вно ісполня́ющая.","Ра́дуйся, терпіли́вих страда́льцев дара́ми благода́тними увенчавающая;","ра́дуйся, всіх благоподвизающихся блаже́нства ра́йськаго сподобля́ющая.","Ра́дуйся, христия́ном Помо́щнице і милосе́рдая о грі́шних Предста́тельнице."]},{"h":"Кондак 9","ps":["Всі А́нгели небе́снії немо́лчними похвала́ми Тя ублажа́ють, Цари́це і Влади́чице всея́ тва́рі, ми же земні́ї і пе́рстнії ку́ю похвалу́ досто́йную принесе́м Ті, Всепі́тая? Оба́че, наді́ющеся на милосе́рдіє Твоє́ неісче́тноє, любо́вію к Тебі́ понужда́єми, поє́м чудеса́ Твоя́, пропові́дуєм благодія́нія Твоя́, славосло́вим і́м'я Твоє́ і, усе́рдно припа́дая ко святі́й іко́ні Твоє́й, ра́бськи вопіє́м ізображе́нному на ней вку́пі с Тобо́ю Богомладенцю Христу́: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́й риторстії глаго́ли не дово́льни к пі́нію чуде́с Твої́х, Богоро́дице, оба́че блага́я су́щи, ві́ру на́шу вмі́сто ри́торськаго благословесія ми́лостиво прийми́, ві́си бо і любо́в на́шу, є́юже се́рдця на́ша к Тебі́ іспо́лнени. Ті́мже благоутро́бно усли́ши нехитростния на́ша пі́сні, і́миже дерза́єм благохвали́ти Тя си́це:","Ра́дуйся, сопресто́льноє Отцю́ Сло́во в ложесна́х Твої́х вмісти́вшая;","ра́дуйся, Світ незаходи́мий ро́ждшая.","Ра́дуйся, жизнь ві́чную ми́ру дарова́вшая рождество́м Твої́м;","ра́дуйся, Преві́чнаго, я́ко Младе́нця, на ру́ку Твоє́ю носи́вшая.","Ра́дуйся, гра́де одушевле́нний Всецаря́;","ра́дуйся, ски́ніє освяще́нная жива́го Бо́га.","Ра́дуйся, ни́жняя сочета́вшая с ви́шніми;","ра́дуйся, миротворице, Боже́ственнаго ми́ра преісполненная.","Ра́дуйся, до́брих вино́вная;","ра́дуйся, злих преміне́ніє.","Ра́дуйся, ору́жіє на враги́ всекрепкоє;","ра́дуйся, щиті́ ві́рних несокруши́мий.","Ра́дуйся, христия́ном Помо́щнице і милосе́рдая о грі́шних Предста́тельнице."]},{"h":"Кондак 10","ps":["Спаси́тельноє прибі́жище от сує́ть ми́ра преле́стнаго яви́ся жре́бій Твой земни́й, свята́я воі́стину Гора́ Афо́нськая, Богоро́дице Ді́во, ознаменованная мно́гими Твої́ми чудеси́. Но і на вся́ком мі́сті с любо́вію призива́ющих Тя усли́ши і заступи́, Си́на же Твоєго́ умоля́ти не преста́й, Всеблага́я, да не отступна пребива́єть благода́ть Єго́ от міст, іді́же в собра́нії ві́рних поє́ться Єму́ хвале́бная піснь: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ ді́вственником, Преблагослове́нная Ді́во, і столп крі́пок от лиця́ вра́жия всім подви́жником благоче́стія: Тебі́ бо даде́ся ве́лія си́ла те́мния а́дськия си́ли побіжда́ти і от іскуше́ній їх душепа́губних челові́ки ізбавля́ти, найпа́че же тіх, і́же цілому́дренно і свя́то на землі́ пребива́ють. Сего́ ра́ди ді́вства і цілому́дрія рачи́тели согла́сно Тебі́ зову́ть:","Ра́дуйся, чистото́ю сія́ющая па́че со́лнця;","ра́дуйся, ді́вства нача́ло і освяще́ніє.","Ра́дуйся, кри́не, облагоуха́вший па́дшеє челові́чество;","ра́дуйся, во смире́нії Твоє́м осіне́нная благоволе́нієм Всеви́шняго.","Ра́дуйся, ві́рная рабо́ Госпо́дня;","ра́дуйся, я́ко Тя блажа́ть всі роди́.","Ра́дуйся, я́ко сотвори́ Ті вели́чіє Си́льний;","ра́дуйся, я́ко соцарствуєши с Сино́м Твої́м во сла́ві ві́чній.","Ра́дуйся, хода́тайце Бо́жия к лю́дем благоволе́нія;","ра́дуйся, грі́шних к Бо́гу дерзнове́ніє окриляющая.","Ра́дуйся, неістощи́мий істо́чниче ми́лостей і щедро́т;","ра́дуйся, преісполненная сострада́нія к стра́ждущим.","Ра́дуйся, христия́ном Помо́щнице і милосе́рдая о грі́шних Предста́тельнице."]},{"h":"Кондак 11","ps":["Пі́ніє на́ше, а́ще би́ло би і тьмочисленноє, не довлі́ло би к досто́йному прославле́нію ми́лостей Твої́х, Преблагослове́нная Ма́ти Бо́жия, я́же непреста́нно ізлива́єши ро́ду на́шему; оба́че да не неблагода́рни яви́мся пред Тобо́ю, по си́лі на́шей похва́льная воспису́єм Ті с ві́рою і любо́вію і, воспомина́я неісче́тная чудотворе́нія Твоя́, вопіє́м верхо́вному Творцю́ чуде́с Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світопода́тельними луча́ми чуде́с іко́на Твоя́, о Всеми́лостивая Влади́чице, на Святі́й Горі́ Афо́нстій і повсю́ду немерцаємо сія́єть і весь мир правосла́вний благода́тно просвіща́єть. Сего́ ра́ди гряду́ть к ней от літ дре́вніх на поклоне́ніє правосла́вних собо́ри, умиле́нно воспіва́я пред не́ю благохвале́нія Ті такова́я:","Ра́дуйся, Царя́ Христа́ ми́ру яви́вшая;","ра́дуйся, на іко́ні Твоє́й вку́пі с Ним ізображе́нная.","Ра́дуйся, клеще́ та́їнственная, Ісаїєю провиденная;","ра́дуйся, купино́ неопали́мая, богови́дцем Мойсе́єм предзри́мая.","Ра́дуйся, руно́ ороше́нноє Гедео́на;","ра́дуйся, чаще приосіне́нная, Авваку́мом воспетая.","Ра́дуйся, две́ре затворе́нная, Ієзекі́їлю показа́нная;","ра́дуйся, горо́ несіко́мая, Данії́лу явле́нная.","Ра́дуйся, многообра́зні от проро́к предвозвіще́нная;","ра́дуйся, проро́чеських рече́ній сбитіє́ яви́вшая.","Ра́дуйся, христия́ном Помо́щнице і милосе́рдая о грі́шних Предста́тельнице."]},{"h":"Кондак 12","ps":["Благода́ті прича́стная Твоя́ іко́на, Богоро́дице Ді́во, я́ко сокро́вище драгоці́нноє, Це́ркві Христо́вой от Тебе́ подаде́ся, в ней бо обіща́лася єси́ с на́ми би́ти до сконча́нія ві́ка, ре́кши о первонапи́санній Твоє́й іко́ні: «С не́ю благода́ть Моя́ і си́ла!» Ві́руєм, Всепі́тая, я́ко не оскуді́єть глаго́л Твой сей, і я́ко во іко́ні Твоє́й святі́й на вся́цім мі́сті і зді с на́ми пребива́єши, іді́же ві́рно поє́ться Си́ну Твоєму́ і Бо́гу хвале́бная піснь: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще чудеса́ Твоя́, Богоро́дице, припа́даєм усе́рдно ко святі́й іко́ні Твоє́й, лобиза́єм ю с серде́чною любо́вію і, я́ко при́сно су́щей с на́ми, мо́лим Ті ся: воззри́ на ни милосе́рдієм Твої́м, Ма́ти Бо́жия і, я́коже Тя зрим ни́ні на іко́ні ізображе́нную, та́ко сподо́би нас узрі́ти Тя в час гро́зний сме́ртний, от руки́ дия́воли нас ісхища́ющую і в Ца́рствіє Христо́во приводя́щую ни держа́вною десни́цею Твоє́ю, да Тебі́ благода́рственно взива́єм:","Ра́дуйся, по Бо́зі пе́рвоє на́ше прибі́жище і покро́ве;","ра́дуйся, Ма́тернею любо́вію Твоє́ю весь мир христия́нський об'ємлющая.","Ра́дуйся, во свято́м житії́ ві́рния утвержда́ющая;","ра́дуйся, благу́ю христия́нськую кончи́ну їм подаю́щая.","Ра́дуйся, от вла́сті лю́таго мироде́ржця уповающия на Тя ізбавля́ющая;","ра́дуйся, на мита́рствах возду́шних заступа́ющая сла́в'ящих Тя.","Ра́дуйся, врата́ ра́йськая нам отверза́ющая;","ра́дуйся, Ца́рствіє Небе́сноє лю́б'ящим Тя хода́тайствующая.","Ра́дуйся, во сла́ві небе́сній присідя́щая Си́ну Твоєму́ і Бо́гу;","ра́дуйся, во обще́ніє Сла́ви Єго́ і чтущия Тя вводя́щая.","Ра́дуйся, тіле́с на́ших здра́віє;","ра́дуйся, душ на́ших спасе́ніє.","Ра́дуйся, христия́ном Помо́щнице і милосе́рдая о грі́шних Предста́тельнице."]},{"h":"Кондак 13","ps":["О всепі́тая Ма́ти, ро́ждшая святи́х Святі́йшеє Сло́во, от А́нгел воспіва́ємая на Небесі́ і от челові́к сла́вимая на землі́! Прийми́ ми́лостиво сіє́ ма́лоє моле́ніє на́ше і да́руй душе́вноє спасе́ніє і тіле́сноє здра́віє всім, ві́рно чту́щим Тя і пою́щим Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Арха́нгел Гавриї́л с небесе́ по́слан бисть от Тебе́, Богоро́дице, к смире́нному послу́шнику гори́ Афо́нськия, в пусти́нній келії воспевавшему Ті хвале́бния пі́сні пред свято́ю Твоє́ю іко́ною, да научи́ть єго́ пі́ти піснь небе́сную, є́юже славосло́в'ять Тя А́нгели в Сіо́ні го́рнем. Ті́мже і ми до́льнії, воспомина́я таково́є Твоє́ о лю́діх благопромишле́ніє, со благодаре́нієм вопіє́м Ті си́це:","Ра́дуйся, досто́йно восхваля́ємая от Арха́нгел і А́нгел;","ра́дуйся, ублажа́ємая от всіх небе́сних сил.","Ра́дуйся, Присноблаже́нная і Пренепоро́чная;","ра́дуйся, Ма́ти Бо́га на́шего.","Ра́дуйся, честні́йшая Херуви́м;","ра́дуйся, сла́внійшая без сравне́нія Серафи́м.","Ра́дуйся, без істлі́нія Бо́га Сло́ва ро́ждшая;","ра́дуйся, воі́стину су́щая Богоро́дице.","Ра́дуйся, величаємая на небесі́ і на землі́;","ра́дуйся, воспіва́ємая го́рними і до́льними.","Ра́дуйся, єди́на благослове́нная в жена́х;","ра́дуйся, ізрасти́вшая нам плод живота́.","Ра́дуйся, христия́ном Помо́щнице і милосе́рдая о грі́шних Предста́тельнице."]},{"h":"Кондак 1","ps":["Ізбра́нній Бо́гом от челові́чеськаго ро́да послужи́ти воплоще́нію предві́чнаго Сло́ва, преблагослове́нній Ді́ві Богоро́диці, досто́йно воспеваємой от А́нгел на Небесі́, ми грі́шнії на землі́ дерза́єм приноси́ти хвале́бноє пі́ніє; є́же ми́лостиво от нас приє́мши, всемилующая Цари́це Богоро́дице, от вся́ких бід нас спаси́ і ві́чних мук свободи́, да зове́м Ті:","Ра́дуйся, христия́ном Помо́щнице і милосе́рдая о грі́шних Предста́тельнице."]},{"h":"Молитва","ps":["О Пресвята́я і Преми́лостивая Влади́чице Богоро́дице! Припа́дая к святі́й іко́ні Твоє́й, смире́нно мо́лимся Тебі́, воньми́ гла́су моле́нія на́шего, виждь ско́рби, виждь біди́ на́ша і, я́ко любвеоби́льная Ма́ти, потщи́ся на по́мощ нам безпо́мощним, умоли́ Си́на Твоєго́ і Бо́га на́шего: да не погуби́ть нас за беззако́нія на́ша, но яви́ть нам человіколю́бно свою́ ми́лость. Іспроси́ нам, Влади́чице, у бла́гости Єго́ тіле́сноє здра́віє і душе́вноє спасе́ніє, і ми́рноє житіє́, землі́ плодоно́сіє, возду́ха благорастворе́ніє, і благослове́ніє сви́ше на вся блага́я діла́ і начина́нія на́ша. І я́коже дре́вле призрі́ла єси́ ми́лостиво на смире́нноє славосло́віє послу́шника Афо́нськаго, воспева́вшего Тя пред пречи́стою іко́ною Твоє́ю і посла́ла єси́ к нему́ А́нгела научи́ти єго́ пі́ти піснь небе́сную, є́юже славосло́в'ять Тя А́нгели; та́ко і ни́ні прийми́ на́ше усе́рдноє молитвосло́віє, Тебі́ приноси́моє. О Цари́ці Всепі́тая! Простри́ ко Го́споду богоно́сния Твоя́ ру́ці, і́миже Богомладе́нця Ісу́са Христа́ носи́ла єси́, і умоли́ Єго́ ізба́вити нас от вся́каго зла. Яви́, Влади́чице, Твою́ ми́лость к нам: боля́щия ісціли́, скорб'я́щия уті́ши, бе́дствующим помози́ і сподо́би нас благоче́стно житіє́ сіє́ земно́є соверши́ти, христия́нськую непости́дную кончи́ну получи́ти і Небе́сноє Ца́рствіє наслі́дити ма́тернім хода́тайством Твої́м к Ро́ждшемуся от Тебе́ Христу́ Бо́гу на́шему, Єму́же со Безнача́льним Єго́ Отце́м і Пресвяти́м Ду́хом подоба́єть вся́кая сла́ва, честь і поклоне́ніє ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Отце́во все Афо́нськоє мно́жество, / собері́теся, ві́рно пра́зднующе, / днесь ра́дующеся і сві́тло восклиця́юще всі во весе́лії, / Бо́жия бо Ма́ти ни́ні от А́нгела пресла́вно воспіва́ється. // Ті́мже, я́ко Бого́родицю, при́сно Сію́ сла́вим."]},{"h":"Інший тропар, глас 4","ps":["Притеце́м, ві́рнії, со дерзнове́нієм / к Ми́лующей Цари́це Богоро́дице / і умиле́нно воззове́м к Ней: / низпосли́ на ни ми́лості Твоя́ бога́тия: / град сей ізба́ви от вся́каго обстоя́нія, / мир да́руй ми́рові // і спасе́ніє душа́м на́шим."]},{"h":"Інший тропар, глас 4","ps":["Притеце́м, ві́рнії, со дерзнове́нієм / к ми́лующей Цари́це Богоро́дице / і уми́льно воззове́м к Ней: / низпосли́ на ни ми́лості Твоя́ бога́тия: / Це́рков на́шу сохрани́, / лю́ди во благоде́нствії соблюди́, / зе́млю на́шу ізба́ви от вся́каго обстоя́нія, / мир да́руй ми́рові // і спасе́ніє душа́м на́шим."]},{"h":"Кондак, глас 4","ps":["Пра́зднуєть днесь весь Афо́н, / я́ко піснь прия́т от А́нгела чу́дно / Тебі́, Чи́стій Богома́тері, // Ю́же вся твар чтить, сла́вящи."]},{"h":"Інший кондак, глас 8","ps":["Арха́нгельський глас вопіє́м Ті, Всецари́це: / досто́йно єсть, я́ко воі́стину, / блажи́ти Тя, Богоро́дицю, / Присноблаже́нную і Пренепоро́чную, // і Ма́тер Бо́га на́шего."]},{"h":"Величання","ps":["Досто́йно єсть / велича́ти Тя, / Богоро́дице, / Честні́йшую Херуви́м / і Сла́внійшую // без сравне́нія Серафи́м."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Помічниця в пологах»","e":"Akathist to the Theotokos before her icon “Helper in Childbirth”","secs":[{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́в Помо́щнице ро́да христия́нськаго, к богоуго́дній жи́зні ражда́ющей, благода́рственная пі́нія прино́сим Ті, Богоро́дице, о дарова́нії чу́дния іко́ни Твоєя́. Ти же, я́ко ско́рая і всеми́лостивая ві́рних Засту́пнице, не оста́ви нас в ско́рбіх, да зове́м Ті:","Ра́дуйся, Помо́щнице в ро́дах, чад Свої́х к Царю́ сла́ви приводя́щая."]},{"h":"Ікос 1","ps":["А́нгел предста́тель по́слан бисть рещи́ Богоро́дице: Ра́дуйся,— єгда́ Бог Сло́во воплоща́шеся во утро́бі Єя́; і ми, грі́шнії, див'я́щеся Свято́му Рождеству́, пред іко́ною чу́дною Твоє́ю с ві́рою і наде́ждою вопіє́м Ті:","Ра́дуйся, ра́дость Христо́ва Рождества́ позна́вшая;","ра́дуйся, Си́на Сві́та нам дарова́вшая.","Ра́дуйся, ско́рби гоне́ній с Плодо́м во чре́ві претерпі́вшая;","ра́дуйся, в по́двизіх матери́нських на землі́ преуспе́вшая.","Ра́дуйся, ско́рби родо́во в ра́дость претворя́ющая;","ра́дуйся, Твоє́ю любо́вію нас для Не́ба созида́ющая.","Ра́дуйся, по́двигом житія́ Твоєго́ нас просвіти́вшая;","ра́дуйся, чу́дними ро́дами весь мир удиви́вшая.","Ра́дуйся, Помо́щнице в ро́дах, чад свої́х к Царю́ сла́ви приводя́щая."]},{"h":"Кондак 2","ps":["Ви́дящи, Всенепоро́чная, во сла́ві Си́на Твоєго́ пред на́ми пребива́ющая, ско́рби ві́рних рабо́в Твої́х, я́же гні́внаго ра́ди Бо́жия вразумле́нія посила́ємия, благоволи́ла єси́ яви́ти іко́ну Твою́, чудеси́ ю прославля́ющи, да, покрива́ємії Твоє́ю любо́вію, с наде́ждою вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Жизнода́теля ро́ждшая, Пресвята́я Богоро́дице, благода́тноє попече́ніє жена́м в ро́дах утверди́ла єси́, ра́зуму на́шему просвіще́ніє сви́ше ісхода́тайствовала єси́, да позна́єм, что єсть во́ля Бо́жия блага́я, уго́дная і соверше́нная. Ми же, див'я́щеся сви́ше благода́тному укріпле́нію со слеза́ми ра́дости вопіє́м Ті:","Ра́дуйся, от гріхо́в нас отвраща́ющая;","ра́дуйся, тру́дную до́лю жен облегча́ющая.","Ра́дуйся, сердця́ на́ша любо́вію Твоє́ю ум'ягча́ющая;","ра́дуйся, моли́твами Твої́ми Си́на нам в по́мощ призива́ющая.","Ра́дуйся, Рождество́ Си́на Твоєго́ нікогда́ не забива́ющая;","ра́дуйся, в ро́дах жен христия́нських не оставля́ющая.","Ра́дуйся, в духо́вном рожде́нії всіх благословля́ющая;","ра́дуйся, в світ Си́на Твоєго́ неізмі́нно призива́ющая.","Ра́дуйся, Помо́щнице в ро́дах, чад свої́х к Царю́ сла́ви приводя́щая."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго благода́тію Богома́тере зе́млю Ру́ськую освяща́єть, чад духо́вних Свої́х ізмла́да любо́вію умудря́ющи і во́їнов Христо́вих к чистоті́ Правосла́вія непреста́нно призива́ющи; ми же с ві́рою прибіга́єм ко Го́споду, пред іко́ною Твоє́ю, Богоро́дице, вопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 3","ps":["І́мами Тя, Засту́пнице усе́рдная ро́да христия́нськаго, я́ко Ма́тер, чад Свої́х покая́нію і смире́нію науча́ющую, то́ки чуде́с нам во укріпле́ніє от пречестни́я іко́ни Своєя́ ми́лостивно істоча́ющую, благода́тію от Бо́га во спасе́ніє всіх нас осіня́ющую. Сего́ ра́ди зове́м Ті си́це:","Ра́дуйся, явле́нієм іко́ни Твоєя́ мглу лю́тих обстоя́ній отгоня́ющая;","ра́дуйся, во святі́й Русі́ ві́рних чад правосла́вною ві́рою окриля́ющая.","Ра́дуйся, бо́ли при ро́дах благода́тію Свята́го Ду́ха ослабля́ющая;","ра́дуйся, любо́в Твою́ всегда́ нам істоча́ющая.","Ра́дуйся, в ско́рбіх мно́гим жена́м прозрі́ніє;","ра́дуйся, да́рующая лю́б'ящим Си́на Твоєго́ моли́твенноє попече́ніє.","Ра́дуйся, сердця́ на́ша ра́достію родо́в ум'ягча́ющая;","ра́дуйся, в свя́тость і чистоту́ ді́тства нас возвраща́ющая.","Ра́дуйся, Помо́щнице в ро́дах, чад Свої́х к Царю́ сла́ви приводя́щая."]},{"h":"Кондак 4","ps":["Бу́рю лю́тих см'яте́ній во страні́ на́шей воздви́гнутих врага́ми Це́ркве, Пресвята́я Ді́во, укроща́єши, чад Твої́х заблу́ждших в покая́нії умудря́єши, ду́ші жен во́їнов Христо́вих в ро́дах наде́ждою сві́тлою укріпля́єши, науча́ющи тім лю́ди Твоя́ благода́рственно пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше правосла́внії лю́діє сокрове́нную та́йну, я́ко предста́тельством Твої́м, Богоро́дице, суд о Оте́честві на́шем преложе́н на ми́лость, і див'я́щеся сви́ше благода́тному Твоєму́ попече́нію, благогові́йно вопіє́м Ті си́це:","Ра́дуйся, на́ша се́ми от уни́нія ізбавля́ющая;","ра́дуйся, благода́тним Твої́м покро́вом младе́нці осіня́ющая.","Ра́дуйся, ско́рби ра́ди покри́тія гріхо́в нам попуска́ющая;","ра́дуйся, чад на́ших в свя́тости охраня́ющая.","Ра́дуйся, ю́ность на́шу сві́том і́стини просвіща́ющая;","ра́дуйся, супру́жества вінча́нная пред Бо́гом с любо́вію храня́щая.","Ра́дуйся, к Та́їнству вінча́нія супру́ги призива́ющая;","ра́дуйся, от блуда́ сме́ртнаго всіх ві́рних предостерега́ющая.","Ра́дуйся, Помо́щнице в ро́дах, чад Свої́х к Царю́ сла́ви приводя́щая."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ яви́ся нам, Богоро́дице, честна́я Твоя́ іко́на, всіх скорб'я́щих в ро́дах жен луча́ми чуде́с Твої́х осіява́ющая, блужда́ющих в духо́внім мра́ці к сві́ту Си́на Твоєго́ призива́ющая, в гріхо́вних страстеіх утопа́ющих в благода́тний мир ми́лостію Бо́га Отця́ облека́ющая і на путь спасе́нія утіше́нієм Свята́го Ду́ха наставля́ющая. Ми же, ві́рою обрі́тше ра́дости сія́, вопіє́м к Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Сли́шавше правосла́внії лю́діє, я́ко святу́ю іко́ну Твою́, Богоро́дице, Госпо́дь мно́гими чудеси́ прославля́єть: ско́рби жен христия́нських в ро́дах облегча́єть, сердца́ оте́ць і ма́терей во сла́ву Бо́жию ра́достію наполня́єть,— я́ко освяще́ніє, я́ко щит і вспоможе́ніє почита́ють ю. Сего́ ра́ди вопіє́м Ті си́це:","Ра́дуйся, жили́ще і до́ме Христа́ Бо́га на́шего;","ра́дуйся, спасе́ніє ру́ськаго наро́да, в отчужде́ніє от Бо́га ду́хом впа́вшаго.","Ра́дуйся, христия́н непобіди́мая Храни́тельнице;","ра́дуйся, Іскупи́теля гріхо́в на́ших ро́ждшая.","Ра́дуйся, благода́тній наде́ждой сердца́ жен в ро́дах наполня́ющая;","ра́дуйся, к духо́вному рожде́нію в Та́їнстві Креще́нія неуста́нно призива́ющая.","Ра́дуйся, доброді́телей вели́коє стяжа́ніє;","ра́дуйся, Бо́жиє к немощни́м благоволе́ніє.","Ра́дуйся, Помо́щнице в ро́дах, чад Свої́х к Царю́ сла́ви приводя́щая."]},{"h":"Кондак 6","ps":["Пред пречи́стим Твої́м о́бразом пропові́даєм, Госпоже́ Богоро́дице, вели́кия Твоя́ ми́лості, я́ко се́ми христия́н огражда́єши, це́ркві дома́шнія благода́тію Свята́го Ду́ха покрива́єши, жен со ча́ди защища́єши, і, ві́дуще Тя воі́стину Помо́щницю непобіди́му, прино́сим Ті славосло́вія сія́ і ра́достно вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Воссія́вши просвіще́ніє і́стинноє, Пречи́стая Богоро́дице, яви́ся чу́дная іко́на Твоя́, роди́телем на утіше́ніє, рассе́янним се́мям во воссоєдине́ніє, востаю́щим на Го́спода неві́рієм в предупрежде́ніє, всім нам во укріпле́ніє і ві́чноє блаже́нство во Христі́, Го́сподом дарова́нноє іскупле́нієм. Ми же, див'я́щеся о нас попече́нію, благода́рно вопіє́м Ті:","Ра́дуйся, от внеза́пния сме́рти нас ізбавля́ющая;","ра́дуйся, мра́чних духо́в свя́тостію Твоє́ю отгоня́ющая.","Ра́дуйся, покро́вом Твої́м нас осіня́ющая;","ра́дуйся, і́стинно нас моли́тися науча́ющая.","Ра́дуйся, к долготерпі́нію в ско́рбіх і неду́зіх нас приклоня́ющая;","ра́дуйся, богоно́снеї ру́ці Твої́ за нас, грі́шних, к Си́ну в моли́тві непреста́нно вознося́щая.","Ра́дуйся, ніколи́же ві́рних Си́ну Твоєму́ заступле́нієм не оставля́ющая;","ра́дуйся, немощни́х благода́тним Покро́вом Твої́м покрива́ющая.","Ра́дуйся, Помо́щнице в ро́дах, чад Свої́х к Царю́ сла́ви приводя́щая."]},{"h":"Кондак 7","ps":["Хотя́й всім челові́ком спасти́ся і во і́стині просвіти́тися, Премилосе́рдий Госпо́дь, усинови́ нас Ма́тері Своє́й і дарова́ Ю жена́м христия́нським в ро́дах в поможе́ніє, ча́дом на́шим в благода́тноє Небе́сноє окормле́ніє. Ми же, обрі́тше от Бо́га ра́дости сія́, со слеза́ми вопіє́м Вседержи́телю: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ву показа́ ми́лость всіх Творе́ць і Влади́ка наш Госпо́дь, єгда́ положи́ во гні́ві Своє́м за гріх наказа́ти род челові́чеський і рече́ жені́ Ада́ма: В болі́зніх роди́ши ча́да твоя́,— я́ко сотвори́ сіє́ для мно́гих челові́ков ко вразумле́нію спасе́нія ра́ди душ їх. Сего́ ра́ди і ми, Влади́чице, припа́дающе к пречи́стому о́бразу Твоєму́, усе́рдно мо́лим Тя: милосе́рдія две́рі отве́рзи нам, вопію́щим Ті си́це:","Ра́дуйся, непристу́пнаго Божества́ селе́ніє;","ра́дуйся, А́нгельськоє і на́ше непреста́нноє удивле́ніє.","Ра́дуйся, Бо́жия ми́лості і любве́ ісполне́ніє;","ра́дуйся, Пода́тельнице спаси́тельнаго в ро́дах вспоможе́нія.","Ра́дуйся, пра́вди святи́я Попечи́тельнице;","ра́дуйся, любве́ і добро́ти непоколеби́мая Храни́тельнице.","Ра́дуйся, в го́рдості закосне́вших заступле́нія Твоєго́ лиша́ющая;","ра́дуйся, от креще́них младе́нцев ра́достний взор Твой не отвраща́ющая.","Ра́дуйся, Помо́щнице в ро́дах, чад Свої́х к Царю́ сла́ви приводя́щая."]},{"h":"Кондак 8","ps":["Стра́нно малове́рующим сли́шати, ка́ко о́браз Твой святи́й то́ки благода́ті істоча́єть, грі́шним, в покая́нії к Тебі́ прише́дшим, ра́дость да́рить, ісціле́нієм скорб'я́щих і боля́щих жен в ро́дах Бо́га прославля́єть, ми же с ві́рою поклоня́ємся Тебі́: о́браз бо че́стію к первоо́бразу восхо́дить, і, всемі́рно прославля́юще Тя, с ра́достію поє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся єси́ горе́ і земни́х не оставля́вши, Пресвята́я Богоро́дице, у́зи страсте́й благода́тним попече́нієм ослабля́єши, в покая́нії притека́ющим к Тебі́ предста́тельством пред Бо́гом очища́єши, іскупле́нієм Христо́вим сердця́ на́ша преобража́єши. Сего́ ра́ди, велича́юще, воспіва́єм Ті та́ко:","Ра́дуйся, чрез покая́ніє к Бо́гу, приводя́щая;","ра́дуйся, покая́нієм на́шим две́рі ра́йськія отверза́ющая.","Ра́дуйся, роди́тельським покая́нієм от чад болі́зні отвраща́ющая;","ра́дуйся, покая́нієм мир духо́вний в се́мях ві́рних утвержда́ющая.","Ра́дуйся, покая́нієм бісо́вськия разла́ди в се́мях угаша́ющая;","ра́дуйся, покая́нієм церко́вним со Христо́м нас внов соєдиня́ющая.","Ра́дуйся, в покая́нії приходя́щих преобража́ющая;","ра́дуйся, чрез покая́ніє заступле́нієм Твої́м пред Си́ном спаса́ющая.","Ра́дуйся, Помо́щнице в ро́дах, чад Свої́х к Царю́ сла́ви приводя́щая."]},{"h":"Кондак 9","ps":["Вся́каго єстества́ а́нгельськаго преви́сшая яви́лася єси́, Пресвята́я Ді́во, Бо́га бо зачала́ єси́ пло́тію, Го́спода во утро́бі Твоє́й вмісти́ла єси́, ті́мже я́ко Святі́йшую і Сла́внійшую у Престо́ла Царя́ царе́й велича́юще Тя, вопіє́м о Тебі́ Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йства боговіща́нних прорече́ній ни́ні зрим о Тебі́ сби́вшаяся, Богоро́дице, я́ко воі́стину Бо́га пло́тію родила́ єси́ нам. І бу́дущаго Ца́рствія Бо́жия не лиши́ нас, Покро́вом Твої́м нас от ко́зней ми́ра сего́ оберега́ющи. Ми же обетова́нноє блаже́нство во Христі́ в моли́твах призива́єм і в покая́нії вопіє́м Ті:","Ра́дуйся, тве́рдоє Правосла́вія укріпле́ніє;","ра́дуйся, душ на́ших ско́роє спасе́ніє.","Ра́дуйся, отчужде́нних от Бо́га к ві́рі возрожде́ніє;","ра́дуйся, духо́вноє на́ше прозрі́ніє.","Ра́дуйся, в чистоті́ Правосла́вія нас оберега́ющая;","ра́дуйся, от гріхо́внаго паде́нія нас ізводя́щая.","Ра́дуйся, вопію́щих к Тебі́ ско́роє усли́шаніє;","ра́дуйся, чадоро́діє благословля́ющая.","Ра́дуйся, Помо́щнице в ро́дах, чад Свої́х к Царю́ сла́ви приводя́щая."]},{"h":"Кондак 10","ps":["Спасти́ хотя́щи мно́гія жени́ в ро́дах от обдержа́щих їх страсте́й і напа́стей, чу́дную іко́ну Твою́, Богома́ти, дарова́ла єси́, єя́же ра́ди ко́зні дия́вола утиха́ють, смертоно́сния болі́зні ісчеза́ють, бо́ли в ро́дах ослабіва́ють, да всі, ви́дяще явля́ємую Тобо́ю ми́лость, вопію́ть со умиле́нієм Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́, Богоро́дице Ді́во, Святі́й Русі́ і наро́ду єя́ огражде́ніє, враго́в Правосла́вія обличе́ніє, жена́м-ма́терем сугу́боє утіше́ніє, ма́лим ча́дом благода́тноє попече́ніє. Ті́мже, благодаря́ще Тя, вопіє́м Бо́гу:","Ра́дуйся, прославля́ющих Тя от бід ізбавля́ющая;","ра́дуйся, позаби́вших Тя посрамля́ющая.","Ра́дуйся, правосла́вних ма́терей сла́во і попече́ніє;","ра́дуйся, сохраня́ющих целому́дріє ві́рноє огражде́ніє.","Ра́дуйся, спаси́тельний Єле́ю ка́ющихся;","ра́дуйся, Цари́це Небе́сная всіх во Христі́ ражда́ющихся.","Ра́дуйся, ра́дости на́ша умножа́ющая;","ра́дуйся, младе́нцев і ма́терей сугу́бою любо́вію Твоє́й защища́ющая.","Ра́дуйся, Помо́щнице в ро́дах, чад Свої́х к Царю́ сла́ви приводя́щая."]},{"h":"Кондак 11","ps":["Пі́ніє хвале́бноє і благода́рственноє прино́сим Ті, Пресвята́я Влади́чице: под Покро́вом Твої́м в Правосла́вній Це́ркві по ми́лості Бо́жієй ражда́ємся, в благода́тном окормле́нії Твоє́м неізмі́нно умудря́ємся, заступле́нієм Твої́м во Христі́ іскони́ спаса́ємся, і возложи́вше на Тя упова́ніє, ра́достно вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоприє́мная свіща́ і́стиннаго Сві́та су́щим нам на землі́ я́вльшися, ду́ші просвіща́єши, чту́щих Тя во ві́рі во спасе́ніє наставля́єши, младе́нцев во утро́бах ма́терей охраня́єши, да поє́м Ті си́це:","Ра́дуйся, в рожде́нії чад ско́рби ослабля́ющая;","ра́дуйся, гріхи́ на́ша Твої́ми моли́твами к Си́ну отпуска́ющая.","Ра́дуйся, во́їном Христо́вим жен смире́нних посила́ющая;","ра́дуйся, непоро́чность отрокови́ць охраня́ющая.","Ра́дуйся, духо́вно всіх неви́димо окормля́ющая;","ра́дуйся, Твоє́ю любо́вію в біда́х нас покрива́ющая.","Ра́дуйся, от ху́льних ми́слей предостерега́ющая;","ра́дуйся, от умерщвле́нія нероди́вшихся младе́нцев всіх отвраща́ющая.","Ра́дуйся, Помо́щнице в ро́дах, чад Свої́х к Царю́ сла́ви приводя́щая."]},{"h":"Кондак 12","ps":["Благода́ть Небе́сния сла́ви Твоєя́ да́ти восхоті́вши почита́ющим Тя с любо́вію, Влади́чице, по ві́рі да́руєши чрез іко́ну Твою́ богообще́ніє, зна́менія і чудеса́ ісціле́нія, от духо́вних скорбе́й ізбавле́ніє. Ми же, ві́дівше сокро́вища сія́, велегла́сно вопіє́м к Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твоя́ чудеса́, би́вшая в дре́вняя і настоя́щая времена́, хва́лим Тя, Богоро́дице, ві́рним врата́ в жизнь ві́чную моли́твами Твої́ми отверза́ющая, благода́тію Свята́го Ду́ха в земно́й жи́зні защища́ющая, ко Го́споду люде́й ізбра́нних Твоє́ю любо́вію привлека́ющая; ми же, упова́ніє по Бо́зі возлага́юще на Тя, с покая́нієм вопіє́м си́це:","Ра́дуйся, отча́янних спасе́ніє;","ра́дуйся, погиба́ющих оживле́ніє.","Ра́дуйся, от бід ізбавле́ніє;","ра́дуйся, духо́вния ра́дости утвержде́ніє.","Ра́дуйся, оби́димих Уті́шительнице;","ра́дуйся, гони́мих Покрови́тельнице.","Ра́дуйся, в ма́лом ві́рних укріпля́ющая;","ра́дуйся, возлюби́вших Го́спода окормля́ющая.","Ра́дуйся, Помо́щнице в ро́дах, чад Свої́х к Царю́ сла́ви приводя́щая."]},{"h":"Кондак 13","ps":["О Всепі́тая Ма́ти, Помо́щнице в ро́дах, ро́ждшая всіх святи́х Святі́йшеє Сло́во, наде́ждо духо́внаго на́шего пробужде́нія і во всем блага́го поспіше́нія, в ро́дах тіле́сних, Благода́тная, жена́м правосла́вним утіше́ніє, Ца́рствія Небе́снаго наслі́дники всіх сотвори́, ві́рно вопію́щих Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел предста́тель по́слан бисть рещи́ Богоро́дице: Ра́дуйся,— єгда́ Бог Сло́во воплоща́шеся во утро́бі Єя́; і ми, грі́шнії, див'я́щеся Свято́му Рождеству́, пред іко́ною чу́дною Твоє́ю с ві́рою і наде́ждою вопіє́м Ті:","Ра́дуйся, ра́дость Христо́ва Рождества́ позна́вшая;","ра́дуйся, Си́на Сві́та нам дарова́вшая.","Ра́дуйся, ско́рби гоне́ній с Плодо́м во чре́ві претерпі́вшая;","ра́дуйся, в по́двизіх матери́нських на землі́ преуспе́вшая.","Ра́дуйся, ско́рби родо́во в ра́дость претворя́ющая;","ра́дуйся, Твоє́ю любо́вію нас для Не́ба созида́ющая.","Ра́дуйся, по́двигом житія́ Твоєго́ нас просвіти́вшая;","ра́дуйся, чу́дними ро́дами весь мир удиви́вшая.","Ра́дуйся, Помо́щнице в ро́дах, чад свої́х к Царю́ сла́ви приводя́щая."]},{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́в Помо́щнице ро́да христия́нськаго, к богоуго́дній жи́зні ражда́ющей, благода́рственная пі́нія прино́сим Ті, Богоро́дице, о дарова́нії чу́дния іко́ни Твоєя́. Ти же, я́ко ско́рая і всеми́лостивая ві́рних Засту́пнице, не оста́ви нас в ско́рбіх, да зове́м Ті:","Ра́дуйся, Помо́щнице в ро́дах, чад Свої́х к Царю́ сла́ви приводя́щая."]},{"h":"Молитва перша","ps":["Прийми́, Госпоже́ Богороди́тельнице, сле́зная моле́нія рабо́в Твої́х, к Тебі́ притека́ющих. Зрим Тя на святі́й іко́ні во чре́ві нося́щую Си́на Твоєго́ і Бо́га на́шего, Го́спода Ісу́са Христа́. А́ще і безболі́зненно родила́ єси́ Єго́, оба́че ма́тернія ско́рби ві́си і не́мощі сино́в і дще́рей челові́чеських зри́ши. Ті́мже те́плі припа́дающе к цільбоно́сному о́бразу Твоєму́ і умиле́нно сей лобиза́юще, мо́лим Тя, Всеми́лостивая Влади́чице: нас, грі́шних, осужде́нних в болі́зніх роди́ти і в печа́ліх пита́ти ча́да на́ша, ми́лостивно пощади́ і сострада́тельно заступи́. Младе́нці же на́ша, та́кожде і роди́вшия їх, от тя́жкаго неду́га і го́ркия ско́рби ізба́ви; да́руй їм здра́віє і благомо́щіє, да і пита́ємії от си́ли в си́лу возраста́ти бу́дуть, і пита́ющия їх іспо́лняться ра́достію і утіше́нієм, я́ко да і ни́ні предста́тельством Твої́м із уст младе́нець і ссу́щих Госпо́дь соверши́ть хвалу́ Свою́.","О Ма́ти Си́на Бо́жия! Умилосе́рдися на ма́тері сино́в челові́чеських і на немощни́я лю́ди Твоя́: постига́ющия нас болі́зні ско́ро ісціли́, належа́щия на нас ско́рби і печа́лі утоли́ і не пре́зри слез і воздиха́ній рабо́в Твої́х. Усли́ши нас в день ско́рби, пред іко́ною Твоє́ю припа́дающих, і в день ра́дости і ізбавле́нія прийми́ благода́рная хвале́нія серде́ць на́ших. Вознеси́ мольби́ на́ша ко Престо́лу Си́на Твоєго́ і Бо́га на́шего, да ми́лостив бу́деть ко гріхо́м і не́мощем на́шим і проба́вить ми́лость Свою́ ві́дущим і́м'я Єго́, я́ко да і ми, і ча́да на́ша, просла́вим Тя, Милосе́рдную Засту́пницю і ві́рную Наде́жду ро́да на́шего, во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О Пресвята́я Госпоже́ Влади́чице Богоро́дице, в земно́й жи́зні нас не оставля́ющая! Ко кому́ моли́тви вознесу́, ко кому́ сле́зи і воздиха́нія принесу́, а́ще не к Тебі́, всіх ві́рних утіше́ніє! Со стра́хом, ві́рою, любо́вію, Ма́ти Живота́, молю́: да вразуми́ть Госпо́дь лю́ди правосла́вния во спасе́ніє, да дасть ражда́ти нам чад Тебі́ і Си́ну Твоєму́ во благоугожде́ніє, да соблюде́ть нас в чистоті́ смире́нія, в наде́жді о Христі́ спасе́нія, і да́руєть нам всім, в покро́віх благода́ті Твоєя́, земно́є утіше́ніє. Храни́ нас под сі́нію ми́лости Твоєя́, Пречи́стая, моля́щимся о ро́дах помози́, наві́тов злих свободи́, тя́жких бід, напа́стей і смерте́й отврати́. Даждь благода́тноє прозрі́ніє, дух сокруше́нія о грісі́х, даждь зрі́ти всю висоту́ і чистоту́ дарова́ннаго нам Христо́ва уче́нія; храни́ нас от поги́бельнаго отчужде́нія, да всі, благода́рні воспіва́юще вели́чія Твоя́, сподо́бимся Небе́снаго успокоє́нія і та́мо с возлю́бленними Твої́ми, со всі́ми святи́ми просла́вим в Тро́йці Єди́наго Бо́га: Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Ма́ти Бо́га на́шего, во утро́бі заче́нши Христа́ Жизнода́вця, по́мощі в рожде́нії Того́ не потре́бовала єси́, ті́мже ле́гці разріши́тися рабо́м Твої́м благослови́ і помози́, і младе́нцев їх во вре́м'я благопотре́бноє роди́тися іму́щих, под покро́в Твой, я́ко Ма́тер, мо́лим, прийми́: Ти бо єси́ в ро́дах Помо́щниця, Засту́пниця рабо́м Твої́м."]},{"h":"Кондак, глас 2","ps":["Слез Є́виних разріше́ніє, проро́чеських писа́ній ісполне́ніє, от Ду́ха Свята́го Богомладе́нця заче́ншая, і во я́сліх Вифлеє́мских Того́ смире́нно роди́вшая, к Тебі́ прибіга́єм я́ко Храни́тельнице жен і младе́нцев, к Тебі́ воздиха́єм і Тя велича́єм: ра́дуйся, Благоутро́бная Ма́ти, в ро́дах Помо́щниця."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтем о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Пом’якшення злих сердець» (Семистрільна)","e":"Akathist to the Theotokos before her icon “Softener of Evil Hearts” (Seven Arrows)","secs":[{"h":"Кондак 1","ps":["Ізбра́нной Ді́ві Марі́ї, преви́сшей всіх дще́рей землі́, Ма́тері Си́на Бо́жия, Є́юже дає́ться спасе́ніє ми́ра, со умиле́нієм взива́єм: воззри́ на многоско́рбноє житіє́ на́ше, воспом'яни́ ско́рби і болі́зні, я́же претерпі́ла єси́, я́ко на́ша земноро́дная, і сотвори́ с на́ми по милосе́рдію Твоєму́, да зове́м Ті:","Ра́дуйся, многоско́рбная Ма́ти Бо́жия, печа́ль на́шу в ра́дость претворя́ющая і сердця́ злих челові́к ум'ягча́ющая."]},{"h":"Ікос 1","ps":["А́нгел возвісти́ па́стирем вифлеє́мстим о Рождестві́ Спаси́теля ми́ра, і с ним мно́жество во́єв небе́сних восхваля́ху Бо́га, пою́ще: «Сла́ва во ви́шніх Бо́гу, і на землі́ мир, в челові́ціх благоволе́ніє». Ти же, Ма́ти Бо́жия, не імі́вши гді главу́ преклони́ти, зане́ не бі мі́ста во оби́теліх, родила́ Си́на Своєго́ Пе́рвенця во верте́пі, і пови́ла Єго́ пелена́ми, і положи́ла Єго́ в я́сліх. Ті́мже, скорб се́рдця Твоєго́ ві́дуще, вопіє́м Ті:","Ра́дуйся, диха́нієм Свої́м Си́на Своєго́ возлю́бленнаго согре́вшая;","ра́дуйся, Преві́чнаго Младе́нця пелена́ми пови́вшая.","Ра́дуйся, Носи́теля вселе́нния мле́ком Свої́м пита́вшая;","ра́дуйся, верте́п в не́бо обрати́вшая.","Ра́дуйся, престо́л херуви́мський соде́лавшаяся;","ра́дуйся, в рождестві́ і по рождестві́ Ді́ва преби́вшая.","Ра́дуйся, многоско́рбная Ма́ти Бо́жия, печа́ль на́шу в ра́дость претворя́ющая і сердця́ злих челові́к ум'ягча́ющая."]},{"h":"Кондак 2","ps":["Ви́дяще Преві́чнаго Младе́нця пови́та лежа́ща в я́сліх, прише́дше, поклони́шася Єму́ па́стирі вифлеє́мстії і глаго́лаша рече́нноє їм а́нгели о Отроча́ти. Марія́м же соблюда́ше вся глаго́ли сія́ в се́рдці Своє́м. По проше́ствії же осьми́ дній обрі́зан бі Ісу́с по зако́ну Ізра́їлеву, я́ко Челові́к. Воспіва́юще смире́ніє і терпі́ніє Твоє́, Богоро́дице, поє́м Ві́чному Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум іму́ще в Бо́зі утвержде́нний і соблюда́юще Зако́н Госпо́день, в четиредеся́тий день, єгда́ іспо́лнишася дні́є очище́нія, вознесо́ста Ісу́са во Ієрусали́м роди́теліє Єго́, є́же поста́вити Єго́ пред Го́сподем і да́ти за Него́ же́ртву по рече́нному в Зако́ні Госпо́днем; ми же вопіє́м Богоро́дице си́це:","Ра́дуйся, Созда́теля вселе́нния во ісполне́ніє Зако́на в храм Ієрусали́мський прине́сшая;","ра́дуйся, та́мо ста́рцем Симео́ном ра́достно сре́тенная.","Ра́дуйся, Єди́на Чи́стая і Благослове́нная в жена́х;","ра́дуйся, крест Твой, скорбми́ преукраше́нний, во смире́нії не́сшая.","Ра́дуйся, во́лю Бо́жию ніколи́же преслу́шавшая;","ра́дуйся, о́браз терпі́нія і смире́нія нам Собо́ю яви́вшая.","Ра́дуйся, сосу́де, іспо́лненний благода́ті Ду́ха Свята́го;","ра́дуйся, ро́ждшая Си́на Єдиноро́днаго Отця́ Небе́снаго.","Ра́дуйся, многоско́рбная Ма́ти Бо́жия, печа́ль на́шу в ра́дость претворя́ющая і сердця́ злих челові́к ум'ягча́ющая."]},{"h":"Кондак 3","ps":["Си́лою сви́ше укріпля́єма била́ єси́, Ма́ти Бо́жия, єгда́ усли́шала єси́ словеса́ пра́веднаго ста́рця Симео́на: «Се, лежи́ть Сей на паде́ніє і на воста́ніє мно́гим во Ізра́їлі і в зна́меніє преріка́ємо, і Тебі́ же Само́й ду́шу про́йдеть ору́жіє, я́ко да откри́ються от мно́гих серде́ць помишле́нія». Оба́че скорб ве́лія пронзе́ се́рдце Богоро́диці, і возопи́ Сія́ Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я тща́ніє погуби́ти Отроча́, посла́ І́род ізби́ти вся ді́ти, су́щия во Вифлеє́мі і преді́ліх єго́, от двою́ лі́ту і нижа́йше, по вре́мені, є́же іспита́ от волхво́в. І се, повелі́нієм Бо́жиїм, да́нним чрез а́нгела во сні ста́рцю Іо́сифу, біжа́ все Свято́є Семе́йство во Єги́пет і преби́сть та́мо седьм літ до сме́рти І́рода. Ті́мже со умиле́нієм воспоє́м Ті, Богоро́дице:","Ра́дуйся, всю тісноту́ стра́нствія поне́сшая;","ра́дуйся, я́ко всі і́доли падо́ша в страні́ Єги́петстій, не возмо́гше терпі́ти крі́пости Си́на Твоєго́.","Ра́дуйся, с нечести́вими язи́чники пребива́вшая;","ра́дуйся, із Єги́пта с Пе́рвенцем О́троком і Свої́м обру́чником в Назаре́т прише́дшая.","Ра́дуйся, со ста́рцем Іо́сифом древоде́лом в нищеті́ жи́вшая;","ра́дуйся, все вре́м'я Своє́ в труді́х провожда́вшая.","Ра́дуйся, многоско́рбная Ма́ти Бо́жия, печа́ль на́шу в ра́дость претворя́ющая і сердця́ злих челові́к ум'ягча́ющая."]},{"h":"Кондак 4","ps":["Бу́ря ско́рби обдержа́ Пречи́стую Ма́тер, єгда́ возвраща́ющимася і́ма із Ієрусали́ма не обріто́ша в путі́ О́трока Ісу́са. Сего́ ра́ди возврати́стася во Ієрусали́м, взиска́юще Єго́. І бисть по тріє́х днех, обріто́ста Єго́ в це́ркві, сідя́щаго посреді́ учи́телей, і послу́шающаго їх, і вопроша́ющаго їх. І рече́ к Нему́ Ма́ти Єго́: «Ча́до, что сотвори́ на́ма та́ко? Се оте́ць Твой і Аз, боля́ще, іска́хом Тебі́.» І рече́ к ни́ма Ісу́с: «Что я́ко іска́сте Мене́? Не ві́сте ли, я́ко в тіх, я́же Отця́ Моєго́, досто́їть би́ти Мі?» Ти же, Пречи́стая, соблюда́ла єси́ глаго́ли сія́ в се́рдці Своє́м, вопію́щи Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Усли́шала єси́, Ма́ти Бо́жия, я́ко Ісу́с прохожда́ше всю Галиле́ю, уча́ на со́нмищих, пропові́дуя Єва́нгеліє Ца́рствія і ісціля́я всяк неду́г і вся́кую я́зю в лю́діх. І ізи́де слух о Нем по всей страні́, і приведо́ша к Нему́ вся боля́щия разли́чними неду́ги і страстьми́, одержи́мия бі́си і разсла́бленния, і ісціли́ їх. Ти же, Ма́ти Бо́жия, ві́дущи проро́чество, скорб'я́щи се́рдцем, познава́ла єси́, я́ко вско́рі при́йдеть час, єгда́ Син Твой принесе́ть Себі́ в же́ртву за гріхи́ ми́ра. Ті́мже ублажа́єм Тя, многоско́рбная Ма́ти Бо́жия, вопію́ще:","Ра́дуйся, Си́на Своєго́ на служе́ніє наро́ду іуде́йському отда́вшая;","ра́дуйся, ско́рбная се́рдцем, но поко́рная во́лі Бо́жієй.","Ра́дуйся, мир от пото́па гріхо́внаго спа́сшая;","ра́дуйся, главу́ дре́вняго змі́я сте́ршая.","Ра́дуйся, Себі́ в же́ртву Бо́гу прине́сшая;","ра́дуйся, Госпо́дь с Тобо́ю, Благослове́нная.","Ра́дуйся, многоско́рбная Ма́ти Бо́жия, печа́ль на́шу в ра́дость претворя́ющая і сердця́ злих челові́к ум'ягча́ющая."]},{"h":"Кондак 5","ps":["Ца́рствіє Бо́жиє на землі́ пропові́дуя, облича́ше Ісу́с го́рдость фарисе́єв, мне́вших себі́ пра́ведники би́ти. Ті́мже сли́шаще при́тчі Єго́, разумі́ша, я́ко о них глаго́леть, і іска́ша взя́ти Єго́, но убоя́шася наро́да, поне́же я́ко проро́ка Єго́ імі́яху; сія́ вся ве́дающи, скорб'я́щи Богоро́диця о Си́ні Своє́м возлю́бленнім, страда́ше, да не убію́ть Єго́, оба́че вопію́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше ні́ції от іуде́й воскреше́ніє Ла́заря, ідо́ша к фарисе́єм і реко́ша їм, я́же сотвори́ Ісу́с; і рече́ їм Кая́фа, архієре́й сий лі́ту тому́: «У́не єсть нам, да єди́н челові́к у́мреть за лю́ди, а не весь наро́д поги́бнеть». І от сего́ дне совіща́ша, да убію́ть Єго́. Ми же вопіє́м Ті, Пречи́стая:","Ра́дуйся, Спаси́теля ми́ра ро́ждшая;","ра́дуйся, спасе́нія на́шего глави́зно.","Ра́дуйся, от рожде́нія в Ма́тер Спа́су на́шему предизбра́нная;","ра́дуйся, Ма́ти Бо́жия, обрече́нная на страда́ніє.","Ра́дуйся, Благослове́нная, Цари́ця Небе́сная соде́лавшаяся;","ра́дуйся, ви́ну за ни моля́щаяся.","Ра́дуйся, многоско́рбная Ма́ти Бо́жия, печа́ль на́шу в ра́дость претворя́ющая і сердця́ злих челові́к ум'ягча́ющая."]},{"h":"Кондак 6","ps":["Пре́жде пропові́дник сло́ва Бо́жия, посліди́ же преда́тель, Іу́да Іскаріо́тський, єди́н от обоюна́десяте апо́столов, і́де ко архієре́ом, преда́ти хотя́ Учи́теля своєго́; они́ же, сли́шавше, обра́довашася і обіща́ша єму́ сре́бренники да́ти. Ти же, Богома́ти, скорб'я́щи о Си́ні Своє́м возлю́бленнім, вопія́ла єси́ го́рці Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ла єсть послі́дняя ве́черя ученико́м Христо́вим, на не́йже Учи́тель уми́ но́зі їм, о́браз смире́нія показу́я, і рече́ їм: «Єди́н от вас преда́сть М'я, яди́й со Мно́ю». Ми же, го́рю Ма́тері Бо́жієй сострада́юще, воспіва́єм Єй:","Ра́дуйся, Ма́ти Бо́жия, му́кою серде́чною істомле́нная;","ра́дуйся, вся претерпі́вшая в юдо́лі сей многоско́рбней.","Ра́дуйся, в моли́тві успокоє́ніє находи́вшая;","ра́дуйся, всіх скорб'я́щих Ра́досте.","Ра́дуйся, утоле́ніє на́ших печа́лей;","ра́дуйся, із ти́ни гріхо́вния нас спаса́ющая.","Ра́дуйся, многоско́рбная Ма́ти Бо́жия, печа́ль на́шу в ра́дость претворя́ющая і сердця́ злих челові́к ум'ягча́ющая."]},{"h":"Кондак 7","ps":["Хотя́й яви́ти любо́в Свою́ к ро́ду челові́чеському Госпо́дь наш Ісу́с Христо́с на Та́йній ве́чері, благослови́в і преломи́в хліб, даде́ Свої́м ученико́м і апо́столом, рек: «Приймі́те, яді́те, сіє́ єсть ті́ло Моє́» і, приє́м ча́шу і хвалу́ возда́в, даде́ їм, глаго́ля: «Сія́ єсть кров Моя́ Но́ваго Заві́та, я́же за мно́гія ізлива́ємая во оставле́ніє гріхо́в». Благодаря́ще Ми́лостиваго Бо́га за милосе́рдіє Єго́ к нам неізрече́нноє, поє́м Єму́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє зна́меніє ми́лости Своєя́ яви́ Госпо́дь ученико́м Свої́м, обіща́я їм посла́ти іна́го Уті́шителя — Ду́ха і́стини, І́же от Отця́ ісхо́дить, да свиді́тельствуєть о Нем. Тебі́ же, Ма́тері Бо́жієй, па́ки освяще́нній Ду́хом Святи́м в день П'ятьдеся́тници, вопіє́м си́це:","Ра́дуйся, Ду́ха Свята́го обита́лище;","ра́дуйся, черто́же всесвяти́й.","Ра́дуйся, простра́нноє селе́ніє Бо́га Сло́ва;","ра́дуйся, Би́сер Боже́ственний проізве́дшая.","Ра́дуйся, рождество́м Твої́м ра́йськія две́рі нам отверза́ющая;","ра́дуйся, зна́меніє ми́лости Бо́жієй нам Собо́ю яви́вшая.","Ра́дуйся, многоско́рбная Ма́ти Бо́жия, печа́ль на́шу в ра́дость претворя́ющая і сердця́ злих челові́к ум'ягча́ющая."]},{"h":"Кондак 8","ps":["Стра́нно і приско́рбно нам сли́шати, я́ко лобза́нієм предаде́ Учи́теля своєго́ і Го́спода Іу́да Іскаріо́тський. Спи́ра же і ти́сящник і слуги́ архієре́йстії взя́ша Ісу́са і связа́ша Єго́, і ведо́ша к первосвяще́ннику А́нні пе́рвіє, посе́м же ко Кая́фі архієре́ові. Ма́тер же Бо́жия, сме́ртнаго сові́та на Си́на Своєго́ возлю́бленнаго ожида́ющи, вопія́ше Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Всі іуде́ї ведо́ша Ісу́са от Кая́фи в прето́р к Пила́ту, глаго́люще Єго́ злоді́я би́ти. Пила́ть же вопроси́ Єго́ і глаго́ла їм, я́ко ні єди́ния вини́ обрі́те в Нем. Ми же Ма́тері Бо́жієй, поноше́нія Си́на Своєго́ ви́дящей, уми́льно вопіє́м:","Ра́дуйся, се́рдце го́рем істерза́нноє імі́вшая;","ра́дуйся, сле́зи о Си́ні Своє́м пролива́вшая.","Ра́дуйся, Ча́до Своє́ люби́моє на суди́лище преда́нноє зре́вшая;","ра́дуйся, вся претерпі́вшая без ро́пота, я́ко раба́ Госпо́дня.","Ра́дуйся, стеня́щая і рида́ющая;","ра́дуйся, Цари́це небесе́ і землі́, приє́млющая моли́тви раб Свої́х.","Ра́дуйся, многоско́рбная Ма́ти Бо́жия, печа́ль на́шу в ра́дость претворя́ющая і сердця́ злих челові́к ум'ягча́ющая."]},{"h":"Кондак 9","ps":["Всі ро́ди блажа́ть Тя, честні́йшую Херуви́м і сла́внійшую без сравне́нія Серафи́м, Влади́чицю і Ма́тер Ізба́вителя на́шего, рождество́м Свої́м ра́дость всему́ ми́ру прине́сшую, посліди́ же скорб ве́лію імі́вшую, ви́дящи Си́на Своєго́ возлю́бленнаго на поруга́ніє, біє́ніє і смерть пре́даннаго. Ми же умиле́нноє пі́ніє прино́сим Ті, Пречи́стая, вопію́ще Всемогу́щему Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї многовіща́ннії не возмо́гуть ізрещи́ всіх страда́ній, Тобо́ю пренесе́нних, Спа́се наш, єгда́ во́їни, спле́тше віне́ць із те́рнія і возложи́вше на главу́ Твою́, і в ри́зу багря́ну обле́кше Тя, глаго́лаху: «Ра́дуйся, Царю́ Іуде́йський», і бія́ху Тя по лани́тома. Ми же, Ма́ти Бо́жия, страда́нія Твоя́ познава́юще, вопіє́м Ті:","Ра́дуйся, Си́на Своєго́ біє́ннаго зре́вшая;","ра́дуйся, багряни́цею і терно́вим вінце́м оде́яннаго зре́вшая.","Ра́дуйся, Єго́же мле́ком Свої́м пита́ла єси́, терза́ємаго ви́дівшая;","ра́дуйся, страда́нієм Єго́ спострада́вшая.","Ра́дуйся, всі́ми ученики́ Єго́ оста́вленнаго ви́дівшая;","ра́дуйся, непра́ведними судія́ми Єго́ осужде́ннаго зре́вшая.","Ра́дуйся, многоско́рбная Ма́ти Бо́жия, печа́ль на́шу в ра́дость претворя́ющая і сердця́ злих челові́к ум'ягча́ющая."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ Ісу́са, рече́ Пила́ть іуде́єм: «Єсть же оби́чай вам, да єди́наго вам отпущу́ на Па́сху. Хо́щете ли у́бо, да отпущу́ вам Царя́ Іуде́йська?» Но всі возопи́ша, глаго́люще: «Не Сего́, но Вара́вву». Прославля́юще милосе́рдіє Отця́ Небе́снаго, І́же та́ко возлюби́ мир, я́ко Си́на Своєго́ Єдиноро́днаго отда́л єсть на кре́стную смерть, да іскупи́ть ни от ві́чния сме́рти, вопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ і огражде́ніє бу́ди нам, Влади́чице, ізнемога́ющим от ско́рби і болі́зні. Ти бо і Сама́ страда́ла єси́, сли́шащи іуде́єв, вопію́щих: «Распни́, распни́ Єго́!» Ни́ні же усли́ши нас, вопію́щих Ті:","Ра́дуйся, Ма́ти милосе́рдія, от'є́млющая вся́кую слезу́ от лю́ті стра́ждущих;","ра́дуйся, слезу́ умиле́нія нам подаю́щая.","Ра́дуйся, погиба́ющих грі́шников спаса́ющая;","ра́дуйся, предста́тельство христия́н непости́дноє.","Ра́дуйся, от страсте́й нас ізбавля́ющая;","ра́дуйся, се́рдцю сокруше́нному отра́ду подаю́щая.","Ра́дуйся, многоско́рбная Ма́ти Бо́жия, печа́ль на́шу в ра́дость претворя́ющая і сердця́ злих челові́к ум'ягча́ющая."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє Спаси́телю ми́ра прино́сим, на во́льноє страда́ніє ше́дшему і крест Свой не́сшему. Во́їни же, прише́дше на Голго́фу, проп'я́ша Єго́. Стоя́ху при кресті́ Ісу́сові Ма́ти Єго́, і сестра́ Ма́тере Єго́ — Марі́я Клео́пова, і Марі́я Магдали́на. Ісу́с же, ви́дів Ма́тер і ученика́ стоя́ща, єго́же любля́ше, глаго́ла Ма́тері Своє́й: «Же́но, се син Твой»; пото́м глаго́ла ученику́: «Се Ма́ти твоя́». І от того́ ча́са поя́ть Ю учени́к во своя́си. Ти же, Ма́ти Бо́жия, обезче́щенна ви́дящи на кресті́ Си́на і Го́спода, терза́лася єси́, вопію́щи Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Си́не Мой і Бо́же Предві́чний, Тво́рче всіх тва́рей, Го́споди! Ка́ко те́рпиши на кресті́ страсть, — Чи́стая Ді́ва, пла́чущи, глаго́лаше. — О стра́шнім Твоє́м Рождестві́, Си́не Мой, па́че всіх ма́терей возвели́чена бих, но уви́ Мні: ни́ні Тя ви́дящи, распаля́юся утро́бою». Ми же, сле́зи пролива́юще і Тебі́ вне́млюще, вопіє́м Ті:","Ра́дуйся, ра́дости і весе́лія лише́нная;","ра́дуйся, во́льная страда́нія Си́на Твоєго́ на кресті́ ви́дівшая.","Ра́дуйся, Ча́до Своє́ возлю́бленноє уязвле́нним зре́вшая;","ра́дуйся, А́гнця, на закла́ніє ведо́маго, Ма́ти.","Ра́дуйся, Ізба́вителя язв душе́вних і тіле́сних я́звами покри́таго ви́дівшая;","ра́дуйся, Си́на Своєго́ воскре́сшаго із ме́ртвих зре́вшая.","Ра́дуйся, многоско́рбная Ма́ти Бо́жия, печа́ль на́шу в ра́дость претворя́ющая і сердця́ злих челові́к ум'ягча́ющая."]},{"h":"Кондак 12","ps":["Благода́ть пода́ждь нам, Спа́се Всеми́лостивий, на Кресті́ дух Свой іспусти́вий і согріше́ній на́ших рукописа́ніє растерза́вий. «Се, сві́те Мой сла́дкий, наде́ждо і животе́ Мой благи́й, Бо́же Мой, уга́сл єси́ на Кресті́», — Ді́ва, стеня́щи, глаго́лаше. Потщи́ся, Іо́сифе, к Пила́ту приступи́ти і проси́ єго́ сня́ти с дре́ва Учи́теля своєго́ уязвле́ннаго: «Даждь мі Сего́ стра́ннаго, І́же не і́мать гді глави́ преклони́ти». Богома́тер же, ви́дівши Си́на Своєго́ безсла́вна, на́га на дре́ві, возопи́: «Уви́ Мні, Ча́до Моє́, уви́ Мні, сві́те Мой, ду́шу про́йде Мні ору́жіє по рече́нію пра́веднаго ста́рця Симео́на». Ми же, Пречи́стій Ді́ві состра́ждуще, вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще милосе́рдіє Твоє́, Человіколю́бче, покланя́ємся бога́тству ми́лости Твоєя́, Влади́ко. «Созда́ніє Твоє́ спасти́ хотя́, смерть под'я́л єси́, — рече́ Пречи́стая, — но Воскресе́нієм Твої́м, Спа́се, поми́луй всіх нас». Ми же Богоро́дице, о нас моля́щейся, вопіє́м:","Ра́дуйся, ме́ртваго зря́щая, бездиха́нна Преблага́го Го́спода;","ра́дуйся, лобза́вшая ті́ло Си́на Твоєго́ возлю́бленнаго.","Ра́дуйся, Сві́та Своєго́ сла́дкаго на́га і уязвле́ннаго Мертвеця́ зре́вшая;","ра́дуйся, Си́на Своєго́ гро́бу преда́вшая.","Ра́дуйся, плащани́цею но́вою ті́ло Єго́ обви́вшая;","ра́дуйся, Воскресе́ніє Єго́ ви́дівшая.","Ра́дуйся, многоско́рбная Ма́ти Бо́жия, печа́ль на́шу в ра́дость претворя́ющая і сердця́ злих челові́к ум'ягча́ющая."]},{"h":"Кондак 13","ps":["О Всепі́тая Ма́ти, ізнемога́ющая от ско́рби у креста́ Си́на Твоєго́ і Бо́га! Внемли́ воздиха́нієм і слеза́м на́шим, ум'ягчи́ зла́я сердца́, востаю́щая на нас, ізба́ви от ско́рби, болі́зней і ві́чния сме́рти всіх упова́ющих на неізрече́нноє Твоє́ милосе́рдіє і вопію́щих Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел возвісти́ па́стирем вифлеє́мстим о Рождестві́ Спаси́теля ми́ра, і с ним мно́жество во́єв небе́сних восхваля́ху Бо́га, пою́ще: «Сла́ва во ви́шніх Бо́гу, і на землі́ мир, в челові́ціх благоволе́ніє». Ти же, Ма́ти Бо́жия, не імі́вши гді главу́ преклони́ти, зане́ не бі мі́ста во оби́теліх, родила́ Си́на Своєго́ Пе́рвенця во верте́пі, і пови́ла Єго́ пелена́ми, і положи́ла Єго́ в я́сліх. Ті́мже, скорб се́рдця Твоєго́ ві́дуще, вопіє́м Ті:","Ра́дуйся, диха́нієм Свої́м Си́на Своєго́ возлю́бленнаго согре́вшая;","ра́дуйся, Преві́чнаго Младе́нця пелена́ми пови́вшая.","Ра́дуйся, Носи́теля вселе́нния мле́ком Свої́м пита́вшая;","ра́дуйся, верте́п в не́бо обрати́вшая.","Ра́дуйся, престо́л херуви́мський соде́лавшаяся;","ра́дуйся, в рождестві́ і по рождестві́ Ді́ва преби́вшая.","Ра́дуйся, многоско́рбная Ма́ти Бо́жия, печа́ль на́шу в ра́дость претворя́ющая і сердця́ злих челові́к ум'ягча́ющая."]},{"h":"Кондак 1","ps":["Ізбра́нной Ді́ві Марі́ї, преви́сшей всіх дще́рей землі́, Ма́тері Си́на Бо́жия, Є́юже дає́ться спасе́ніє ми́ра, со умиле́нієм взива́єм: воззри́ на многоско́рбноє житіє́ на́ше, воспом'яни́ ско́рби і болі́зні, я́же претерпі́ла єси́, я́ко на́ша земноро́дная, і сотвори́ с на́ми по милосе́рдію Твоєму́, да зове́м Ті:","Ра́дуйся, многоско́рбная Ма́ти Бо́жия, печа́ль на́шу в ра́дость претворя́ющая і сердця́ злих челові́к ум'ягча́ющая."]},{"h":"Молитва перша","ps":["О многоско́рбная Ма́ти Бо́жия, преви́шшая всіх дще́рей землі́ по чистоті́ Своє́й і по мно́жеству страда́ній, Тобо́ю на землі́ пренесе́нних! Прийми́ многоболі́зненния воздиха́нія на́ша і сохрани́ нас под кро́вом Твоєя́ ми́лости. Іна́го бо прибі́жища і те́плаго предста́тельства, ра́зві Тебе́, не ві́ми, но, я́ко дерзнове́ніє іму́щи ко І́же от Тебе́ Рожде́нному, помози́ і спаси́ ни моли́твами Свої́ми, да непреткнове́нно дости́гнем Ца́рствія Небе́снаго, іді́же со всі́ми святи́ми бу́дем воспіва́ти хвалу́ в Тро́йці Єди́ному Бо́гу, всегда́, ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О кто не ублажи́ть Тя, Ді́во Благода́тная, кто не воспоє́ть Твоє́ милосе́рдіє к ро́ду челові́чеському. Тебі́ мо́лимся, Теб'я́ про́сим: не оста́ви нас, во злі погиба́ющих, раствори́ любо́вію сердця́ на́ша і ко врага́м на́шим пошли́ стрілу́ Свою́, да уязвля́єть сердця́ на́ша ми́ром ко гоня́щим нас. А́ще мир нас ненави́дить — Ти простри́ любо́в Свою́ к нам, а́ще мир нас го́нить — Ти прийми́ нас. Пода́ждь нам Благода́тную си́лу терпі́нія — без ро́пота перенести́ іспита́нія, в ми́рі сем бива́ємая. О Госпожі́! Ум'ягчи́ сердця́ злих челові́ков, восстаю́щих на нас, да не поги́бнуть сердця́ їх во злі, но умоли́, Благода́тная, Си́на Твоєго́ і Бо́га на́шего, да умири́ть сердця́ їх ми́ром, дия́вол же — оте́ць зло́би — да посрами́ться! Ми же, воспіва́юще милосе́рдіє Твоє́ к нам, злим, непотре́бним, воспоє́м Ті, о Пречу́дная Госпоже́ Ді́во Благода́тная: усли́ши нас в час сей, сокруше́нная сердца́ іму́щих, огради́ нас ми́ром і любо́вію друг ко дру́гу і ко враго́м на́шим, іскорени́ от нас вся́кую зло́бу і вражду́, да воспоє́м Тебі́ і Си́ну Твоєму́, Го́споду Ісу́су Христу́ на́шему: Аллилу́я! Аллилу́я! Аллилу́я!"]},{"h":"Тропар, глас 5","ps":["Ум'ягчи́ на́ша зла́я сердца́, Богоро́дице, / і на́пасти ненави́дящих нас угаси́ / і вся́кую тісноту́ душі́ на́шея разріши́, / на Твой бо святи́й о́браз взира́юще, / Твої́м сострада́нієм і милосе́рдованієм о нас умиля́ємся / і ра́ни Твоя́ лобиза́єм, / стріл же на́ших, Тя терза́ющих, ужаса́ємся. / Не даждь нам, Ма́ти Благосе́рдная, / в жестосе́рдії на́шем і от жестосе́рдія бли́жніх поги́бнути, // Ти бо єси́ воі́стину злих серде́ць ум'ягче́ніє."]},{"h":"Кондак, глас 2","ps":["Благода́тію Твоє́ю, Влади́чице, / ум'ягчи́ сердця́ злоді́єв, / низпосли́ благоді́телей, / соблюда́ющи їх от вся́каго зла, / благомоля́щимся Ті усе́рдно // пред честни́ми іко́нами Твої́ми."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтим о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Виховання»","e":"Akathist to the Theotokos before her icon “The Upbringing”","secs":[{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді і усе́рдной Воспита́тельнице ро́да христия́нськаго, я́ко ізба́вльшеся от злих, благода́рственная воспису́єм Ті раби́ Твої́, Богоро́дице, но я́ко іму́щая держа́ву непобіди́мую, от вся́ких бід на́ших чад свободи́, да зове́м Ті:","Ра́дуйся, блага́я Воспита́тельнице, воспита́нная во Свята́я святи́х."]},{"h":"Ікос 1","ps":["А́нгела с Небесе́ посла́ти ча́дом на́шим ісхода́тайствуй, Пресвята́я, у Си́на Твоєго́ і Бо́га на́шего, я́коже і Тебі́ по́слан бисть Гавриї́л арха́нгел, і сподо́би ни взива́ти Тебі́ си́це:","Ра́дуйся, рожде́нієм Свої́м роди́телей обра́довавшая;","ра́дуйся, со слеза́ми мно́гими у Бо́га іспро́шенная.","Ра́дуйся, моли́тви і поста́ сві́тлоє прозябе́ніє;","ра́дуйся благочести́вия жи́зні кра́сний пло́де.","Ра́дуйся, от младе́нства свята́го послуша́нія іспо́лненная;","ра́дуйся благоче́стієм от сосця́ ма́тере напоє́нная.","Ра́дуйся, любве́ всесві́тлоє Жили́ще;","ра́дуйся, ми́лостей Госпо́дніх Сокро́вище.","Ра́дуйся, блага́я Воспита́тельнице, воспита́нная во Свята́я святи́х."]},{"h":"Кондак 2","ps":["Ви́дящи на́ше сле́зноє роди́тельськоє моле́ніє, умилосе́рдися, Влади́чице, о ча́діх на́ших, возьми́ їх под Свой честни́й і благосве́тлий покро́в, да воззову́ть во весели́ Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум ча́дом на́шим низпосли́, є́же ка́ко до́брі Ті послужи́ти, і напо́лни сердця́ їх прему́дростію небе́сною, подаю́щи єди́ну ю возлюби́ти, земно́є же презрі́ти, і не возбрани́ усто́м на́шим взива́ти такова́я:","Ра́дуйся, де́тство Своє́ при хра́мі прове́дшая;","ра́дуйся, во Свята́я святи́х возше́дшая.","Ра́дуйся, єди́ному Бо́гу посвяще́нная;","ра́дуйся, моли́вшаяся Єму́ день і нощ.","Ра́дуйся, чистоту́ і целому́дріє ізмла́да возлюби́вшая;","ра́дуйся, смире́ніє Своє́ всеусе́рдно охраня́вшая.","Ра́дуйся, моли́твою к Бо́гу при́сно пламене́вшая;","ра́дуйся, Похвало́ і Ра́досте роди́телей святи́х.","Ра́дуйся, блага́я Воспита́тельнице, воспита́нная во Свята́я святи́х."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго да осіни́ть ча́да на́ша Твоєго́ ра́ди неуси́пного предста́тельства за них пред Си́ном Твої́м, да позна́вше Твоє́ Ма́тернеє милосе́рдіє ко всім с ві́рою притека́ющим к Тебі́, воззову́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще от Бо́га чад на́ших, не хо́щем зрі́ти їх в геє́нні о́гненній пребива́ющих, но запи́санних в кни́зі живо́тній. Сего́ ра́ди, Пречи́стая Ді́во, приклони́ся ко гла́су моле́нія на́шего, взива́ющему Тебі́:","Ра́дуйся, Ма́ти Бо́га і Сло́ва;","ра́дуйся Свята́я святи́х бо́льшая.","Ра́дуйся, Воспита́тельнице Си́на Бо́жия;","ра́дуйся, Корми́лице Го́спода сил.","Ра́дуйся, я́ко ражда́єши Спаси́теля ми́ра;","ра́дуйся, я́ко расти́ши Ізба́вителя пліне́нним.","Ра́дуйся, я́ко но́сиши Наста́вника заблу́дшим;","ра́дуйся, я́ко Син Твой Госпо́дь.","Ра́дуйся, блага́я Воспита́тельнице, воспита́нная во Свята́я святи́х."]},{"h":"Кондак 4","ps":["Бу́рю ви́дяще собла́знов многоразли́чних, умно́жившихся, я́ко пе́сія му́хи і скни́пи, в преді́ліх на́ших, к Тебі́, Благода́тная, взива́єм о ча́діх свої́х, да ізбі́гнуть сих і вопію́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаще глас Твой, глаго́лющий Си́ну Твоєму́: Прийми́ вся́каго моля́щагося Тебі́ і призива́юща і́м'я Моє́ на по́мощ, - простира́єм ру́ці на́ша на моли́тві к Твоєму́ милосе́рдію, да во́зьмеши чад на́ших под покро́в Свой і іспо́лниши проше́нія на́ша такова́я:","Ра́дуйся, от уни́нія зла́го чад на́ших ізбавля́ющая;","ра́дуйся, от безу́мнаго весе́лія їх огражда́ющая.","Ра́дуйся, в несе́нії креста́ їх укріпля́ющая;","ра́дуйся, в по́двизіх благоче́стія їх утвержда́ющая.","Ра́дуйся, под покро́вом Твої́м ми́лостиво їх сохраня́ющая;","ра́дуйся, здра́віє душ і тіле́с їм подава́ющая.","Ра́дуйся, усе́рдная Наста́внице цілому́дрія;","ра́дуйся, ми́лостивая Взиска́тельнице заблу́дших.","Ра́дуйся, блага́я Воспита́тельнице, воспита́нная во Свята́я святи́х."]},{"h":"Кондак 5","ps":["Боготе́чная Звізда́ у́тренняя, Син Твой, Пресвята́я Ді́во, да возсія́єть сві́том невече́рнім в сердця́х чад на́ших, во є́же воззва́ти їм Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дящи на́ше прилі́жноє моле́ніє, не отврати́ лиця́ Твоєго́ от чад на́ших, а́ще і отвратя́ться Тебі́, і усли́ши глаго́ли уст на́ших, вопію́щих такова́я:","Ра́дуйся, я́ко науча́єши чад на́ших імі́ти ра́зум на до́броє;","ра́дуйся, на путі́ гріха́ їх запина́ющая.","Ра́дуйся, пра́во ше́ствовати їх наставля́ющая;","ра́дуйся, от лука́вства злих челові́к їх огражда́ющая.","Ра́дуйся, в злострада́нії їх укріпля́ющая;","ра́дуйся, благодари́ти Бо́га за вся науча́ющая.","Ра́дуйся, блага́я Хода́тайце при́сно о ча́діх на́ших к Си́ну Своєму́;","ра́дуйся, Спору́чнице їх пред Творцо́м і Бо́гом.","Ра́дуйся, блага́я Воспита́тельнице, воспита́нная во Свята́я святи́х."]},{"h":"Кондак 6","ps":["Пропові́дуєть весь мир христия́нський Твоє́ всегда́шнєє заступле́ніє о моля́щихся Тебі́. Си́це і ни́ні усли́ши многоболі́зненноє сіє́ роди́тельськоє моле́ніє о ча́діх на́ших, во є́же зва́ти їм Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Да возсія́єть луча́ благода́ті в душа́х чад на́ших, і, просвіще́ніі Тобо́ю, у́зрять путь, веду́щий в живо́т ві́чний, і послі́дують їм, сохраня́ємі под Твої́м всемогу́щим покро́вом. Сего́ ра́ди усли́ши ни, зову́щия Ті такова́я:","Ра́дуйся, роди́телей на любо́в бла́гу к ча́дом свої́м подвиза́ющая;","ра́дуйся, сердца́ чад, во є́же роди́телей свої́х чти́ти, умиля́ющая.","Ра́дуйся, прося́щим подаю́щая ра́зум;","ра́дуйся, ві́рних озаря́ющая сми́сли.","Ра́дуйся, всіх скорб'я́щих Ра́досте;","ра́дуйся, Ум'ягче́ніє злих серде́ць.","Ра́дуйся, Отра́до і Утіше́ніє;","ра́дуйся, Прибавле́ніє ума́.","Ра́дуйся, блага́я Воспита́тельнице, воспита́нная во Свята́я святи́х."]},{"h":"Кондак 7","ps":["Хотя́ще ча́дом на́шим ві́чнаго спасе́нія, со слеза́ми предстої́м пред честно́ю Твоє́ю іко́нною, Влади́чице, да не пре́зриши моле́нія на́шего, зову́ще Си́ну Твоєму́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую покажи́ ми́лость на ча́діх на́ших, Влади́чице, і неізследи́мими судьба́ми Си́на Твоєго́ привлеци́ їх под Свой благода́тний покро́в, да усе́рдно зове́м Ті:","Ра́дуйся, Воспита́ніє чад на́ших, во є́же огражде́нним їм би́ти му́ки ві́чния;","ра́дуйся, Воспита́ніє чад на́ших, во є́же наслі́довати їм блаже́нство непрестаю́щеє.","Ра́дуйся, Пробужде́ніє со́вісти чад на́ших на покая́ніє;","ра́дуйся, пита́ющая їх плода́ми добротолю́бія.","Ра́дуйся, премилосе́рдая Уті́шительнице всіх скорб'я́щих і обремене́нних;","ра́дуйся, неусипа́ющая Наста́внице всіх заблу́дших і осліпле́нних.","Ра́дуйся, Судії́ пра́веднаго умоле́ніє;","ра́дуйся, мно́гих согріше́ній проще́ніє.","Ра́дуйся, блага́я Воспита́тельнице, воспита́нная во Свята́я святи́х."]},{"h":"Кондак 8","ps":["Стра́нствующе в юдо́лі сей многоско́рбней по мо́рю многом'яте́жному страсте́й, ча́да на́ша гді обря́щуть тве́рдоє приста́нище, а́ще не в Тебі́, Пречи́стая? Спутеше́ствуй же їм і наста́ви їх на путь і́стинний, да зову́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Всім єси́ Ма́ти ми́лующая, Пречи́стая Ді́во, я́коже Христо́с Спаси́тель рече́ Тебі́, у креста́ Єго́ предстоя́щей: Се, син Твой, - указу́я на і́збраннаго от челові́к. Сего́ ра́ди вруча́єм ча́да на́ша в ру́ці Твої́ і во смире́нії зове́м Ті:","Ра́дуйся, чад на́ших благосе́рдая Путеводи́тельнице;","ра́дуйся, те́рнія гріхо́вних страсте́й милосе́рдая Іскорени́тельнице.","Ра́дуйся, отра́ду в пусти́ні гріха́ подаю́щая;","ра́дуйся, в мину́ту ско́рби утіша́ющая.","Ра́дуйся, в зе́млю обітова́нія путево́дствующая;","ра́дуйся, на воді́ упокоє́нія веселя́щая.","Ра́дуйся, соверше́нний Ра́зуме наста́вников і дітоводи́телей;","ра́дуйся, Благослове́ніє домо́в і семе́йств благочести́вих.","Ра́дуйся, блага́я Воспита́тельнице, воспита́нная во Свята́я святи́х."]},{"h":"Кондак 9","ps":["Вся́каго бла́га іспо́лни сердця́ і ду́ші чад на́ших, отгоня́ющи от них ду́ха злосмра́днаго безбо́жия, нече́стія і блудоде́йства, госпо́дствующа в ми́рі сем. Сохрани́ рабо́в Твої́х в чистоті́ і цілому́дрії, да взива́ють во умиле́нії Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́й суєму́дренних, лжу́щих на Твоє́ всемо́щноє заступле́ніє, отжени́, Ма́ти Бо́жия, от чад на́ших, да не попо́лзнуться умо́м в душетлі́нная уче́нія і не обратя́ться се́рдцем в по́хоті безмі́стния, но при́зри на ни, ві́рно вопію́щия:","Ра́дуйся, до́брим нра́вом чад на́ших науча́ющая;","ра́дуйся, от злих на́виков їх ізбавля́ющая.","Ра́дуйся, му́дрих наста́вников Твої́м рабо́м посила́ющая;","ра́дуйся, от худи́х соо́бществ їх отвраща́ющая.","Ра́дуйся, благо́му уче́нію внима́ти призива́ющая;","ра́дуйся, сує́тниє ба́сни презира́ти помога́ющая.","Ра́дуйся, Бо́жиє ко грі́шним благоволе́ніє;","ра́дуйся, ка́ющихся пред Го́сподем крі́пкоє заступле́ніє.","Ра́дуйся, блага́я Воспита́тельнице, воспита́нная во Свята́я святи́х."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ мир, Христо́с Бог призва́ не пра́ведники, но грі́шники на покая́ніє. Сего́ ра́ди моли́ся Си́ну Твоєму́ о ча́діх на́ших, а́ще і уйду́ть в страну́ дале́че, оба́че, взиска́ннії Твої́м Ма́тернім заступле́нієм, возвратя́ться в сокруше́нії сердця́ к Отцю́ Небе́сному і воззову́ть Єму́: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіно́ю несокруши́мою ста́ни, Небе́сная Цари́це, ча́дом на́шим, да Твої́м предста́тельством ізбі́гнуть змі́єва приноше́нія, кра́снаго в снідь, посліди́ же смертоно́снаго, і возмо́гуть чи́стим се́рдцем пі́ти Тебі́ такова́я:","Ра́дуйся, ізбавля́ющая чад на́ших от ядови́таго зе́лія;","ра́дуйся, спаса́ющая їх от душепа́губнаго питія́.","Ра́дуйся, от блудоде́йства їх сохраня́ющая;","ра́дуйся, цілому́дрію їх науча́ющая.","Ра́дуйся, потребле́ніє вся́каго обольще́нія;","ра́дуйся, ізбавле́ніє вся́каго смуще́нія.","Ра́дуйся, трезві́нія побо́рнице;","ра́дуйся, му́дрости хода́тайце.","Ра́дуйся, блага́я Воспита́тельнице, воспита́нная во Свята́я святи́х."]},{"h":"Кондак 11","ps":["Пі́ти Твоє́ необори́моє заступле́ніє ви́ну сподо́би чад на́ших, да обря́щуть Тебі́ крі́пкую Помо́щницю, і Твоє́ю благода́тію отве́рзуть уста́ свої́ воспіва́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоприє́мную свіщу́ житіє́ чад на́ших соді́лай, да при́сно горя́ть любо́вію к Тебі́ і Си́ну Твоєму́, і не пре́зри ни, зову́щия Ті:","Ра́дуйся, дим собла́знов разгоня́ющая;","ра́дуйся, мглу страсте́й просвіща́ющая.","Ра́дуйся, зрі́ніє храни́ти науча́ющая;","ра́дуйся, блюсти́ чу́вствованія вразумля́ющая.","Ра́дуйся, щедро́т неізрече́нних Ма́ти;","ра́дуйся, побужда́ющая чад на́ших в благогові́нії Тебі́ предстоя́ти.","Ра́дуйся, Утіше́ніє їм в ско́рбі живоно́сноє;","ра́дуйся, от набе́га лука́вих Прибі́жище непрело́жноє.","Ра́дуйся, блага́я Воспита́тельнице, воспита́нная во Свята́я святи́х."]},{"h":"Кондак 12","ps":["Благода́тію неізрече́нною Ду́ха Свята́го напита́й сердца́ чад на́ших, є́же возлюби́ти то́кмо Си́на Твоєго́ і Бо́га і Тебі́, Преблагу́ю Засту́пницю, да, подви́гшеся Тобо́ю, зову́ть Царю́ вся́чеських: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твоє́ милосе́рдіє, і́мже ми́луєши і пита́єши чад на́ших, мо́лимся: не преста́й проси́ти о них Си́на Твоєго́, я́ко вся Тебі́ возмо́жна суть, і усли́ши мольби́ на́ша такови́я:","Ра́дуйся, от купі́лі Свята́го Креще́нія чад на́ших Восприє́мнице;","ра́дуйся, к сві́ту і́стини їх Путеводи́тельнице.","Ра́дуйся, ро́су благода́ті Твоєя́ їм подаю́щая;","ра́дуйся, мле́ком і́стини їх пита́ющая.","Ра́дуйся, я́ко твори́ши чад на́ших земни́я а́нгели;","ра́дуйся, я́ко претворя́єши їх в небе́сния челові́ки.","Ра́дуйся, наслі́дники Ца́рствія Небе́снаго їх показу́ющая;","ра́дуйся, в Оби́теліх Небе́сних їх водворя́ющая.","Ра́дуйся, блага́я Воспита́тельнице, воспита́нная во Свята́я святи́х."]},{"h":"Кондак 13","ps":["О Всепі́тая Ма́ти Ісу́са Сладча́йшаго! Прийми́ ма́лоє сіє́ моле́ніє о ча́діх на́ших во воню́ благоуха́нія духо́внаго і возьми́ їх под Твой милосе́рдний покро́в. Єще́ же да́руй їм ми́слити, глаго́лати і твори́ти то́чію Тебі́ і Си́ну Твоєму́ уго́дная і посли́ їм в жи́зні сей привре́менній вся поле́зная ко спасе́нію душ їх, да воспіва́ють Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгела с Небесе́ посла́ти ча́дом на́шим ісхода́тайствуй, Пресвята́я, у Си́на Твоєго́ і Бо́га на́шего, я́коже і Тебі́ по́слан бисть Гавриї́л арха́нгел, і сподо́би ни взива́ти Тебі́ си́це:","Ра́дуйся, рожде́нієм Свої́м роди́телей обра́довавшая;","ра́дуйся, со слеза́ми мно́гими у Бо́га іспро́шенная.","Ра́дуйся, моли́тви і поста́ сві́тлоє прозябе́ніє;","ра́дуйся благочести́вия жи́зні кра́сний пло́де.","Ра́дуйся, от младе́нства свята́го послуша́нія іспо́лненная;","ра́дуйся благоче́стієм от сосця́ ма́тере напоє́нная.","Ра́дуйся, любве́ всесві́тлоє Жили́ще;","ра́дуйся, ми́лостей Госпо́дніх Сокро́вище.","Ра́дуйся, блага́я Воспита́тельнице, воспита́нная во Свята́я святи́х."]},{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді і усе́рдной Воспита́тельнице ро́да христия́нськаго, я́ко ізба́вльшеся от злих, благода́рственная воспису́єм Ті раби́ Твої́, Богоро́дице, но я́ко іму́щая держа́ву непобіди́мую, от вся́ких бід на́ших чад свободи́, да зове́м Ті:","Ра́дуйся, блага́я Воспита́тельнице, воспита́нная во Свята́я святи́х."]},{"h":"Молитва до Господа нашого Ісуса Христа","ps":["Го́споди Ісу́се Христе́, Си́не Бо́жий, моли́тв ра́ди Пречи́стия Твоєя́ Ма́тере усли́ши нас, недосто́йних раб Твої́х, к Тебі́ прилі́жно притека́ющих. Го́споди, в ми́лостивій вла́сті Твоє́й ча́да на́ша, раби́ Твої́ (імена). Поми́луй і спаси́ їх і́мене Твоєго́ ра́ди, прости́ їм вся согріше́нія во́льная і нево́льная, соверше́нная і́ми пред Тобо́ю, Го́споди. Наста́ви їх на путь і́стинний, ра́зум їх просвіти́ сві́том Твої́м, се́рдце согрі́й любо́вію Твоє́ю. Го́споди, благослови́ їх в до́мі, в уче́нії, в путі́ і на вся́ком мі́сті Твоєго́ влади́чества. Го́споди, сохрани́ їх под кро́вом Твої́м святи́м от летя́щия стрі́ли, от огня́, меча́, от смертоно́сния я́зви і от напра́сния сме́рті. Го́споди, огради́ їх от всіх ви́димих і неви́димих враго́в, ісціли́ їх от вся́кия болі́зні, очи́сти їх от вся́кия скве́рни і облегчи́ їх душе́вния страда́нія. Го́споди, да́руй їм благода́ть Ду́ха Твоєго́ Свята́го на мно́гая лі́та жи́зні, здра́вія, цілому́дрія і благоче́стія. Го́споди, умно́ж і укріпи́ їх душе́вниє і тіле́сниє си́ли, Тобо́ю дарова́нниє їм. Да́руй Твоє́ благослове́ніє ча́дом на́шим на благочести́вую і, а́ще уго́дно Тебі́, семе́йную жизнь. Го́споди, да́руй нам, недосто́йним і грі́шним рабо́м Твої́м (імена), благослове́ніє на воспита́ніє чад на́ших і сподо́би всіх ку́пно дости́гнути ві́чнаго Ца́рствія і та́мо просла́вити пречестно́є і великолі́поє і́м'я Твоє́, со Отце́м і Святи́м Ду́хом. Амі́нь."]},{"h":"Молитва до Матері Божої","ps":["О Пресвята́я Влади́чице Ді́во Богоро́дице, премилосе́рдая Ма́ти всіх челові́к, спаси́ і сохрани́ под кро́вом Твої́м чад на́ших (імена), всіх отроко́в, отрокови́ць, младе́нцев і во чре́ві ма́тере носи́мих. Покри́й їх ри́зою Твоє́ю, соблюди́ їх во стра́сі Бо́жиєм і послуша́нії роди́телем, умоли́ Го́спода на́шего і Си́на Твоєго́, да да́руєть їм вся поле́зная к душе́вному спасе́нію. Вруча́єм їх Твоєму́ Матери́нському смотре́нію, я́ко Ти єси́ Боже́ственний покро́в рабо́м Твої́м. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Воспита́вшейся во хра́мі во свята́я святи́х, / оді́янній ві́рою і прему́дростію і безмі́рним ді́вством, / Архистрати́г Гавриї́л принесе́ с небесе́ цілова́ніє / і є́же ра́дуйся, ра́дуйся Благослове́нная, // ра́дуйся, Препросла́вленная, Госпо́дь с Тобо́ю."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтем о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Взискання погибших»","e":"Akathist to the Theotokos before her icon “Seeker of the Lost”","secs":[{"h":"Кондак 1","ps":["Возбра́нной Воєво́ді, Цари́це небесе́ і землі́, дарова́вшей нам пречу́дную іко́ну Взиску́ющую, благода́рственноє прино́сим пі́ніє. Ти же, я́ко благосе́рдая Ма́ти, не отри́ни на́шего сего́ моле́нія, но благоволи́ прия́ти є, і сподо́би вопи́ти Тебі́ та́ко:","Ра́дуйся, Благода́тная Богоро́дице Ді́во, всеблага́я Ма́ти, взиску́ющая погиба́ющих."]},{"h":"Ікос 1","ps":["А́нгельський усли́ша глас свята́я А́нна, віща́яй: зачне́ши і роди́ши Дщер, преблагослове́нную Марі́ю, о Не́йже благослов'я́ться вся колі́на земна́я і при́йдеть спасе́ніє всему́ ми́ру; ми же, сіє́ ві́дуще, возопії́м Богоро́дице:","Ра́дуйся, Ма́ти Си́на Бо́жия;","ра́дуйся, пренепоро́чная Ді́во.","Ра́дуйся, Спа́са душ на́ших роди́вшая;","ра́дуйся, Невмісти́маго вмісти́лище.","Ра́дуйся, к сме́ртним благоволе́ніє;","ра́дуйся, сме́ртних к Бо́гу дерзнове́ніє.","Ра́дуйся, честні́йшая херуви́м;","ра́дуйся, сла́внійшая без сравне́нія серафи́м.","Ра́дуйся, а́да і сме́рті попра́ніє;","ра́дуйся, ві́чния жи́зні дарова́ніє.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, всеблага́я Ма́ти, взиску́ющая погиба́ющих."]},{"h":"Кондак 2","ps":["Ви́дівше святі́ї Твої́ роди́теліє Іоаки́м і А́нна, я́ко Ти єси́, Пречи́стая, плод благослове́нний, возблагодари́ша Бо́га, і пред две́рми хра́ма положи́ша обі́т посвяти́ти Тя Го́споду, пою́ще Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум соверше́нний стяжа́ла єси́, Богоро́дице, воспита́вшися во свята́я святи́х, та́ко же не преста́ни умудря́ти і просвіща́ти сві́том богоразу́мія і вся христия́ни, вопію́щия Ті такова́я:","Ра́дуйся, к богопозна́нію приводя́щая;","ра́дуйся, к сві́ту і́стини прельще́нних обраща́ющая.","Ра́дуйся, страх Бо́жий в сердця́ вселя́ющая;","ра́дуйся, благогові́ти пред святи́нею науча́ющая.","Ра́дуйся, ре́вностію ко спасе́нію воодушевля́ющая;","ра́дуйся, хра́ми Бо́жії почита́ти внуша́ющая.","Ра́дуйся, в них отра́ду находи́ти вдохновля́ющая;","ра́дуйся, жа́жду Свята́го Причаще́нія возбужда́ющая.","Ра́дуйся, ві́ру і любо́в к Бо́гу воспламеня́ющая;","ра́дуйся, чистоти́ і цілому́дрія побо́рнице.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, всеблага́я Ма́ти, взиску́ющая погиба́ющих."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго осіни́ Тя, Благода́тная, єгда́ арха́нгел Гавриї́л благовіствова́ніє о безсі́менном зача́тії із Тебе́ Си́на Бо́жия Спаси́теля ми́ру принесе́; Ти же, прия́вши сію́ благу́ю вість со смире́нієм, я́ко раба́ Госпо́дня, возопи́ла єси́ Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи во утро́бі Христа́ Жизнода́вця, востекла́ єси́, Благослове́нная, к ю́жице Своє́й, пра́ведній Єлисаве́ті, і цілова́стіся о́бі ма́тері, ра́дующеся о Бо́зі Спа́сі на́шем. Сего́ ра́ди, я́ко істо́чнику святи́я ра́дости, вопіє́м Ті си́це:","Ра́дуйся, тя́жкоє житіє́ на́ше облегча́ющая;","ра́дуйся, лю́тия біди́ і напа́сти отгоня́ющая.","Ра́дуйся, от душе́вния ту́ги і уни́нія спаса́ющая;","ра́дуйся, іспита́нія Бо́жия за бла́го прийма́ти указу́ющая.","Ра́дуйся, в самі́х страда́ніїх утіше́ніє подаю́щая;","ра́дуйся, я́ко Тобо́ю до́броє жела́ніє на́ше ісполня́ється.","Ра́дуйся, я́ко Тобо́ю зла́я начина́нія на́ша пресіка́ються;","ра́дуйся, огне́м Ма́тернія Твоєя́ любве́ ду́ші ві́рних согріва́ющая.","Ра́дуйся, благода́тію Свята́го Ду́ха нас озаря́ющая;","ра́дуйся, всіх скорб'я́щих і угнете́нних Ма́ти благосе́рдая.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, всеблага́я Ма́ти, взиску́ющая погиба́ющих."]},{"h":"Кондак 4","ps":["Бу́ря недоумі́нія смуща́єть мні ум, ка́ко возмогу́ недосто́йними устни́ восхвали́ти Тя, Пресвята́я Ді́во, за Твоє́ вели́коє нам воспоможе́ніє; ті́мже, велича́я неісче́тния Твоя́ ми́лості, смиренному́дренно пою́ Вседержи́телю Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаша вифлеє́мстії па́стиріє а́нгелов, пою́щих Христо́во Рождество́, те́кше к пеще́рі, обріто́ша та́мо Богороди́тельницю, на рука́х держа́щую Предві́чнаго Младе́нця. С ни́ми во весе́лії духо́вном і ми Тебі́, я́ко о́бщей Ма́тері, глаго́лем та́ко:","Ра́дуйся, младе́нцев воспита́ніє;","ра́дуйся, о́троком сми́сла пода́тельнице.","Ра́дуйся, до́брих діл вели́чіє;","ра́дуйся, возра́стних муже́й прему́дростію обогаща́ющая.","Ра́дуйся, жизнь смире́нієм і кро́тостію наделя́ющая;","ра́дуйся, ста́рцев благогові́йних сла́дкоє успокоє́ніє.","Ра́дуйся, ста́риць благолюби́вих ти́хоє прибі́жище;","ра́дуйся, честни́х бра́ков устроє́ніє.","Ра́дуйся, благочести́вих семе́йств благослове́ніє;","ра́дуйся, ді́вства похвало́ і возвише́ніє.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, всеблага́я Ма́ти, взиску́ющая погиба́ющих."]},{"h":"Кондак 5","ps":["Боготе́чною звіздо́ю явля́єшися, Цари́це Небе́сная, всім под кров Твой всемо́щний прибега́ющим і непреста́нно во умиле́нії серде́чнім вопію́щих Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя пра́ведний Симео́н Тя прише́дшую с Младе́нцем Ісу́сом во хра́мі предста́витися Го́сподеві, рече́: Тебі́ Само́й ду́шу ору́жіє про́йдеть, проразумева́я Ма́терняя Твоя́ страда́нія о Си́ні Твоє́м Боже́ственнім. Сего́ ра́ди зове́м Ті:","Ра́дуйся, рабо́в Бо́жиїх осмеїва́ємих ободре́ніє;","ра́дуйся, стоя́щих за пра́вду защи́щеніє.","Ра́дуйся, терпіли́вих страда́льцев предвкуше́нієм блаже́нства на небесі́ услажда́ющая;","ра́дуйся, сердця́ злих люде́й, вражду́ющих проти́вная, ум'ягча́ющая.","Ра́дуйся, сові́ти лука́вия і кова́рство їх разоря́ющая;","ра́дуйся, от разбо́йников на путі́ нас охраня́ющая.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, всеблага́я Ма́ти, взиску́ющая погиба́ющих."]},{"h":"Кондак 6","ps":["Пропові́дници Твоєя́ благода́тния по́мощі все мно́жество Тобо́ю спасе́нних єсть: стра́ждущії, боля́щії, скорб'я́щії і гріхми́ обремене́ннії, благода́рственно о Тебі́ вопію́щії к Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ боже́ственний світ во Єги́пті і падо́ша та́мо і́доли, єгда́ бежа́ла єси́, Пречи́стая, с Богомладе́нцем Ісу́сом, спаса́ющися от уби́йства І́родова; Ти бо, озаря́ющи сві́том богові́дінія уми́ всіх, удаля́ющихся пре́лестей су́єтнаго ми́ра, історга́єши із душ їх куми́ри гніздя́щихся та́мо губи́тельних страсте́й, ті́мже превозно́сим Тя словеси́ си́ми:","Ра́дуйся, сумня́щихся во ві́рі вразумле́ніє;","ра́дуйся, го́рдих умо́м свої́м смире́ніє.","Ра́дуйся, озло́бленних і гні́вом пали́мих укроще́ніє;","ра́дуйся, ро́пщущих на про́мисл Бо́жий с тягота́ми жи́зні примире́ніє.","Ра́дуйся, заблу́ждших на путь спасе́нія наставля́ющая;","ра́дуйся, суєве́рних і гада́телей посрамле́ніє.","Ра́дуйся, развраще́нних і нечести́вих обличе́ніє;","ра́дуйся, я́ко душевре́дния уче́нія низлага́єши.","Ра́дуйся, я́ко і́стину познава́ти помога́єши;","ра́дуйся, я́ко мрак хули́, срамосло́вія і вся́кия лжі разсева́єши.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, всеблага́я Ма́ти, взиску́ющая погиба́ющих."]},{"h":"Кондак 7","ps":["Хотя́ще ніколи́же отлуча́тися от рожде́ннаго Тобо́ю Спаси́теля ми́ра, Ти, Богоблаже́нная, пребива́ла єси́ с Ним неотлу́чно во гра́ді Назаре́ті, детоводя́щи і пита́ющи Єго́, я́ко Челові́ка, і пою́щи в се́рдці Своє́м, я́ко Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую показу́ющи Ма́тернюю любо́в к Си́ну Твоєму́, со ско́рбію іска́ла єси́ Єго́, двоюнадесятоле́тняго О́трока, во гра́ді Ієрусали́ме в пра́здник Па́схи, мня́щи Єго́ во дружи́ні би́ти. Ві́дуще таково́є Твоє́ сердобо́ліє, со умиле́нієм вопіє́м Ті:","Ра́дуйся, оби́димих і огорче́нних возвиша́ющая;","ра́дуйся, ненави́димих і всі́ми отве́рженних че́стію вінча́ющая.","Ра́дуйся, убо́гих і наги́х одія́ніє;","ра́дуйся, ни́щих і разоре́нних пита́ніє.","Ра́дуйся, бездо́мних, стра́нних, вдов і сиро́т призрі́ніє;","ра́дуйся, путеше́ствующих благополу́чноє к до́му возвраще́ніє.","Ра́дуйся, заблу́ждших в путі́ к жили́щу приведе́ніє;","ра́дуйся, ді́тем неразу́мним ра́зум обновля́ющая.","Ра́дуйся, умо́м і нра́вом прости́х люде́й Своє́ю по́мощію не оставля́ющая;","ра́дуйся, упова́ющих на во́лю Бо́жию наслажде́ніє.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, всеблага́я Ма́ти, взиску́ющая погиба́ющих."]},{"h":"Кондак 8","ps":["Стра́нноє і преди́вноє Твоє́ попече́ніє бисть о христия́ніх на всіх путеіх їх жи́зні многом'яте́жния і многотру́дния; іму́ще у́бо в Тебі́ толи́ко милосе́рдную і незави́стную помо́щницю, всі облагоде́тельствованнії Тобо́ю велегла́сно пою́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся била́ єси́ со Христо́м, єгда́ служа́ше Той ро́ду челові́чеському, я́коже боже́ственний Лука́ повіству́єть. Прийдо́ша бо ні́ції к Си́ну Твоєму́, глаго́люще: Ма́ти Твоя́ і бра́тія Твої́ вні стоя́ть, ви́діти Тя хотя́ще. Мним, я́ко Ти, всеблага́я Ма́ти, неотсту́пно пребива́єши і со всі́ми тружда́ющимися во сла́ву Бо́жию, і восхваля́ющими Тя та́ко:","Ра́дуйся, су́щих во вла́сті к торжеству́ до́бра наставля́ющая;","ра́дуйся, святи́телей пра́вило ві́ри і благоче́стія явля́ющая.","Ра́дуйся, па́стирей ре́вностію о спасе́нії душ чад духо́вних снабдіва́ющая;","ра́дуйся, наста́вников соверше́нний ра́зуме.","Ра́дуйся, уча́щихся в нау́ках преспі́яніє;","ра́дуйся, і́ноком і і́нокиням в борбі́ с прило́ги ми́ра і пло́ті пособля́ющая.","Ра́дуйся, суде́й свято́є зерца́ло пра́вди;","ра́дуйся, враче́й іску́сноє врачева́ніє больни́х.","Ра́дуйся, земледі́льцев сорабо́тнице і блага́я помо́щнице;","ра́дуйся, всіх тружда́ющихся поко́ю і наде́жноє приста́нище.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, всеблага́я Ма́ти, взиску́ющая погиба́ющих."]},{"h":"Кондак 9","ps":["Всяк во́зраст ві́рних благопо́льзується Твої́м попече́нієм, всеми́лостивая Ма́ти, я́ко всегда́ к Тебі́ прибега́ющим душеполе́зная да́руєши, потре́бная в житії́ доставля́єши і усе́рдно хода́тайствуєши за ни, немощни́я і грі́шния, у престо́ла Го́спода сла́ви, Єму́же поє́м: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́я многовіща́ннії не мо́гуть ізглаго́лати Твоєя́ Ма́тернія печа́лі, при кресті́ Си́на Твоєго́ би́вшия, єгда́ ви́діла єси́ Єго́ стра́ждуща за вся челові́ки му́ками неізглаго́ланними; ті́мже, я́ко іскуше́нная по вся́чеським, претерпі́ти в са́мих тя́жких ско́рбіх і лише́ніїх нам помози́. Сего́ ра́ди взива́єм Ті:","Ра́дуйся, сліпи́м прозрі́ніє;","ра́дуйся глухи́м сли́шаніє.","Ра́дуйся, хроми́м хожде́ніє;","ра́дуйся, рассла́бленних ті́лом ісціле́ніє.","Ра́дуйся, неду́жних здра́віє;","ра́дуйся, стужа́ємих от бісо́в ізбавле́ніє.","Ра́дуйся, поврежде́нних умо́м просвіще́ніє;","ра́дуйся, неісці́льних больни́х на Свої́ всемо́щнеї ру́ці приє́млющая.","Ра́дуйся, отча́янних грі́шников моле́ніє не отверга́ющая;","ра́дуйся, от па́губнаго безво́лія їх похища́ющая.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, всеблага́я Ма́ти, взиску́ющая погиба́ющих."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ мир і́же всіх Госпо́дь, Сий на кресті́, дарова́ всему́ ми́ру пресвяту́ю премилосе́рдную Ма́тер, єгда́ ізрече́ Пренепоро́чній і возлю́бленному ученику́: Же́но, се син Твой, і: Се Ма́ти твоя́. Благодаря́ще за сіє́ всеблага́го Бо́га, глаго́лем Єму́: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ крі́пкая яви́лася єси́ по заві́ту Го́спода, Преблагослове́нная, да́рующи всім благоде́нствіє, мир, отра́ду, ра́дость, я́ко і Сама́ сія́ от воскре́сшаго Христа́ Спаси́теля прия́ла єси́, усли́шавши от Него́ приве́тственний глас:","Ра́дуйся, я́ко ублажа́ють Тя всі ро́ди;","ра́дуйся, вся́кую не́нависть, зло́бу, вражду́ укроща́ющая.","Ра́дуйся, мир о Ду́сі Свя́те в сердця́ ві́рних вселя́ющая;","ра́дуйся, клевету́, ре́вность і злопа́м'ятство істребля́ющая.","Ра́дуйся, братолю́бієм лю́ди ущедря́ющая;","ра́дуйся, от гла́да, хла́да, тру́са, пото́па, огня́, меча́ огражда́ющая.","Ра́дуйся, хлі́бом насу́щним ві́рния пита́ющая;","ра́дуйся, смертоно́сную я́зву прекраща́ющая.","Ра́дуйся, гнів Бо́жий пра́ведний утоля́ющая;","ра́дуйся, пра́ведних діл поспіше́ніє.","Ра́дуйся, на всіх путеіх жи́зні христия́н промишле́ніє;","ра́дуйся, роди́телей благонра́вієм діте́й утіша́ющая.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, всеблага́я Ма́ти, взиску́ющая погиба́ющих."]},{"h":"Кондак 11","ps":["Пі́ніє на́ше смире́нноє, от полноти́ любве́ і усе́рдія Тебі́ приноси́моє, не пре́зри, Богоневі́сто, і не отврати́ся от нас, грі́шних і недосто́йних, но помози́ нам очи́ститися от вся́кия скве́рни пло́ті і ду́ха, да возмо́жем досто́йно і пра́ведно пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́том путеводя́щим яви́лася єси́ апо́столом, Богороди́тельнице, по вознесе́нії Си́на Твоєго́ на не́бо; сего́ у́бо сві́та, о Всепі́тая, не лиши́ всіх, да́же до сего́ дне оста́вльшихся і хотя́щих спасти́ся і в ра́зум і́стини прийти́. Твої́м святи́м води́тельством і нас спаси́, в жите́йськом мо́ре треволне́ньми обурева́ємих, оба́че от сердця́ принося́щих Тебі́ благохвале́нія такова́я:","Ра́дуйся, нечи́стия по́мисли пожига́ющая;","ра́дуйся, іскуше́нія і собла́зни от нас прогоня́ющая.","Ра́дуйся, к покая́нію і ісправле́нію жи́зні на́шея подвиза́ющая;","ра́дуйся, слеза́ми сокруше́нія бе́здну беззако́ній на́ших омива́ющая.","Ра́дуйся, духо́вно бо́дрствовати нам помога́ющая;","ра́дуйся, к трезве́нію і моли́тві ві́рния приводя́щая.","Ра́дуйся, блаже́нство ду́ха тім уготовля́ющая;","ра́дуйся, подви́жников благоче́стія я́вноє укріпле́ніє.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, всеблага́я Ма́ти, взиску́ющая погиба́ющих."]},{"h":"Кондак 12","ps":["Благода́ть боже́ственную іспроси́ нам у Си́на Твоєго́ і Бо́га, простри́ ру́ку по́мощі, да не поги́бнем во грісі́х і лю́тих обстоя́ніїх, находя́щих на ни от враг ви́димих і неви́димих; умиротвори́ на́ша сердця́, зло́бою і враждо́ю іспо́лненная, да уті́шени Тобо́ю, ра́достно зове́м Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще честно́є Твоє́ успе́ніє, прославля́єм і покро́в Твой святи́й, распросте́ртий над всім ми́ром, найпа́че же родо́м христия́нським, прославля́ющим Тя та́ко:","Ра́дуйся, покая́нієм ко ісхо́ду от сея́ жи́зні нас приуготовля́ющая;","ра́дуйся, болі́зньми от гріхо́в очища́ющая.","Ра́дуйся, я́ко от напра́сния сме́рті ві́рния сохраня́єши;","ра́дуйся, я́ко послі́дняго напу́тствія досто́йния сподобля́єши.","Ра́дуйся, сме́ртний страх от тіх удаля́ющая;","ра́дуйся, ско́роє разріше́ніє ду́ші от ті́ла в предсме́ртних му́ках находя́щимся посила́ющая.","Ра́дуйся, ми́рную кончи́ну живота́ на́шего да́рующая;","ра́дуйся, го́рких мита́рств ізбавля́ющая.","Ра́дуйся, христия́нськаго погребе́нія нас не лиша́ющая;","ра́дуйся, ко Го́споду, Си́ну Своєму́, о нас предста́тельствующая.","Ра́дуйся, і в жи́зні і по сме́рті с на́ми пребива́ющая;","ра́дуйся, ра́досте на́ша, две́рі ра́йськія нам отверза́ющая.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, всеблага́я Ма́ти, взиску́ющая погиба́ющих."]},{"h":"Кондак 13","ps":["О Влади́чице ми́ра! Прийми́ сіє́ ма́лоє благодаре́ніє на́ше, от всего́ се́рдця Тебі́ приноси́моє, і не попусти́ нам ніколи́же охладева́ти в сем благода́рном чу́встві, но вразуми́ нас всегда́ по́мнити Твоя́ неісче́тния ми́лості і со слеза́ми умиле́нія вопи́ти о Тебі́ Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельський усли́ша глас свята́я А́нна, віща́яй: зачне́ши і роди́ши Дщер, преблагослове́нную Марі́ю, о Не́йже благослов'я́ться вся колі́на земна́я і при́йдеть спасе́ніє всему́ ми́ру; ми же, сіє́ ві́дуще, возопії́м Богоро́дице:","Ра́дуйся, Ма́ти Си́на Бо́жия;","ра́дуйся, пренепоро́чная Ді́во.","Ра́дуйся, Спа́са душ на́ших роди́вшая;","ра́дуйся, Невмісти́маго вмісти́лище.","Ра́дуйся, к сме́ртним благоволе́ніє;","ра́дуйся, сме́ртних к Бо́гу дерзнове́ніє.","Ра́дуйся, честні́йшая херуви́м;","ра́дуйся, сла́внійшая без сравне́нія серафи́м.","Ра́дуйся, а́да і сме́рті попра́ніє;","ра́дуйся, ві́чния жи́зні дарова́ніє.","Ра́дуйся, Благода́тная Богоро́дице Ді́во, всеблага́я Ма́ти, взиску́ющая погиба́ющих."]},{"h":"Кондак 1","ps":["Возбра́нной Воєво́ді, Цари́це небесе́ і землі́, дарова́вшей нам пречу́дную іко́ну Взиску́ющую, благода́рственноє прино́сим пі́ніє. Ти же, я́ко благосе́рдая Ма́ти, не отри́ни на́шего сего́ моле́нія, но благоволи́ прия́ти є, і сподо́би вопи́ти Тебі́ та́ко:","Ра́дуйся, Благода́тная Богоро́дице Ді́во, всеблага́я Ма́ти, взиску́ющая погиба́ющих."]},{"h":"Молитва перша","ps":["О, Пресвята́я і Преблагослове́нная Ді́во, Влади́чице Богоро́дице! При́зри ми́лостивим Твої́м о́ком на нас, предстоя́щих пред свято́ю іко́ною Твоє́ю і со умиле́нієм моля́щихся Тебі́, воздви́гни нас із глубини́ гріхо́вния, просвіти́ ум наш, омраче́нний страстьми́, і уврачу́й я́зви душ і тіле́с на́ших. Не і́мами іни́я по́мощі, не і́мами іни́я наде́жди, ра́зві Тебе́, Влади́чице, Ти ві́си вся не́мощі і согріше́нія на́ша, к Тебі́ прибіга́єм і вопіє́м: не оста́ви нас Твоє́ю Небе́сною по́мощію, но предста́ни нам при́сно і Твої́м неізрече́нним милосе́рдієм і щедро́тами спаси́ і поми́луй нас, погиба́ющих. Да́руй нам ісправле́ніє гріхо́вния жи́зні на́шея і ізба́ви нас от скорбе́й, бід і болі́зней, от напра́сния сме́рті, а́да і ві́чния му́ки. Ти бо, Цари́це і Влади́чице, ско́рая Помо́щниця і Засту́пниця всім, притека́ющим к Тебі́, і крі́пкоє прибі́жище грі́шников ка́ющихся. Пода́ждь у́бо нам, Преблага́я і Всенепоро́чная Ді́во, христия́нський коне́ць живота́ на́шего, ми́рен і непости́ден, і сподо́би нас Твої́м хода́тайством всели́тися в оби́телях Небе́сних, іді́же непреста́нний глас пра́зднующих ра́достію сла́вить Пресвяту́ю Тро́йцю, Отця́, і Си́на, і Свята́го Ду́ха, ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["Засту́пнице усе́рдная, Благоутро́бная Го́спода Ма́ти, к Тебі́ прибіга́ю аз, окая́нний і па́че всіх челові́ко грішні́йший, воньми́ гла́су моле́нія моєго́, вопль мой і стена́нія усли́ши, я́ко беззако́нія моя́ превзидо́ша главу́ мою́, і аз, я́коже кора́бль в пучи́ні, погружа́юся в мо́ре гріхо́в мої́х. Но Ти, всеблага́я і Милосе́рдая Влади́чице, не пре́зри мене́, отча́яннаго і во грісі́х погиба́ющаго; поми́луй м'я, ка́ющагося в злих ді́ліх мої́х, і обрати́ на путь пра́вий заблу́ждшую окая́нную ду́шу мою́. На Тебі́, Влади́чице моя́ Богоро́дице, возлага́ю все упова́ніє моє́. Ти, Ма́ти Бо́жия, сохрани́ і соблюди́ м'я под кро́вом Твої́м, ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["О Пресвята́я Ді́во Богоро́дице, преми́лостивая Ма́ти всіх христия́н, найпа́че же скорб'я́щих, гони́мих і многоразли́чними неду́ги одержи́мих! Аз, нищ сий і убо́г душе́ю і ті́лом, предстою́ пред святи́м Твої́м о́бразом со слеза́ми і уми́льно прошу́ Твоєго́ благода́тнаго призрі́нія, нічто́же бо до́броє і благо́є во мні єсть: весь обложе́н єсьм немощми́, нището́ю і убо́жеством; но́зі мої́ не обуве́ни, даби́ поспеша́ти мі на ді́ла свята́я і богоуго́дная; ру́ці мої́ загрязне́ни от мно́жества соді́янних беззако́ній; о́чі мої́ потупле́ни от нечистоти́ со́вісти, не возмо́гуть взира́ти на благолі́піє красоти́ Твоєя́; лице́ моє́ потемне́но і іспещре́но печа́тію безчи́сленних мої́х поро́ков і гріхопаде́ній. Ність во мні ні спаси́тельния ві́ри, ні уті́шительния наде́жди, ніже́ благости́нния любве́. Аз єсьм я́ко гни́лостний сосу́д, преіспо́лненний вся́кия скве́рни, го́рдості, себ'ялю́бія, високоу́мія, тщесла́вія, гні́ва, раздражи́тельности, зло́би, пам'ятозло́бія, недоброжела́тельства, за́висти, ре́вности, осужде́нія, ро́пота, злосло́вія, праздносло́вія, лука́вства, ле́сти, обма́на, невоздержа́нія душе́вних і тіле́сних чувств, пристра́стія, плотоуго́дія вся́каго, сладостра́стія і іни́х тьмочи́сленних страсте́й; і вся́коє убо́жество моє́ духо́вноє, і тіле́сния болі́зні, і напа́сти обдержа́ша м'я, і все житіє́ моє́, я́ко трость, коле́блемо ві́тром, по́лно недосто́їнства, стра́ха, і вся́кия опа́сности; по глаго́лу свята́го апо́стола, біди́ нападо́ша отовсю́ду на м'я; біди́ от духо́в зло́би поднебе́сних, біди́ от ненави́дящих і оби́дящих, вражду́ющих проти́ву мене́ челові́к; біди́ от звіре́й, ското́в і гад земни́х, біди́ от стихі́й ми́ра: мо́лнії, огня́, води́, тлетво́рнаго возду́ха, хла́да, гла́да; біди́ от мно́гих не́мощей і болі́зней моєго́ ті́ла; біди́ на путі́ і в дому́, біди́ во дні і нощі́. Кто же м'я от враго́в ізба́вить, кто к добро́ті діл напра́вить, кто болі́зні моя́ ісціли́ть, кто утіши́ть і успоко́їть, вразуми́ть, наста́вить, спасе́ть і поми́луєть м'я, а́ще не Ти, Пресвята́я Ма́ти, засту́пнице і покрови́тельнице всеблага́я! Ти разсі́янний мой ум собери́, по́мисли от вся́кия скве́рни очи́сти; чу́вства, отра́вленная злом, освежи́; во́лю мою́ немощну́ю на все до́броє укріпи́ і от па́губнаго безво́лія м'я ізба́ви; се́рдце моє́ от страсте́й свободи́ і свято́ю любо́вію к Бо́гу і бли́жнім напо́лни; всю вну́треннюю хра́мину мою́ устро́й і удо́бним жили́щем Ду́ха Свята́го соді́лай. Не оста́ви м'я, премилосе́рдная Влади́чице, в тіле́сном моє́м многоско́рбном житії́. Болі́зні потреби́, враги́ ви́димия і неви́димия разжени́, зла́я обстоя́нія разруши́, страх, приходя́щий от духо́в зло́би і челові́ков, хотя́щих м'я погуби́ти, отжени́. Вся потре́бная і ну́жная мі да́руй; бо́дрость ду́ха посли́; да обновле́нний, да очище́нний, да уті́шенний Тобо́ю, Цари́це моя́ пресвята́я, просла́влю Святу́ю Тро́йцю, Отця́ і Си́на і Свята́го Ду́ха, і Твоє́ ди́вноє о мні попече́ніє ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 7","ps":["Ра́дуйся, Благода́тная Богоро́дице Ді́во, / во об'я́тіях Свої́х Предві́чнаго Младе́нця і Бо́га носи́вшая. / Проси́ Єго́ да́ти ми́ру умире́ніє / і душа́м на́шим спасе́ніє. / Син бо Тебе́, Богома́ти, віща́єть, / я́ко вся проше́нія Твоя́ во благо́є іспо́лнить. / Сего́ ра́ди і ми припа́дающе, мо́лимся / і наді́ющіїся на Тя, да не поги́бнем, / і́м'я Твоє́ імену́єм: / Ти бо єси́ Влади́чице, // Взиска́ніє поги́бших."]},{"h":"Інший тропар, глас 4","ps":["Взищи́ нас, погиба́ющих, Пресвята́я Ді́во, / не по гріхо́м бо на́шим наказу́єши нас, / но по человіколю́бію ми́луєши, / ізба́ви нас от а́да, болі́зні і ну́жди // і спаси́ нас."]},{"h":"Кондак, глас 6","ps":["Предста́тельство христия́н непости́дноє, / хода́тайство ко Творцю́ непрело́жноє, / не пре́зри грі́шних моле́ній гла́си, / но предвари́, я́ко Блага́я, на по́мощ нас, / ві́рно зову́щих Ті: / ускори́ на моли́тву і потщи́ся на умоле́ніє, // предста́тельствующи при́сно, Богоро́дице, чту́щих Тя."]},{"h":"Інший кондак, глас 6","ps":["Не і́мами іни́я по́мощі, / не і́мами іни́я наде́жди, / ра́зві Тебе́, Пречи́стая Ді́во, / Ти нам помози́, / на Тебі́ наді́ємся / і Тобо́ю хва́лимся, / Твої́ бо єсьми́ раби́, // да не постиді́мся."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтем о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Нечаянная Радість»","e":"Akathist to the Theotokos before her icon “Unexpected Joy”","secs":[{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́в Бо́жієй Ма́тері і Цари́ці, яви́вшейся іногда́ к челові́ку беззако́нну, во є́же отврати́ти єго́ от путі́ нече́стія, благода́рственноє пі́ніє прино́сим Ті, Богороди́тельнице; Ти же, я́ко іму́щая милосе́рдіє неізрече́нноє, от вся́ких нас бід і гріхо́в свободи́, да зове́м Ті:","Ра́дуйся, неча́янную ра́дость ві́рним да́рующая."]},{"h":"Ікос 1","ps":["А́нгели і пра́ведних ду́ші удиви́шася, єгда́ предста́ла єси́ пред Си́ном Твої́м і Бо́гом і мно́гим моле́нієм хода́тайствовала єси́ о челові́ці, при́сно во грісі́х пребива́ющем; ми же, очи́ма ві́ри толи́коє Твоє́ благоутро́біє зря́ще, со умиле́нієм взива́єм Ті си́це:","Ра́дуйся, моли́тви всіх христия́н приє́млющая;","ра́дуйся, і са́мих отча́янних грі́шников моле́нія не отверга́ющая.","Ра́дуйся, к Си́ну Твоєму́ о них предста́тельствующая;","ра́дуйся, неча́янную ра́дость спасе́нія їм подаю́щая.","Ра́дуйся, предста́тельством Твої́м весь мир спаса́ющая;","ра́дуйся, вся на́ша печа́лі утоля́ющая.","Ра́дуйся, Ма́ти всіх Бо́га, озло́бленних ду́ші утіша́ющая;","ра́дуйся, житіє́ на́ше до́брі устроя́ющая.","Ра́дуйся, ізбавле́ніє от гріхо́во всім челові́ком прине́сшая;","ра́дуйся, Ра́дость всему́ ми́ру роди́вшая.","Ра́дуйся, неча́янную ра́дость ві́рним да́рующая."]},{"h":"Кондак 2","ps":["Ви́дящи Пресвята́я челові́ка, а́ще і беззако́нна, но на всяк день с ві́рою і упова́нієм пред честно́ю Єя́ іко́ною до́лу поверга́ющагося і Арха́нгельськоє приві́тствіє Єй принося́щаго, внят і такова́го грі́шника славосло́вію, да всі, зря́ще Єя́ Ма́тернєє милосе́рдіє, на Небесі́ і на землі́ вопію́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум челові́чеський воі́стину превосхо́дить любо́в Твоя́ к ро́ду христия́нському, я́ко і тогда́ не преста́ла єси́ от хода́тайства Твоєго́ о челові́ці беззако́нном, єгда́ Син Твой показа́ Тебі́ я́зви гвозди́ния, гріхи́ челові́чеськими Єму́ соді́янния. Зря́ще Тя толи́ко неотсту́пную Предста́тельницю за нас, грі́шних, со слеза́ми вопіє́м Ті:","Ра́дуйся, Засту́пнице усе́рдная ро́да христия́нськаго, от Бо́га нам дарова́нная;","ра́дуйся, Путеводи́тельнице на́ша, к Небе́сному Оте́честву нас возводя́щая.","Ра́дуйся, ві́рних огражде́ніє і прибі́жище;","ра́дуйся, по́моще всіх, призива́ющих і́м'я Твоє́ свято́є.","Ра́дуйся, всі́ми презрі́нних і отве́рженних от ро́ва поги́белі ісхища́ющая;","ра́дуйся, тіх на путь пра́вий обраща́ющая.","Ра́дуйся, непреста́нноє уни́ніє і мрак душе́вний отгоня́ющая;","ра́дуйся, іжди́вшим от неду́га ум но́вий і лу́чшій смисл подаю́щая.","Ра́дуйся, оста́вленних врача́ми на Своя́ всемо́щния ру́ці приє́млющая.","Ра́дуйся, неча́янную ра́дость ві́рним да́рующая."]},{"h":"Кондак 3","ps":["Си́ла благода́ті преізоби́ловала та́мо, іді́же умно́жися гріх; да ра́дуються на Небесі́ всі А́нгели о єди́нім грі́шниці пока́явшемся, пою́ще пред Престо́лом Бо́жиїм: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи к ро́ду христия́нському Ма́тернєє милосе́рдіє, всім с ві́рою і упова́нієм прибега́ющим к Тебі́ подає́ши ру́ку по́мощі, Влади́чице, да всі єди́нім се́рдцем і єди́ними усти́ славосло́віє прино́сять Ті сицево́є:","Ра́дуйся, я́ко Тобо́ю к нам нисхо́дить Бо́жиє благоволе́ніє;","ра́дуйся, я́ко Тобо́ю і ми і́мами вя́щшеє к Бо́гу дерзнове́ніє.","Ра́дуйся, я́ко во всіх біда́х і обстоя́ніїх на́ших прино́сиши Си́ну Твоєму́ усе́рдния о нас моли́тви;","ра́дуйся, я́ко і на́ша моли́тви прия́тними Бо́гу соде́ливаєши.","Ра́дуйся, я́ко неви́димих враго́в от нас отгоня́єши;","ра́дуйся, я́ко от ви́димих враго́в нас ізбавля́єши.","Ра́дуйся, я́ко сердця́ злих челові́к ум'ягча́єши;","ра́дуйся, я́ко от клевети́, досажде́нія і укоре́нія нас ізима́єши.","Ра́дуйся, я́ко Тобо́ю вся блага́я жела́нія на́ша ісполня́ються;","ра́дуйся, я́ко мно́го мо́жеть моли́тва Твоя́ пред Си́ном Твої́м і Бо́гом.","Ра́дуйся, неча́янную ра́дость ві́рним да́рующая."]},{"h":"Кондак 4","ps":["Бу́рю внутр імі́я гріхо́вних помишле́ній, челові́к беззако́нен моля́шеся пред честно́ю іко́ною Твоє́ю і, ви́дів Кров от язв Предві́чнаго Си́на Твоєго́ пото́ками, я́коже на Кресті́, теку́щую, паде́ от стра́ха і с рида́нієм та́ко вопія́ше Ті: «Поми́луй м'я, о Ма́ти милосе́рдія, да не преодолі́єть зло́ба моя́ неізре́ченния бла́гості і милосе́рдія Твоєго́, Ти бо єси́ всім грі́шником єди́на наде́жда і прибі́жище; преклони́ся у́бо на ми́лость, Блага́я Ма́ти, і умоли́ о мні Си́на Твоєго́ і Творця́ моєго́, да непреста́нно зову́ Єму́: Аллилу́я»."]},{"h":"Ікос 4","ps":["Сли́шавше небожи́тели о чуде́снім моли́твами Твої́ми спасе́нії їх земна́го ги́бнущаго бра́та, просла́виша Тя, благосе́рдую Цари́цю Небесе́ і землі́; і ми, грі́шнії, све́давше таково́є подо́бнаго нам грі́шника заступле́ніє, а́ще і недоуміва́єть язи́к наш восхвали́ти Тя по достоя́нію, от глубини́ умиле́ннаго сердця́ на́шего воспіва́єм Ті си́це:","Ра́дуйся, Спору́чнице спасе́нія грі́шних;","ра́дуйся, Взиска́ніє поги́бших.","Ра́дуйся, Неча́янная грі́шних Ра́досте;","ра́дуйся, па́дших возста́ніє.","Ра́дуйся, Предста́тельнице к Бо́гу, мир от бід спаса́ющая;","ра́дуйся, я́ко гла́са моли́тв Твої́х бі́си трепе́щуть.","Ра́дуйся, я́ко А́нгели сему́ ра́дуються;","ра́дуйся, я́ко і нас, земноро́дних, си́ла моли́тв Твої́х весе́лія ісполня́єть.","Ра́дуйся, я́ко ті́ми от ти́ни гріхо́в нас ізима́єши;","ра́дуйся, я́ко пла́мень страсте́й на́ших угаша́єши.","Ра́дуйся, неча́янную ра́дость ві́рним да́рующая."]},{"h":"Кондак 5","ps":["Боготе́чную звізду́, чудотво́рную іко́ну Ма́тере Твоєя́ показа́л єси́ нам, Го́споди, і́бо, взира́юще на о́браз Єя́ тіле́снима очи́ма, умо́м і се́рдцем к Первообра́зній возвиша́ємся і Є́ю к Тебі́ востека́єм, пою́ще: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше А́нгели Храни́тели христия́н, я́ко Бо́жия Ма́тер споспішеству́єть їм в наставле́нії тіх, заступле́нії і спасе́нії, потща́шася си́це возопи́ти Честні́йшей Херуви́м і Сла́внейшей без сравне́нія Серафи́м:","Ра́дуйся, с Си́ном Твої́м і Бо́гом ві́чно ца́рствующая;","ра́дуйся, Єму́ всегда́ о ро́ді христия́нстім моле́нія принося́щая.","Ра́дуйся, в христия́нстій ві́рі і благоче́стії Наста́внице;","ра́дуйся, єресе́й і тлітво́рних раско́лов Іскорени́тельнице.","Ра́дуйся, от растліва́ющих ду́шу і ті́ло собла́знов сохраня́ющая;","ра́дуйся, от опа́сних обстоя́ній і внеза́пния сме́рті без покая́нія і Свята́го Причаще́нія ізбавля́ющая.","Ра́дуйся, упова́ющим на Тя живота́ непости́дний коне́ць да́рующая;","ра́дуйся, і по сме́рті за отше́дшую на суд Госпо́день ду́шу пред Си́ном Твої́м неотсту́пно хода́тайствующая.","Ра́дуйся, Твої́м Ма́тернім предста́тельством от ві́чнаго муче́нія сію́ ізбавля́ющая.","Ра́дуйся, неча́янную ра́дость ві́рним да́рующая."]},{"h":"Кондак 6","ps":["Пропові́дник чу́днаго Твоєго́ милосе́рдія, дарова́ннаго ні́коєму челові́ку беззако́нну, яви́ся святи́й Дими́трій Росто́вський, і́же, спису́я вели́кая і сла́вная, і ізря́дная ді́ла Бо́жія, в Тебі́ явле́нная, предаде́ пи́сьмені і сіє́ ді́ло ми́лости Твоєя́ в науче́ніє і утіше́ніє всім ві́рним, да і ті́ї, во грісі́х, біда́х, ско́рбіх і озлобле́ніїх су́ще, мно́гажди на всяк день с ві́рою в моли́тві пред о́бразом Твої́м колі́на преклоня́ють і, тіх ізби́вше, вопію́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ нам, я́ко пресві́тлая заря́, чудотво́рная іко́на Твоя́, Богома́ти, прогоня́я тьму бід і скорбе́й от всіх, с любо́вію вопію́щих Ті си́це:","Ра́дуйся, Ціли́тельнице на́ша в болі́зніх тіле́сних;","ра́дуйся, Блага́я Уті́шительнице в печа́ліх на́ших душе́вних.","Ра́дуйся, скорб на́шу в ра́дость претворя́ющая;","ра́дуйся, ненаді́ющихся несумні́нною наде́ждою возвеселя́ющая.","Ра́дуйся, а́лчущих Пита́тельнице;","ра́дуйся, наги́х одія́ніє.","Ра́дуйся, вдов Уті́шительнице;","ра́дуйся, безма́терніх сиро́т незри́мая Воспита́тельнице.","Ра́дуйся, непра́ведно гони́мих і оби́димих Засту́пнице;","ра́дуйся, гоня́щих і оби́дящих правосу́дная отмсти́тельнице.","Ра́дуйся, неча́янную ра́дость ві́рним да́рующая."]},{"h":"Кондак 7","ps":["Хотя́ Законода́вець Правосу́дний Госпо́дь Сам би́ти зако́на Ісполни́тель і яви́ти милосе́рдія Своєго́ бе́здну, преклони́ся на усе́рдноє моле́ніє Твоє́, Преблагослове́нная Ма́ти Ді́во, о челові́ці беззако́нне, глаго́ля: «Зако́н повеліва́єть, да син чтить ма́тер. Аз Син Твой, Ти же Ма́ти Моя́: Аз Тя до́лжен чти́ти, послу́шая Твоєго́ моле́нія; бу́ди у́бо, я́коже хо́щеши: ни́ні проща́ються єму́ гріси́ Тебе́ ра́ди». Ми же, ви́дяще такову́ю си́лу моли́тви Хода́тайці на́шей о проще́нії согріше́ній на́ших, просла́вим милосе́рдіє і неізрече́нноє благоутро́біє Єя́, зову́ще: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє ди́вноє і сла́вноє зна́меніє всім ві́рним яви́ся, я́ко не то́кмо Ма́тері Твоє́й, но і пречи́стому Єя́ ли́ку, на доскі ізображе́нному, си́лу чудотворе́нія дарова́л єси́, Го́споди; сему́ та́їнству див'я́щеся, во умиле́нії сердця́ вопіє́м к Ней такова́я:","Ра́дуйся, прему́дрости і бла́гости Бо́жия открове́ніє;","ра́дуйся, ві́ри утвержде́ніє.","Ра́дуйся, благода́ті явле́ніє;","ра́дуйся, душеполе́зних зна́ній дарова́ніє.","Ра́дуйся, душевре́дних уче́ній низложе́ніє;","ра́дуйся, беззако́нних на́виков нетру́дноє преодолі́ніє.","Ра́дуйся, сло́во прему́дрости прося́щим да́рующая;","ра́дуйся, несми́сленния разу́мния соде́ловающая.","Ра́дуйся, ді́тем, неудо́б уча́щимся, ра́зум подаю́щая;","ра́дуйся, ю́ности блага́я Охрани́тельнице і Наста́внице.","Ра́дуйся, неча́янную ра́дость ві́рним да́рующая."]},{"h":"Кондак 8","ps":["Стра́нноє і ужа́сноє виді́ніє бисть ні́коєму челові́ку беззако́нну, показу́я єму́ бла́гость Госпо́дню, предста́тельством Богома́тере гріхи́ єго́ проща́ющую; сего́ ра́ди отто́лі, іспра́вль своє́ житіє́, поживе́ богоуго́дні. Си́це і ми, сла́вная діла́ і многоразли́чную прему́дрость Бо́жию в ми́рі і жи́зні на́шей ви́дяще, устрані́мся земни́я суєти́ і ізли́шніх жите́йських попече́ній і ум і се́рдце на́ше на Небеса́ возведе́м, пою́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся во ви́шніх пребива́ющи, і ни́жніх ніка́коже отступи́ла єси́, Премилосе́рдая Цари́це Небесе́ і землі́; а́ще бо по Успе́нії Твоє́м і взошла́ єси́ на Небеса́ с Пречи́стою Твоє́ю пло́тію, оба́че і грі́шния землі́ не оста́вила єси́, явля́ющися Прича́стниця Промишле́нія Си́на Твоєго́ о ро́ді христия́нстім. Сего́ ра́ди Тя по до́лгу ублажа́єм:","Ра́дуйся, сія́нієм пречи́стия душі́ Твоєя́ всю зе́млю просвіти́вшая;","ра́дуйся, чистото́ю тілесе́ Твоєго́ вся Небеса́ возвесели́вшая.","Ра́дуйся, Промишле́нія Си́на Твоєго́ о ро́ді христия́нстім Свята́я Служи́тельнице;","ра́дуйся, о всем ми́рі усе́рдная Предста́тельнице.","Ра́дуйся, всіх нас при Кресті́ Си́на Твоєго́ усинови́вшая;","ра́дуйся, всегда́ Ма́тернюю любо́в к нам явля́ющая.","Ра́дуйся, всіх даро́в, духо́вних і тіле́сних, незави́стная Пода́тельнице;","ра́дуйся, благ вре́менних Хода́тайце.","Ра́дуйся, две́рі Ца́рствія Христо́ва ві́рним отверза́ющая;","ра́дуйся, і на землі́ чи́стаго весе́лія сердця́ їх ісполня́ющая.","Ра́дуйся, неча́янную ра́дость ві́рним да́рующая."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ а́нгельськоє удиви́ся ді́лу Твоєго́ милосе́рдія, Го́споди, я́ко дарова́л єси́ толи́ко тве́рдую і те́плую Засту́пницю і Помо́щницю ро́ду христия́нському, нам неви́димо спребива́ющу, сли́шащу же Тебе́ пою́щих: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї многовіща́ннії, но не богопросве́щеннії, суєсло́в'ять, я́ко поклоне́ніє свято́му о́бразу а́ки би поклоне́ніє і́долу єсть; не разумі́ють бо, я́ко честь, свято́му о́бразу воздава́ємая, на Первообра́зная восхо́дить. Ми же не то́кмо сія́ до́брі ві́дуще, но і от ві́рних челові́к о мно́гих чудотворе́ніїх от ли́ка Богома́тере сли́шаще, і са́мі поклоне́нієм єму́ потре́бная ко вре́менній і ві́чній жи́зні приє́млюще, с весе́лієм Богоро́дице взива́єм:","Ра́дуйся, я́ко от свяще́ннаго ли́ка Твоєго́ чудеса́ ді́ються;","ра́дуйся, я́ко утаї́ся прему́дрость і благода́ть сія́ от му́дрих і разу́мних ві́ка сего́.","Ра́дуйся, я́ко откри́ся та младе́нцем во ві́рі;","ра́дуйся, я́ко прославля́ющих Тя прославля́єши.","Ра́дуйся, я́ко отверга́ющих Тя пред всі́ми посрамля́єши;","ра́дуйся, я́ко от потопле́нія, огня́ і меча́, от смертоно́сния я́зви і от вся́каго зла прибіга́ющих к Тебі́ ізбавля́єши.","Ра́дуйся, я́ко вся болі́зні челові́честії, душе́вния і тіле́сния, ми́лостивно врачу́єши;","ра́дуйся, я́ко пра́ведний гнів Бо́жий на нас Твої́м моле́нієм ско́ро утоля́єши.","Ра́дуйся, я́ко Ти єси́ ти́хоє приста́нище от бур пла́вающим по мо́рю жите́йському;","ра́дуйся, я́ко і по конці́ жите́йськаго пла́ванія на́шего наде́жно приво́диши нас в необурева́ємую страну́ Ца́рствія Христо́ва.","Ра́дуйся, неча́янную ра́дость ві́рним да́рующая."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ челові́ка ні́коєго беззако́нна от заблужде́нія жи́зненнаго путі́ єго́, ди́вноє виді́ніє от пречестни́я іко́ни Твоєя́ показа́ла єси́ єму́, Преблагослове́нная, да, чу́до ви́дя, пока́ється і, із глубини́ гріхо́вния милосе́рдим промишле́нієм Твої́м воздви́гнутий, вопіє́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ ді́вам, Богоро́дице Ді́во, і всім к Тебі́ притека́ющим, і́бо Небесе́ і землі́ Творе́ць, всели́вийся во утро́бу Твою́ і от Тебе́ роди́вийся, яви́ Тя, Присноді́ву, стра́жа ді́вства, чистоти́ і цілому́дрія і сосу́д вся́кия доброді́телі і всіх возглаша́ти Тебі́ научи́:","Ра́дуйся, сто́лпе і огражде́ніє ді́вства;","ра́дуйся, чистоти́ і цілому́дрія незри́мая Охрани́тельнице.","Ра́дуйся, до́брая ді́вам Наста́внице;","ра́дуйся, неві́ст блага́я Украси́тельнице і Спору́чнице.","Ра́дуйся, всежела́нноє соверше́ніє благи́х супру́жеств;","ра́дуйся, ма́терей дітородя́щих ско́роє разріше́ніє.","Ра́дуйся, младе́нцев воспита́ніє і благода́тноє охране́ніє;","ра́дуйся, безча́дних роди́телей плода́ми ві́ри і Ду́ха веселя́щая.","Ра́дуйся, ма́терей скорб'я́щих утіше́ніє;","ра́дуйся, та́йноє весе́ліє чи́стих дів і вдови́ць.","Ра́дуйся, неча́янную ра́дость ві́рним да́рующая."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє принося́ще Ті, недосто́йнії, про́сим Тебе́, Ді́во Богоро́дице: не пре́зри гла́са рабо́в Твої́х, к Тебі́ бо в напа́стіх і ско́рбіх прибіга́єм і пред Тобо́ю в біда́х на́ших сле́зи пролива́єм, пою́ще: Аллилу́я."]},{"h":"Ікос 11","ps":["Светопода́тельную свіщу́, су́щим во тьмі гріха́ і юдо́лі пла́ча яви́вшуюся, зрим Святу́ю Ді́ву; духо́вний бо огнь моли́тв Свої́х, наставле́нія і утіше́нія возжига́ющи, приво́дить к Сві́ту Невече́рнему всіх, воззва́нії почита́ющих Ю си́ми:","Ра́дуйся, Луче́ от Со́лнця Пра́вди, Христа́ Бо́га на́шего;","ра́дуйся, нечи́стую со́вість просвіща́ющая.","Ра́дуйся, та́йная і неудо́б предви́дінная вся до́брі ві́дущая і і́мже подоба́єть сказу́ющая;","ра́дуйся, лжи́вих прови́дцев і су́єтная гада́нія посрамля́ющая.","Ра́дуйся, в час недоумі́ній мисль бла́гу на се́рдці полага́ющая;","ра́дуйся, в пості́, моли́тві і богоми́слії пребива́ющим при́сно спребива́ющая.","Ра́дуйся, ві́рних па́стирей Це́ркве ободря́ющая і вразумляющая;","ра́дуйся, богобоя́зненних і́ноков і і́нокинь при́сноє утіше́ніє.","Ра́дуйся, ка́ющихся пред Бо́гом грі́шников непости́дная Засту́пнице;","ра́дуйся, всіх христия́н те́плая Хода́тайце.","Ра́дуйся, неча́янную ра́дость ві́рним да́рующая."]},{"h":"Кондак 12","ps":["Благода́ть Боже́ственную іспроси́ нам у Си́на Твоєго́ і Бо́га, простри́ нам ру́ку по́мощі, отжени́ от нас вся́каго врага́ і супоста́та, умири́ на́шу жизнь, да не поги́бнем лю́ті, без покая́нія, но прийми́ нас во ві́чния кро́ви, Богороди́тельнице, да ра́дующеся поє́м Бо́гу, Тобо́ю нас спаса́ющему: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще неізрече́нноє Ма́тернєє Твоє́ милосе́рдіє к челові́ку беззако́нну, восхваля́єм Тя всі, я́ко тве́рдую Предста́тельницю за нас, грі́шних, і поклоня́ємся Тебі́, о нас моля́щейся; ві́руєм бо і упова́єм, я́ко іспро́сиши у Си́на Твоєго́ і Бо́га блага́я вре́менная і ві́чная всім, с любо́вію вопію́щим Ті си́це:","Ра́дуйся, всіх наві́тов і іскуше́ній, от ми́ра, пло́ті і дия́вола находя́щих, попра́ніє;","ра́дуйся, неча́ємоє примире́ніє ожесточе́нно вражду́ющих.","Ра́дуйся, недові́домоє ісправле́ніє нераска́янних грі́шников;","ра́дуйся, ізнемога́ющих от уни́нія і печа́лі ско́рая Уті́шительнице.","Ра́дуйся, благода́тію смире́нія і терпі́нія нас снабдіва́ющая;","ра́дуйся, клятвопреступле́ній і непра́ведних стяжа́ній всенаро́дноє обличе́ніє.","Ра́дуйся, от дома́шнія бра́ні і вражди́ єдинокро́вния ми́ром і любо́вію огражда́ющая;","ра́дуйся, от па́губних начина́ній і несми́сленних пожела́ній нас незри́мо отвраща́ющая.","Ра́дуйся, во благи́х наме́реніїх на́ших при́сная Споспі́шнице;","ра́дуйся, в час кончи́ни всім нам Помо́щнице.","Ра́дуйся, неча́янную ра́дость ві́рним да́рующая."]},{"h":"Кондак 13","ps":["О Всепі́тая Ма́ти, Невмісти́маго Бо́га во чре́ві вмісти́вшая і Ра́дость всему́ ми́ру роди́вшая! Ни́нішнєє прийми́ пі́ніє, вся на́ша печа́лі на ра́дость преложи́ і от вся́кия ізба́ви напа́сти всіх і бу́дущия ізми́ му́ки, о Тебі́ вопію́щих: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгели і пра́ведних ду́ші удиви́шася, єгда́ предста́ла єси́ пред Си́ном Твої́м і Бо́гом і мно́гим моле́нієм хода́тайствовала єси́ о челові́ці, при́сно во грісі́х пребива́ющем; ми же, очи́ма ві́ри толи́коє Твоє́ благоутро́біє зря́ще, со умиле́нієм взива́єм Ті си́це:","Ра́дуйся, моли́тви всіх христия́н приє́млющая;","ра́дуйся, і са́мих отча́янних грі́шников моле́нія не отверга́ющая.","Ра́дуйся, к Си́ну Твоєму́ о них предста́тельствующая;","ра́дуйся, неча́янную ра́дость спасе́нія їм подаю́щая.","Ра́дуйся, предста́тельством Твої́м весь мир спаса́ющая;","ра́дуйся, вся на́ша печа́лі утоля́ющая.","Ра́дуйся, Ма́ти всіх Бо́га, озло́бленних ду́ші утіша́ющая;","ра́дуйся, житіє́ на́ше до́брі устроя́ющая.","Ра́дуйся, ізбавле́ніє от гріхо́во всім челові́ком прине́сшая;","ра́дуйся, Ра́дость всему́ ми́ру роди́вшая.","Ра́дуйся, неча́янную ра́дость ві́рним да́рующая."]},{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́в Бо́жієй Ма́тері і Цари́ці, яви́вшейся іногда́ к челові́ку беззако́нну, во є́же отврати́ти єго́ от путі́ нече́стія, благода́рственноє пі́ніє прино́сим Ті, Богороди́тельнице; Ти же, я́ко іму́щая милосе́рдіє неізрече́нноє, от вся́ких нас бід і гріхо́в свободи́, да зове́м Ті:","Ра́дуйся, неча́янную ра́дость ві́рним да́рующая."]},{"h":"Молитва","ps":["О Пресвята́я Ді́во, Всеблага́го Си́на Ма́ти Всебла́гая, гра́да Москви́ Покрови́тельнице, всіх су́щих во грісі́х, ско́рбіх, біда́х і болі́зніх Ві́рная Предста́тельнице і Засту́пнице! Прийми́ моле́бноє пі́ніє сіє́ от нас, недосто́йних раб Твої́х, Тебі́ возноси́моє, і я́коже дре́вле грі́шника, на всяк день мно́гажди пред честно́ю іко́ною Твоє́ю моли́вшагося, не презрі́ла єси́, но дарова́ла єси́ єму́ неча́янную ра́дость покая́нія і преклони́ла єси́ Си́на Твоєго́ мно́гим і усе́рдним к Нему́ хода́тайством ко проще́нію сего́ грі́шнаго і заблу́ждшагося, та́ко і ни́ні не пре́зри моле́нія нас, недосто́йних рабо́в Твої́х, і умоли́ Си́на Твоєго́ і Бо́га на́шего, да і всім нам, с ві́рою і умиле́нієм покланя́ющимся пред цільбоно́сним о́бразом Твої́м, да́руєть неча́янную по коєго́ждо потре́бі ра́дость: грі́шником, погря́зшим во глубині́ зол і страсте́й,— вседі́йственноє вразумле́ніє, покая́ніє і спасе́ніє; су́щим в ско́рбіх і печа́ліх — утіше́ніє; обріта́ющимся в біда́х і озлобле́ніїх — соверше́нноє сих ізби́тіє; малоду́шним і ненаді́ждним — наде́жду і терпі́ніє; в ра́дості і ізоби́лії живу́щим — непреста́нноє Благоді́телю Бо́гу благодаре́ніє; бе́дствующим — милосе́рдіє; су́щим в болі́зні і долгонеду́жії і оста́вленним врача́ми — неча́ємоє ісціле́ніє і укріпле́ніє; іжди́вшим от неду́га ум — ума́ возвраще́ніє і обновле́ніє; отходя́щим во ві́чную і несконча́ємую жизнь — па́м'ять сме́ртную, умиле́ніє і сокруше́ніє о грісі́х, дух бодр і тве́рдую на милосе́рдіє Судії́ наде́жду. О Госпожі́ Пресвята́я! Умилосе́рдися ко всім, чту́щим всечестно́є і́м'я Твоє́, і всім яви́ всемо́щний покро́в Твой і заступле́ніє; во благоче́стії, чистоті́ і честні́м жи́тельстві пребива́ющия до послі́дняго їх сконча́нія во бла́гости соблюди́; зли́я бла́гі сотвори́; заблу́ждшия на путь пра́вий наста́ви; вся́кому ді́лу благо́му і Си́ну Твоєму́ уго́дному споспі́шествуй; вся́коє ді́ло зло́є і богопроти́вноє разруши́; в недоумі́нії і тру́дних і опа́сних обстоя́ніїх обріта́ющимся незри́мую по́мощ і вразумле́ніє с Небесе́ низпосли́; от іскуше́ній, собла́знов і поги́белі спаси́; от всіх злих челові́к і от враго́во ви́димих і неви́димих защити́ і сохрани́; пла́вающим спла́вай; путеше́ствующим спутеше́ствуй; су́щим в нужді́ і гла́ді бу́ди Пита́тельниця; неіму́щим кро́ва і приста́нища бу́ди покро́в і прибі́жище; наги́м пода́ждь одія́ніє; оби́димим і непра́ведно гони́мим — заступле́ніє; клевету́, поноше́ніє і хуле́ніє терп'я́щия незри́мо оправда́й; клеветники́ і хули́телі пред всі́ми обличи́; ожесточе́нно вражду́ющим неча́ємоє пода́ждь примире́ніє, і всім нам друг ко дру́гу любо́в, мир і благоче́стіє і здра́віє с долгоде́нствієм. Супру́жества в любві́ і єдиноми́слії сохрани́; супру́ги, во вражді́ і разділе́нії су́щия, умири́, соєдини́ я друг ко дру́гу і положи́ їм сою́з любве́ неразруши́мий; ма́терем, ді́ти родя́щим, ско́роє пода́ждь разріше́ніє; младе́нці воспита́й; ю́ния уцілому́дри, отве́рзи їм ум к восприя́тію вся́каго поле́знаго уче́нія, стра́ху Бо́жию, воздержа́нію і трудолю́бію наста́ви; от дома́шнія бра́ні і вражди́ єдинокро́вних ми́ром і любо́вію огради́. Безма́терніх сиро́т бу́ди Ма́тер, от вся́каго поро́ка і скве́рни отврати́ я і всему́ благо́му і Богоуго́дному научи́, прельще́нния же і во гріх і нечистоту́ па́дшия, скве́рну гріха́ от'я́вши, із бе́здни поги́белі ізведи́. Вдов бу́ди Уті́шительниця і Помо́щниця, ста́рости бу́ди жезл, от внеза́пния сме́рті без покая́нія всіх нас ізба́ви, і всім нам христия́нськую кончи́ну живота́ на́шего, безболі́зненну, непости́дну, ми́рну і до́брий отві́т на стра́шнім Суди́щі Христо́ві да́руй. Преста́вльшіяся во ві́рі і покая́нії от житія́ сего́ со А́нгели і всі́ми святи́ми жи́ти сотвори́, сконча́вшимся внеза́пною сме́ртію ми́лостива би́ти Си́на Твоєго́ умоли́, і о всіх усо́пших, і́же не і́муть сро́дников, о упокоє́нії їх Си́на Твоєго́ умоля́ющих, Сама́ бу́ди непреста́нная і те́плая Моли́твенниця і Хода́тайця, да всі на Небесі́ і на землі́ ві́дять Тя, я́ко тве́рдую і непости́дную Предста́тельницю ро́да христия́нськаго, і, ві́дуще, сла́в'ять Тя і Тобо́ю Си́на Твоєго́, со Безнача́льним Єго́ Отце́м і Єдиносу́щним Єго́ Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Днесь, ві́рнії лю́діє / духо́вно торжеству́єм, / прославля́юще Засту́пницю усе́рдную ро́да христия́нськаго / і притека́юще к пречи́стому Єя́ о́бразу, взива́єм си́це: / о, Преми́лостивая Влади́чице Богоро́дице, / пода́ждь нам неча́янную ра́дость, / обремене́нним гріхи́ і скорбми́ мно́гими, / і ізба́ви нас от вся́каго зла, / моля́щи Си́на Твоєго́, Христа́ Бо́га на́шего, // спасти́ ду́ші на́ша."]},{"h":"Кондак, глас 6","ps":["Не і́мами іни́я по́мощі, / не і́мами іни́я наде́жди, / ра́зві Тебе́, Влади́чице. / Ти нам помози́, / на Тебі́ наді́ємся / і Тобо́ю хва́лимся, / Твої́ бо єсьми́ раби́, // да не постиді́мся."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтем о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притека́ющим."]}],"notes":[]}];
export default D;
